      if (!/^\d{4}-\d{2}$/.test(normalized.endMonth)) normalized.endMonth = '';
      if (!/^\d{4}-\d{2}$/.test(normalized.createdMonthKey)) normalized.createdMonthKey = normalized.startMonth;
      if (!/^\d{4}-\d{2}$/.test(normalized.anchorMonthKey)) normalized.anchorMonthKey = normalized.startMonth;
