      const override = subscriptionStatusOverrideForMonthKey(subscription, monthKey);
      if (override === '-') return '-';
      if (override === 'paid') return 'paid';
      if (subscriptionHasMatchedPaymentForMonthKey(subscription, monthKey)) return 'paid';
