      const actualEntries = entries.filter(function(entry) { return entry.fixedPaid; });
      const paidEntries = entries.filter(function(entry) { return entry.status === 'paid'; });
      const plannedTotal = plannedEntries.reduce(function(sum, entry) { return sum + Math.max(Number(entry.amount || 0), 0); }, 0);
      const actualTotal = actualEntries.reduce(function(sum, entry) { return sum + Math.max(Number(entry.amount || 0), 0); }, 0);
      // Display-only total: includes ledger-matched paid subscriptions because the
      // matching CSV/PDF/manual transaction is already counted in Currently.
