    function categoryIconGroups() {
      return categoryIconOptions().reduce(function(groups, option) {
        const group = option.group || 'Other';
        if (!groups[group]) groups[group] = [];
        groups[group].push(option);
        return groups;
      }, {});
    }

    function categoryIconRecentKeys(rootState) {
      ensureCategoryMeta(rootState || state);
      return (rootState || state).categoryIconRecent
        .map(sanitizeCategoryIconKey)
        .filter(Boolean)
        .filter(function(iconKey, index, list) { return list.indexOf(iconKey) === index; })
        .slice(0, 3);
    }

    function recordCategoryIconRecent(iconKey) {
      const cleanIcon = sanitizeCategoryIconKey(iconKey);
      if (!cleanIcon) return;
      ensureCategoryMeta(state);
      state.categoryIconRecent = [cleanIcon].concat(categoryIconRecentKeys(state).filter(function(key) {
        return key !== cleanIcon;
      })).slice(0, 3);
      saveState(state);
    }

    function renderManageCategoryIconSelect(kind, group, sourceMap) {
      const selected = getCategoryIcon(kind, group, sourceMap);
      const safeKind = escapeHtml(kind);
      const cleanGroup = cleanGroupName(group);
      const safeGroup = escapeHtml(cleanGroup);
      const selectId = 'manageCategoryIconSelect-' + safeKind + '-' + safeGroup.replace(/[^a-z0-9_-]+/gi, '-');
      const recentKeys = categoryIconRecentKeys(state);
      const recentSet = recentKeys.reduce(function(map, key) {
        map[key] = true;
        return map;
      }, {});
      const recentOptions = recentKeys.map(categoryIconOption).filter(Boolean);
      const grouped = categoryIconOptions().reduce(function(groups, option) {
        if (recentSet[option.key]) return groups;
        const groupName = option.group || 'Other';
        if (!groups[groupName]) groups[groupName] = [];
        groups[groupName].push(option);
        return groups;
      }, {});
      const optionMarkup = function(option) {
        return '<option value="' + escapeHtml(option.key) + '"' + (option.key === selected ? ' selected' : '') + '>' + escapeHtml(option.emoji + ' ' + option.label) + '</option>';
      };
      const options = ['<option value=""' + (selected ? '' : ' selected') + '>+ No icon</option>'];
      if (recentOptions.length) {
        options.push('<optgroup label="Recently used">' + recentOptions.map(optionMarkup).join('') + '</optgroup>');
      }
      Object.keys(grouped).forEach(function(groupLabel) {
        options.push('<optgroup label="' + escapeHtml(groupLabel) + '">' + grouped[groupLabel].map(optionMarkup).join('') + '</optgroup>');
      });
      const buttonLabel = selected ? ('Change icon for ' + cleanGroup) : ('Choose icon for ' + cleanGroup);
      const currentMarkup = selected ? categoryIconMarkup(selected) : '<span aria-hidden="true">+</span>';
      return '<div class="manage-category-icon-picker" title="' + escapeHtml(buttonLabel) + '">' +
        '<div class="manage-category-icon-current' + (selected ? '' : ' is-empty') + '" aria-hidden="true">' + currentMarkup + '</div>' +
        '<select id="' + selectId + '" class="manage-category-icon-select" aria-label="' + escapeHtml(buttonLabel) + '" data-category-icon-select-kind="' + safeKind + '" data-category-icon-select-group="' + safeGroup + '">' + options.join('') + '</select>' +
      '</div>';
    }

    function ensureGlobalInlineTooltip() {
      let tooltip = document.getElementById('globalInlineInfoTooltip');
      if (tooltip) return tooltip;
      tooltip = document.createElement('div');
      tooltip.id = 'globalInlineInfoTooltip';
      tooltip.className = 'inline-info-tooltip';
      tooltip.setAttribute('role', 'tooltip');
      document.body.appendChild(tooltip);
      return tooltip;
    }

    function setInlineInfoOpen(wrap, isOpen) {
      if (!wrap) return;
      const trigger = wrap.querySelector('[data-inline-info-trigger]');
      const tooltip = ensureGlobalInlineTooltip();
      const open = !!isOpen;
      wrap.setAttribute('data-open', open ? 'true' : 'false');
      wrap.classList.toggle('is-visible', open);
      if (trigger) trigger.setAttribute('aria-expanded', open ? 'true' : 'false');
      if (!open) {
        if (window.__activeInlineInfoWrap === wrap) window.__activeInlineInfoWrap = null;
        tooltip.classList.remove('is-visible');
        tooltip.style.left = '-9999px';
        tooltip.style.top = '-9999px';
        tooltip.innerHTML = '';
        return;
      }
      if (!trigger) return;
      window.__activeInlineInfoWrap = wrap;
      tooltip.innerHTML = trigger.getAttribute('data-tooltip-html') || '';
      tooltip.classList.add('is-visible');
      updateInlineInfoPosition(wrap);
    }

    function closeInlineInfoTooltips(exceptWrap) {
      document.querySelectorAll('.inline-info-wrap.is-visible, .inline-info-wrap[data-open="true"]').forEach(function(wrap) {
        if (exceptWrap && wrap === exceptWrap) return;
        setInlineInfoOpen(wrap, false);
      });
    }

    function updateInlineInfoPosition(wrap) {
      if (!wrap) return;
      const trigger = wrap.querySelector('[data-inline-info-trigger]');
      const tooltip = ensureGlobalInlineTooltip();
      if (!trigger || !tooltip) return;
      const triggerRect = trigger.getBoundingClientRect();
      const viewportPad = 8;
      const gap = 8;
      tooltip.style.left = '0px';
      tooltip.style.top = '0px';
      const maxWidth = Math.min(260, Math.max(160, window.innerWidth - viewportPad * 2));
      tooltip.style.width = maxWidth + 'px';
      const tipWidth = Math.min(maxWidth, Math.max(tooltip.offsetWidth || 180, 160));
      tooltip.style.width = tipWidth + 'px';
      const tipHeight = Math.max(tooltip.offsetHeight || 36, 24);
      let left = triggerRect.right + gap;
      if (left + tipWidth > window.innerWidth - viewportPad) left = triggerRect.left - tipWidth - gap;
      if (left < viewportPad) left = Math.max(viewportPad, Math.min(triggerRect.left, window.innerWidth - tipWidth - viewportPad));
      let top = triggerRect.top + (triggerRect.height / 2) - (tipHeight / 2);
      if (top + tipHeight > window.innerHeight - viewportPad) top = window.innerHeight - tipHeight - viewportPad;
      if (top < viewportPad) top = viewportPad;
      tooltip.style.left = Math.round(left) + 'px';
      tooltip.style.top = Math.round(top) + 'px';
    }

    function categoryPaletteColor(label) {
      const map = {
        "Living Costs": "#8fb6ff",
        "Multimedia": "#6f7bf7",
        "Essentials": "#7fd39a",
        "Transport": "#53b978",
        "Life-Upgrades": "#f5b56b",
        "Leasure": "#b79268",
        "Fish and Chips Crypto": "#8a809f",
        "Financial": "#b68f86",
        "Crypto": "#5f7d8f",
        "ETF": "#6f8d9f",
        "Savings": "#7ea090"
      };
      return map[label] || "#6f879a";
    }

    function piePalette(items) {
      return (items || []).map(function(item) {
        return categoryPaletteColor(item.label);
      });
    }

    function chartBreakdown(month) {
      const subscriptionImpact = derivedSubscriptionImpactForMonth(month);
      const expenseGroupMap = new Map();

      groupRows(month.expenses).forEach(function(pair) {
        const group = pair[0];
        const rows = pair[1];
        const key = cleanGroupName(group);
        expenseGroupMap.set(key, {
          label: group,
          value: rows.reduce((sum, row) => sum + rowActual(row), 0),
          type: "expense_group",
          key: group
        });
      });

      Object.keys(subscriptionImpact.actualByGroup || {}).forEach(function(group) {
        const key = cleanGroupName(group);
        const manualPaidActual = Number(subscriptionImpact.actualByGroup[group] || 0);
        if (!(manualPaidActual > 0)) return;
        const existing = expenseGroupMap.get(key);
        if (existing) existing.value += manualPaidActual;
        else expenseGroupMap.set(key, { label: group, value: manualPaidActual, type: "expense_group", key: group });
      });

      const expenseGroups = Array.from(expenseGroupMap.values()).filter(item => item.value > 0);

      const savingsRows = month.savings || [];
      const cryptoMatcher = /crypto|btc|bitcoin|eth|ethereum|egld|pol|polygon/i;
      const etfMatcher = /etf|index/i;
      const cryptoTotal = savingsRows.filter(row => cryptoMatcher.test(String(row.name || ""))).reduce((sum, row) => sum + rowActual(row), 0);
      const etfTotal = savingsRows.filter(row => etfMatcher.test(String(row.name || ""))).reduce((sum, row) => sum + rowActual(row), 0);
      const savingsTotal = savingsRows.reduce((sum, row) => sum + rowActual(row), 0);

      const namedSavings = [];
      if (cryptoTotal > 0) namedSavings.push({ label: "Crypto", value: cryptoTotal, type: "savings_filter", key: "crypto", matcher: cryptoMatcher });
      if (etfTotal > 0) namedSavings.push({ label: "ETF", value: etfTotal, type: "savings_filter", key: "etf", matcher: etfMatcher });

      const usedByNamed = cryptoTotal + etfTotal;
      const otherSavings = Math.max(0, savingsTotal - usedByNamed);
      if (otherSavings > 0) namedSavings.push({ label: "Savings", value: otherSavings, type: "savings_filter", key: "savings", matcher: /.*/ });

      return [...expenseGroups, ...namedSavings].filter(item => item.value > 0);
    }

    let spendingChartResizeObserver = null;
    let spendingChartResizeRaf = 0;
    let spendingChartObservedSize = "";
    let spendingChartHoverIndex = -1;

    function prepareResponsiveSpendingCanvas(canvas) {
      const tile = canvas.closest(".distribution-chart-tile") || canvas.parentElement;
      const rect = tile ? tile.getBoundingClientRect() : canvas.getBoundingClientRect();
      const fallback = 320;
      const availableWidth = Math.max(0, Math.floor(rect.width || fallback));
      const availableHeight = Math.max(0, Math.floor(rect.height || fallback));
      const cssSize = Math.max(160, Math.min(availableWidth || fallback, availableHeight || fallback));
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const pixelSize = Math.max(1, Math.round(cssSize * dpr));

      canvas.style.width = cssSize + "px";
      canvas.style.height = cssSize + "px";
      if (canvas.width !== pixelSize || canvas.height !== pixelSize) {
        canvas.width = pixelSize;
        canvas.height = pixelSize;
      }

      const ctx = canvas.getContext("2d");
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      return { ctx, w: cssSize, h: cssSize };
    }

    function scheduleSpendingChartResize() {
      if (spendingChartResizeRaf) cancelAnimationFrame(spendingChartResizeRaf);
      spendingChartResizeRaf = requestAnimationFrame(function() {
        spendingChartResizeRaf = 0;
        renderSpendingChart(getActiveMonth());
      });
    }

    function bindSpendingChartShellResize() {
      if (typeof ResizeObserver === "undefined") return;
      const shell = document.querySelector(".overview-chart-card .distribution-stage");
      if (!shell) return;
      if (spendingChartResizeObserver) spendingChartResizeObserver.disconnect();
      spendingChartResizeObserver = new ResizeObserver(function(entries) {
        const entry = entries && entries[0];
        if (!entry) return;
        const width = Math.round(entry.contentRect.width || 0);
        const height = Math.round(entry.contentRect.height || 0);
        const key = width + "x" + height;
        if (key && key !== spendingChartObservedSize) {
          spendingChartObservedSize = key;
          scheduleSpendingChartResize();
        }
      });
      spendingChartResizeObserver.observe(shell);
    }

    function renderSpendingChart(month) {
      const canvas = document.getElementById("spendingPie");
      const legend = document.getElementById("spendingLegend");
      if (!canvas || !legend) return;
      bindSpendingChartShellResize();
      const canvasMetrics = prepareResponsiveSpendingCanvas(canvas);
      const ctx = canvasMetrics.ctx;
      const w = canvasMetrics.w;
      const h = canvasMetrics.h;
      const cx = w / 2;
      const cy = h / 2;
      const outerR = Math.min(w, h) * 0.38;
      const innerR = outerR * 0.58;
      const depth = 0;
      const isDarkTheme = document.documentElement.getAttribute('data-theme') === 'dark' || document.body.classList.contains('dark-mode');
      ctx.clearRect(0, 0, w, h);

      const items = chartBreakdown(month);
      const total = items.reduce((sum, item) => sum + item.value, 0);
      const colors = piePalette(items);

      if (!items.length || total <= 0) {
        legend.dataset.legendCount = "0";
        legend.classList.remove("legend-count-compact", "legend-count-dense", "legend-count-ultra");
        legend.innerHTML = '<div class="chart-empty">Add some expenses or savings entries to see the chart.</div>';
        ctx.save();
        ctx.shadowColor = "rgba(15,23,42,0.12)";
        ctx.shadowBlur = 18;
        ctx.shadowOffsetY = 8;
        ctx.fillStyle = "#dbe4f0";
        ctx.beginPath();
        ctx.arc(cx, cy, Math.min(w, h) * 0.30, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
        canvas.onclick = null;
        canvas.onmousemove = null;
        canvas.onmouseleave = null;
        spendingChartHoverIndex = -1;
        return;
      }

      function shade(hex, amount) {
        const value = String(hex || "#94a3b8").replace("#", "");
        const full = value.length === 3 ? value.split("").map(ch => ch + ch).join("") : value;
        const num = parseInt(full, 16);
        const r = Math.max(0, Math.min(255, (num >> 16) + amount));
        const g = Math.max(0, Math.min(255, ((num >> 8) & 255) + amount));
        const b = Math.max(0, Math.min(255, (num & 255) + amount));
        return `rgb(${r},${g},${b})`;
      }

      function drawSegment(start, end, radiusOuter, radiusInner, offsetY, fillStyle, offsetX = 0, segmentOffsetY = 0) {
        const sx = cx + offsetX;
        const sy = cy + segmentOffsetY + offsetY;
        ctx.beginPath();
        ctx.arc(sx, sy, radiusOuter, start, end);
        ctx.arc(sx, sy, radiusInner, end, start, true);
        ctx.closePath();
        ctx.fillStyle = fillStyle;
        ctx.fill();
      }

      function roundedRect(x, y, width, height, radius) {
        const r = Math.min(radius, width / 2, height / 2);
        ctx.beginPath();
        ctx.moveTo(x + r, y);
        ctx.lineTo(x + width - r, y);
        ctx.quadraticCurveTo(x + width, y, x + width, y + r);
        ctx.lineTo(x + width, y + height - r);
        ctx.quadraticCurveTo(x + width, y + height, x + width - r, y + height);
        ctx.lineTo(x + r, y + height);
        ctx.quadraticCurveTo(x, y + height, x, y + height - r);
        ctx.lineTo(x, y + r);
        ctx.quadraticCurveTo(x, y, x + r, y);
        ctx.closePath();
      }

      function segmentOffsetFor(start, end, idx) {
        if (idx !== spendingChartHoverIndex) return { x: 0, y: 0, distance: 0, mid: (start + end) / 2 };
        const mid = (start + end) / 2;
        const distance = Math.max(7, Math.round(outerR * 0.065));
        return { x: Math.cos(mid) * distance, y: Math.sin(mid) * distance, distance, mid };
      }

      const hitRegions = [];
      let startAngle = -Math.PI / 2;

      // modern soft base halo
      ctx.save();
      const halo = ctx.createRadialGradient(cx, cy, innerR * 0.7, cx, cy, outerR * 1.18);
      halo.addColorStop(0, isDarkTheme ? "rgba(129,140,248,0.04)" : "rgba(99,102,241,0.05)");
      halo.addColorStop(1, isDarkTheme ? "rgba(15,23,42,0.00)" : "rgba(30,64,120,0.00)");
      ctx.fillStyle = halo;
      ctx.beginPath();
      ctx.arc(cx, cy, outerR * 1.14, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();

      // top face with a subtle modern highlight
      items.forEach((item, idx) => {
        const angle = (item.value / total) * Math.PI * 2;
        const endAngle = startAngle + angle;
        const offset = segmentOffsetFor(startAngle, endAngle, idx);
        const grad = ctx.createRadialGradient((cx + offset.x) - outerR * 0.35, (cy + offset.y) - outerR * 0.45, innerR * 0.2, cx + offset.x, cy + offset.y, outerR * 1.1);
        grad.addColorStop(0, shade(colors[idx % colors.length], 24));
        grad.addColorStop(0.65, colors[idx % colors.length]);
        grad.addColorStop(1, shade(colors[idx % colors.length], -14));
        drawSegment(startAngle, endAngle, outerR, innerR, 0, grad, offset.x, offset.y);
        hitRegions.push({ start: startAngle, end: endAngle, item, idx, mid: offset.mid });
        startAngle = endAngle;
      });

      // inner cutout and center label
      ctx.save();
      ctx.shadowColor = isDarkTheme ? "rgba(0,0,0,0.32)" : "rgba(15,23,42,0.10)";
      ctx.shadowBlur = 14;
      ctx.shadowOffsetY = 5;
      ctx.fillStyle = isDarkTheme ? "rgba(15,23,42,0.96)" : "rgba(255,255,255,0.96)";
      ctx.beginPath();
      ctx.arc(cx, cy, innerR * 0.96, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();

      function fitCanvasText(text, preferredPx, minPx, weight, family, maxWidth) {
        let size = preferredPx;
        while (size > minPx) {
          ctx.font = weight + " " + size + "px " + family;
          if (ctx.measureText(text).width <= maxWidth) break;
          size -= 1;
        }
        return Math.max(size, minPx);
      }

      const centerMaxWidth = innerR * 1.50;
      const centerLabelSize = fitCanvasText(
        "Total",
        Math.max(10, Math.round(outerR * 0.070)),
        8,
        "800",
        "Geist, ui-sans-serif, sans-serif",
        centerMaxWidth
      );
      const centerValue = currency(total);
      const centerValueSize = fitCanvasText(
        centerValue,
        Math.max(16, Math.round(outerR * 0.112)),
        11,
        "850",
        "Geist Mono, ui-monospace, monospace",
        centerMaxWidth
      );

      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillStyle = isDarkTheme ? "#94a3b8" : "#64748b";
      ctx.font = "800 " + centerLabelSize + "px Geist, ui-sans-serif, sans-serif";
      ctx.fillText("Total", cx, cy - Math.round(innerR * 0.22));
      ctx.fillStyle = isDarkTheme ? "#f8fafc" : "#122033";
      ctx.font = "850 " + centerValueSize + "px Geist Mono, ui-monospace, monospace";
      ctx.fillText(centerValue, cx, cy + Math.round(innerR * 0.16));
      ctx.textBaseline = "alphabetic";

      if (spendingChartHoverIndex >= 0 && hitRegions[spendingChartHoverIndex]) {
        const region = hitRegions[spendingChartHoverIndex];
        const label = String(region.item && region.item.label ? region.item.label : "");
        const pct = total > 0 ? (region.item.value / total) * 100 : 0;
        const tagText = label + " · " + pct.toFixed(1) + "%";
        const labelSize = Math.max(10, Math.round(outerR * 0.052));
        ctx.font = "800 " + labelSize + "px Geist, ui-sans-serif, sans-serif";
        const padX = 9;
        const padY = 6;
        const tagW = Math.min(w - 16, ctx.measureText(tagText).width + padX * 2);
        const tagH = labelSize + padY * 2;
        let tagX = cx + Math.cos(region.mid) * (outerR + Math.max(22, outerR * 0.18)) - tagW / 2;
        let tagY = cy + Math.sin(region.mid) * (outerR + Math.max(22, outerR * 0.18)) - tagH / 2;
        tagX = Math.max(8, Math.min(w - tagW - 8, tagX));
        tagY = Math.max(8, Math.min(h - tagH - 8, tagY));
        ctx.save();
        ctx.shadowColor = "rgba(15,23,42,0.14)";
        ctx.shadowBlur = 14;
        ctx.shadowOffsetY = 6;
        roundedRect(tagX, tagY, tagW, tagH, 999);
        ctx.fillStyle = isDarkTheme ? "rgba(15,23,42,0.96)" : "rgba(255,255,255,0.96)";
        ctx.fill();
        ctx.shadowColor = "transparent";
        ctx.lineWidth = 1;
        ctx.strokeStyle = isDarkTheme ? "rgba(148,163,184,0.26)" : "rgba(111,135,154,0.18)";
        ctx.stroke();
        ctx.fillStyle = isDarkTheme ? "#f8fafc" : "#122033";
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillText(tagText, tagX + tagW / 2, tagY + tagH / 2 + 0.5);
        ctx.restore();
      }

      function chartHitIndex(event) {
        const rect = canvas.getBoundingClientRect();
        const scaleX = w / Math.max(1, rect.width);
        const scaleY = h / Math.max(1, rect.height);
        const x = (event.clientX - rect.left) * scaleX;
        const y = (event.clientY - rect.top) * scaleY;
        const dx = x - cx;
        const dy = y - cy;
        const r = Math.sqrt(dx * dx + dy * dy);
        if (r < innerR || r > outerR + depth + Math.max(12, outerR * 0.08)) return -1;
        let angle = Math.atan2(dy, dx);
        if (angle < -Math.PI / 2) angle += Math.PI * 2;
        const match = hitRegions.find(region => angle >= region.start && angle <= region.end);
        return match ? match.idx : -1;
      }

      canvas.onmousemove = (event) => {
        const nextIndex = chartHitIndex(event);
        if (nextIndex !== spendingChartHoverIndex) {
          spendingChartHoverIndex = nextIndex;
          renderSpendingChart(month);
        }
      };
      canvas.onmouseleave = () => {
        if (spendingChartHoverIndex !== -1) {
          spendingChartHoverIndex = -1;
          renderSpendingChart(month);
        }
      };
      canvas.onclick = (event) => {
        const idx = chartHitIndex(event);
        if (idx >= 0 && items[idx]) drillToChartItem(items[idx]);
      };

      legend.dataset.legendCount = String(items.length);
      legend.classList.toggle("legend-count-compact", items.length >= 7);
      legend.classList.toggle("legend-count-dense", items.length >= 10);
      legend.classList.toggle("legend-count-ultra", items.length >= 13);

      legend.innerHTML = items.map((item, idx) => {
        const pct = total > 0 ? (item.value / total) * 100 : 0;
        const activeClass = idx === spendingChartHoverIndex ? " is-active" : "";
        return `
          <div class="chart-legend-item chart-clickable${activeClass}" data-chart-item="${idx}">
            <span class="chart-swatch" style="background:${colors[idx % colors.length]}"></span>
            <span class="chart-legend-label">${item.label}</span>
            <span class="chart-legend-value"><span class="amount">${currency(item.value)}</span><span class="percent">${pct.toFixed(1)}%</span></span>
          </div>`;
      }).join("");

      legend.querySelectorAll("[data-chart-item]").forEach(el => {
        el.onmouseenter = () => {
          const idx = Number(el.dataset.chartItem);
          if (idx !== spendingChartHoverIndex) {
            spendingChartHoverIndex = idx;
            renderSpendingChart(month);
          }
        };
        el.onmouseleave = () => {
          if (spendingChartHoverIndex !== -1) {
            spendingChartHoverIndex = -1;
            renderSpendingChart(month);
          }
        };
        el.onclick = () => {
          const idx = Number(el.dataset.chartItem);
          drillToChartItem(items[idx]);
        };
      });
    }

    
    

    

    window.addEventListener("resize", function() {
      if (document.getElementById("spendingPie")) scheduleSpendingChartResize();
    });

    function planningBucketOptions(month) {
      const options = [];
      (month.income || []).forEach(function(row) {
        options.push({
          key: "income-row|" + row.name,
          label: "Income / " + row.name,
          current: rowActual(row),
          bucketType: "income"
        });
      });
      (month.savings || []).forEach(function(row) {
        const classification = row.classification === 'investment' ? 'Investment' : 'Savings';
        options.push({
          key: "savings-row|" + row.name,
          label: "Savings / " + row.name + " · " + classification,
          current: rowActual(row),
          bucketType: "savings"
        });
      });
      groupRows(month.expenses || []).forEach(function(entry) {
        const group = entry[0].trim();
        const rows = entry[1];
        options.push({
          key: "expense-group|" + group,
          label: "Expenses / " + group,
          current: rows.reduce(function(sum, row) { return sum + rowActual(row); }, 0),
          bucketType: "expense"
        });
        rows.forEach(function(row) {
          options.push({
            key: "expense-row|" + group + "|" + row.name,
            label: "Expenses / " + group + " / " + row.name,
            current: rowActual(row),
            bucketType: "expense"
          });
        });
      });
      return options;
    }

    function goalKeywordPhrases(goal) {
      return String((goal && goal.matchWords) || '')
        .split(',')
        .map(function(part) { return part.trim(); })
        .filter(function(part) { return part.length >= 1; });
    }

    function goalKeywordTokens(goal) {
      const phrases = goalKeywordPhrases(goal).map(function(part) { return part.toLowerCase(); });
      if (!phrases.length) return [];
      const stopWords = new Set(['fund','funds','goal','goals','saving','savings','save','account','accounts','monthly','rolling','plan','planned','target','money']);
      return Array.from(new Set(phrases
        .flatMap(function(phrase) { return phrase.split(/[^a-z0-9]+/i); })
        .map(function(part) { return part.trim(); })
        .filter(function(part) { return part.length >= 2 && !stopWords.has(part); })
      ));
    }

    function goalMatchesText(goal, text) {
      const tokens = goalKeywordTokens(goal);
      if (!tokens.length) return true;
      const haystack = String(text || '').toLowerCase();
      return tokens.some(function(token) { return haystack.includes(token); });
    }

    function goalCurrentProgressForTargetKey(month, goal) {
      const targetKey = String(goal && goal.targetKey || '');
      if (!targetKey) return 0;
      const parts = targetKey.split('|');
      const scope = parts[0] || '';
      const bucketType = scope.indexOf('income') === 0 ? 'income' : scope.indexOf('savings') === 0 ? 'savings' : 'expenses';
      const pool = bucketType === 'income' ? (month.income || []) : bucketType === 'savings' ? (month.savings || []) : (month.expenses || []);
      const targetGroup = parts[1] || '';
      const targetRowName = parts.slice(2).join('|');
      const matchedRows = pool.filter(function(row) {
        if (scope === 'income-row' || scope === 'savings-row') {
          return String(row.name || '') === targetGroup;
        }
        const groupMatch = cleanGroupName(row.group) === cleanGroupName(targetGroup);
        if (!groupMatch) return false;
        if (scope === 'expense-group') return true;
        return String(row.name || '') === targetRowName;
      });
      const tokens = goalKeywordTokens(goal);
      const useKeywordFilter = tokens.length > 0;
      return matchedRows.reduce(function(sum, row) {
        if (!useKeywordFilter) return sum + rowActual(row);
        const txs = Array.isArray(row.transactions) ? row.transactions : [];
        if (!txs.length) {
          const rowHaystack = [row.note || '', row.name || '', row.group || ''].join(' ');
          return sum + (goalMatchesText(goal, rowHaystack) ? rowActual(row) : 0);
        }
        const filteredTxTotal = txs.reduce(function(txSum, tx) {
          const haystack = [tx.note || '', tx.category || '', row.note || '', row.name || '', row.group || ''].join(' ');
          return goalMatchesText(goal, haystack) ? txSum + Number(tx.amount || 0) : txSum;
        }, 0);
        return sum + filteredTxTotal;
      }, 0);
    }

    function resolveGoalProgressForGoal(month, goal, options) {
      options = options || planningBucketOptions(month);
      const found = options.find(function(opt) { return opt.key === goal.targetKey; }) || null;
      const currentMonthProgress = goalCurrentProgressForTargetKey(month, goal);
      const target = Math.max(0, Number(goal.goalAmount || 0));
      const baseProgress = Number(goal.baseProgress || 0);
      const totalProgress = (goal.goalMode === "rolling" ? baseProgress : 0) + currentMonthProgress;
      const pct = target > 0 ? (totalProgress / target) * 100 : 0;
      return {
        found: found,
        currentMonthProgress: currentMonthProgress,
        totalProgress: totalProgress,
        target: target,
        pct: pct,
        remaining: Math.max(0, target - totalProgress)
      };
    }

    function carryRollingGoalsFrom(sourceMonth) {
      const options = planningBucketOptions(sourceMonth);
      return (sourceMonth.goals || [])
        .filter(function(goal, index) {
          if (goal.goalMode !== "rolling") return false;
          const item = goalPresentationModel(sourceMonth, goal, options, index);
          if (Number(item && item.resolved && item.resolved.pct || 0) >= 100) {
            if (typeof recordCompletedFinancialGoal === 'function') recordCompletedFinancialGoal(sourceMonth, goal, item);
            return false;
          }
          return true;
        })
        .map(function(goal) {
          const resolved = resolveGoalProgressForGoal(sourceMonth, goal, options);
          return Object.assign({}, goal, {
            baseProgress: resolved.totalProgress
          });
        });
    }

    function applyLinkedRollingGoals(month, sourceMonth) {
      if (!month.goalRolloverLink?.sourceMonthName) return;
      const carried = carryRollingGoalsFrom(sourceMonth).map(function(goal) {
        return Object.assign({}, goal, {
          linkedFromMonth: sourceMonth.name
        });
      });
      const nonLinkedGoals = (month.goals || []).filter(function(goal) {
        return goal.linkedFromMonth !== sourceMonth.name;
      });
      month.goals = nonLinkedGoals.filter(function(goal) { return goal.goalMode !== "rolling" || !goal.linkedFromMonth; }).concat(carried);
    }

    function resolveGoalEditTarget(month, goal) {
      if (!goal) return { month: month, goal: null };
      let currentGoal = goal;
      let currentMonth = month;
      const visited = new Set();
      while (currentGoal && currentGoal.linkedFromMonth && !visited.has(currentGoal.linkedFromMonth)) {
        visited.add(currentGoal.linkedFromMonth);
        const sourceMonth = state.months.find(function(m) { return m.name === currentGoal.linkedFromMonth; });
        if (!sourceMonth) break;
        sourceMonth.goals = sourceMonth.goals || [];
        const sourceGoal = sourceMonth.goals.find(function(item) { return item.id === currentGoal.id; });
        if (!sourceGoal) break;
        currentMonth = sourceMonth;
        currentGoal = sourceGoal;
      }
      return { month: currentMonth, goal: currentGoal || goal };
    }

    function syncGoalFieldsAcrossMonths(goalId, fields) {
      if (!goalId || !fields || !Object.keys(fields).length) return;
      state.months.forEach(function(month) {
        month.goals = month.goals || [];
        month.goals.forEach(function(goal) {
          if (goal.id !== goalId) return;
          Object.keys(fields).forEach(function(key) {
            goal[key] = fields[key];
          });
        });
      });
    }

    function goalTrackerIndexState() {
      state.goalTrackerActiveIndexByMonth = state.goalTrackerActiveIndexByMonth || {};
      return state.goalTrackerActiveIndexByMonth;
    }

    function goalTrackerStateFor(month) {
      const monthName = String(month && month.name || '');
      const map = goalTrackerIndexState();
      const goalCount = Array.isArray(month && month.goals) ? month.goals.length : 0;
      let activeIndex = Number(map[monthName] || 0);
      if (!Number.isFinite(activeIndex) || activeIndex < 0) activeIndex = 0;
      if (goalCount <= 0) activeIndex = 0;
      if (goalCount > 0 && activeIndex >= goalCount) activeIndex = goalCount - 1;
      map[monthName] = activeIndex;
      return {
        monthName: monthName,
        map: map,
        goalCount: goalCount,
        activeIndex: activeIndex
      };
    }

    function setGoalTrackerActiveIndex(month, nextIndex) {
      const trackerState = goalTrackerStateFor(month);
      if (!trackerState.monthName) return trackerState.activeIndex;
      let normalizedIndex = Number(nextIndex || 0);
      if (!Number.isFinite(normalizedIndex) || normalizedIndex < 0) normalizedIndex = 0;
      if (trackerState.goalCount <= 0) normalizedIndex = 0;
      if (trackerState.goalCount > 0 && normalizedIndex >= trackerState.goalCount) normalizedIndex = trackerState.goalCount - 1;
      trackerState.map[trackerState.monthName] = normalizedIndex;
      return normalizedIndex;
    }

    function normalizeGoalRecord(month, goal, index) {
      const normalized = goal && typeof goal === 'object' ? goal : {};
      if (!normalized.id) {
        const monthKey = String(month && month.name || 'month').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'month';
        normalized.id = 'goal-' + monthKey + '-' + index;
      }
      normalized.name = String(normalized.name || ('Goal ' + (index + 1)));
      normalized.targetKey = String(normalized.targetKey || '');
      normalized.goalMode = normalized.goalMode === 'rolling' ? 'rolling' : 'monthly';
      normalized.goalAmount = Number.isFinite(Number(normalized.goalAmount)) ? Number(normalized.goalAmount) : 0;
      normalized.baseProgress = Number.isFinite(Number(normalized.baseProgress)) ? Number(normalized.baseProgress) : 0;
      normalized.matchWords = String(normalized.matchWords || '');
      normalized.keywordDraft = String(normalized.keywordDraft || '');
      return normalized;
    }

    function goalPresentationModel(month, goal, goalOptions, index) {
      const normalizedGoal = normalizeGoalRecord(month, goal, index || 0);
      const resolved = resolveGoalProgressForGoal(month, normalizedGoal, goalOptions);
      const safePct = Number.isFinite(resolved.pct) ? resolved.pct : 0;
      const safeProgress = Number.isFinite(resolved.totalProgress) ? resolved.totalProgress : 0;
      const safeRemaining = Number.isFinite(resolved.remaining) ? resolved.remaining : 0;
      const fillPct = Math.min(Math.max(safePct, 0), 100);
      const fillClass = safePct >= 100 ? 'good' : safePct >= 80 ? 'warn' : '';
      const keywordTokens = goalKeywordTokens(normalizedGoal);
      const goalAmount = Math.max(0, Number(normalizedGoal.goalAmount || 0));
      return {
        goal: normalizedGoal,
        resolved: Object.assign({}, resolved, {
          pct: safePct,
          totalProgress: safeProgress,
          remaining: safeRemaining
        }),
        fillPct: fillPct,
        fillClass: fillClass,
        title: String(normalizedGoal.name || 'Goal'),
        sourceLabel: resolved.found && resolved.found.label ? String(resolved.found.label) : 'No source selected',
        modeLabel: normalizedGoal.goalMode === 'rolling' ? 'Cumulative' : 'Current',
        pctLabel: goalAmount > 0 ? safePct.toFixed(1) + '%' : '—',
        remainingLabel: goalAmount > 0 ? currency(safeRemaining) : '—',
        targetLabel: goalAmount > 0 ? currency(goalAmount) : 'No target set',
        keywordSummary: keywordTokens.length
          ? 'Matching entry notes containing: <strong>' + escapeHtml(keywordTokens.join(', ')) + '</strong>'
          : 'No note filter — using all entries from the selected source.'
      };
    }

    function goalTrackerViewModel(month, goalOptions) {
      const goals = Array.isArray(month && month.goals) ? month.goals.filter(function(goal) {
        return goal && typeof goal === 'object';
      }) : [];
      const trackerState = goalTrackerStateFor(month || {});
      const items = goals.map(function(goal, index) {
        return goalPresentationModel(month, goal, goalOptions || [], index);
      }).filter(function(item) {
        return item && item.goal;
      });
      const safeActiveIndex = items.length ? Math.min(Math.max(trackerState.activeIndex, 0), items.length - 1) : 0;
      if (trackerState.activeIndex !== safeActiveIndex) {
        setGoalTrackerActiveIndex(month, safeActiveIndex);
      }
      const activeItem = items[safeActiveIndex] || null;
      return {
        items: items,
        activeIndex: safeActiveIndex,
        activeItem: activeItem,
        hasGoals: items.length > 0,
        hasMultiple: items.length > 1,
        countLabel: items.length > 1 ? ('Goal ' + (safeActiveIndex + 1) + ' of ' + items.length) : 'Single goal'
      };
    }

    if (typeof window !== 'undefined' && typeof window.escapeHtml !== 'function') {
      window.escapeHtml = function(v){
        return String(v == null ? '' : v)
          .replace(/&/g,'&amp;')
          .replace(/</g,'&lt;')
          .replace(/>/g,'&gt;')
          .replace(/"/g,'&quot;')
          .replace(/'/g,'&#39;');
      };
    }

    function renderGoalTrackerPanel(goalTracker, goalOptions) {
      const safeHtml = window.escapeHtml || escapeHtml;
      if (!goalTracker || !goalTracker.hasGoals || !goalTracker.items || !goalTracker.items.length) {
        return '<div class="fg-workspace-empty"><strong>No active financial goals yet.</strong><br>Use Add goal to create a draft, then Confirm goal to activate it.</div>';
      }
      const optionList = goalOptions || [];
      function optionsFor(goal) {
        return optionList.map(function(opt) {
          return '<option value="' + safeHtml(String(opt.key || '')) + '" ' + (goal.targetKey === opt.key ? 'selected' : '') + '>' + safeHtml(String(opt.label || '')) + '</option>';
        }).join('');
      }
      return '<div class="fg-goal-grid">' + goalTracker.items.map(function(item) {
        const goal = item.goal || {};
        const goalId = safeHtml(String(goal.id || ''));
        const keywordPhrases = goalKeywordPhrases(goal);
        const pct = Math.max(0, Math.min(100, financialGoalPercent(item)));
        const stateText = pct >= 100 ? 'Completed' : (pct < 50 ? 'Lagging' : 'Active');
        const keywordChipMarkup = keywordPhrases.length
          ? keywordPhrases.map(function(phrase, idx) {
              return '<button type="button" class="goal-keyword-chip" data-remove-goal-keyword="' + goalId + '" data-goal-keyword-index="' + idx + '" title="Remove keyword">' + safeHtml(phrase) + '<span>×</span></button>';
            }).join('')
          : '<span class="goal-keyword-empty">No keywords added</span>';
        return '<article class="fg-goal-card ' + financialGoalsStateClass(item) + '">'
          + '<div class="fg-goal-card-head"><div class="fg-goal-title-block"><div class="fg-goal-title-row"><div class="fg-goal-title">' + safeHtml(item.title || 'Untitled goal') + '</div><span class="financial-goals-state-pill ' + financialGoalsStateClass(item) + '">' + safeHtml(stateText) + '</span></div><div class="fg-goal-source">' + safeHtml(item.sourceLabel || 'No source selected') + '</div></div><div class="fg-goal-card-actions"><button class="fg-goal-delete" type="button" data-delete-goal="' + goalId + '" aria-label="Delete goal">×</button></div></div>'
          + '<div class="fg-goal-metrics"><div class="fg-goal-metric"><div class="fg-goal-metric-label">Current</div><div class="fg-goal-metric-value">' + currency(item.resolved.totalProgress) + '</div></div><div class="fg-goal-metric"><div class="fg-goal-metric-label">Target</div><div class="fg-goal-metric-value">' + safeHtml(item.targetLabel) + '</div></div><div class="fg-goal-metric"><div class="fg-goal-metric-label">Remaining</div><div class="fg-goal-metric-value">' + safeHtml(item.remainingLabel) + '</div></div><div class="fg-goal-metric"><div class="fg-goal-metric-label">Progress</div><div class="fg-goal-metric-value">' + safeHtml(item.pctLabel) + '</div></div></div>'
          + '<div class="financial-goals-progress"><div class="financial-goals-progress-fill ' + financialGoalsProgressFillClass(item) + '" style="width:' + pct + '%;"></div></div>'
          + '<div class="fg-goal-form-grid"><div class="fg-goal-field"><label>Name</label><input type="text" data-goal-field="name" data-goal-id="' + goalId + '" value="' + safeHtml(goal.name || '') + '" /></div><div class="fg-goal-field"><label>Source</label><select data-goal-field="targetKey" data-goal-id="' + goalId + '"><option value="">Select bucket</option>' + optionsFor(goal) + '</select></div><div class="fg-goal-field"><label>Goal type</label><select data-goal-field="goalMode" data-goal-id="' + goalId + '"><option value="monthly" ' + (goal.goalMode === 'monthly' ? 'selected' : '') + '>Monthly</option><option value="rolling" ' + (goal.goalMode === 'rolling' ? 'selected' : '') + '>Rolling</option></select></div><div class="fg-goal-field"><label>Goal €</label><input type="number" step="0.01" min="0" data-goal-field="goalAmount" data-goal-id="' + goalId + '" value="' + Number(goal.goalAmount || 0).toFixed(2) + '" /></div><div class="fg-goal-field fg-goal-keywords"><label>Match words (optional)</label><div class="fg-goal-keyword-box"><div class="fg-goal-keyword-chips">' + keywordChipMarkup + '</div><div class="fg-goal-keyword-entry"><input type="text" data-goal-keyword-input="' + goalId + '" value="' + safeHtml(goal.keywordDraft || '') + '" placeholder="Add keyword or phrase" /><button type="button" class="tiny-btn" data-add-goal-keyword="' + goalId + '">Add</button></div></div></div></div>'
          + '<div class="fg-goal-sub">' + item.keywordSummary + '</div>'
          + '</article>';
      }).join('') + '</div>';
    }

    // ── Decision Simulator v3 — signal-driven question pipeline ─────────
    //
    // Reads from 5 insight card models to generate smart questions.
    // Each question has: id, label, framing, buckets (1–2 sliders), tier
    // Tier 1 = issue-triggered (overspend, pace, subscriptions)
    // Tier 2 = opportunity-driven (savings, income, trajectory)
    // Questions are ranked: tier 1 first, then tier 2; max 5 shown.
    // ─────────────────────────────────────────────────────────────────────

    function dsSliderRange(current, histAvg, bucketType) {
      // Dynamic range anchored on current value.
      // Min: 0 always (user can go to zero; it's extreme but valid).
      // Max: larger of 2× current, 1.6× histAvg, or a sensible floor.
      const safeCurrent = Math.max(0, Number(current || 0));
      const safeAvg = histAvg != null ? Math.max(0, Number(histAvg)) : null;
      const dynamicMax = safeAvg
        ? Math.max(safeCurrent * 2, safeAvg * 1.6, 50)
        : Math.max(safeCurrent * 2.2, 50);
      // Step: coarser for larger amounts
      const step = safeCurrent > 500 ? 25 : safeCurrent > 200 ? 10 : safeCurrent > 50 ? 5 : 1;
      return { min: 0, max: Math.ceil(dynamicMax / step) * step, step };
    }

    function dsHistAvgForKey(key, historyMonths) {
      if (!historyMonths.length) return null;
      const vals = historyMonths.map(function(hm) {
        return planningBucketOptions(hm).reduce(function(s, o) {
          return o.key === key ? s + (o.current || 0) : s;
        }, 0);
      }).filter(function(v) { return v > 0; });
      if (!vals.length) return null;
      return vals.reduce(function(a, b) { return a + b; }, 0) / vals.length;
    }

    function dsSavedAmount(month, slotId) {
      const sc = month.scenario;
      if (!sc || !Array.isArray(sc.adjustments)) return null;
      const entry = sc.adjustments.find(function(a) { return a.id === slotId; });
      return entry != null ? Number(entry.amount) : null;
    }

    function dsBucketFromOption(opt, slotId, month, historyMonths) {
      const histAvg = dsHistAvgForKey(opt.key, historyMonths);
      const range = dsSliderRange(opt.current, histAvg, opt.bucketType);
      const saved = dsSavedAmount(month, slotId);
      return {
        id: slotId,
        key: opt.key,
        bucketType: opt.bucketType,
        label: opt.label
          .replace('Expenses / ', '')
          .replace('Savings / ', '')
          .replace('Income / ', '')
          .replace(' · Savings', '')
          .replace(' · Investment', ''),
        current: opt.current,
        histAvg: histAvg,
        min: range.min,
        max: range.max,
        step: range.step,
        value: saved != null ? Math.min(Math.max(saved, range.min), range.max) : opt.current
      };
    }

    function dsComputeOutcomes(buckets, forecast, totalIncome, historyMonths) {
      const baseEnd = Number(forecast.projectedAvailableEnd || 0);
      const remainingDays = Math.max(1, Number(forecast.remainingDays || 1));

      let totalDelta = 0;
      buckets.forEach(function(b) {
        // Use currentDisplay as baseline when set (allocation target), not actual mid-month spend
        const baseline = b.currentDisplay != null ? b.currentDisplay : b.current;
        const diff = b.value - baseline;
        totalDelta += b.bucketType === 'income' ? diff : -diff;
      });

      const adjustedEnd = baseEnd + totalDelta;
      const baseDaily = baseEnd / remainingDays;
      const adjustedDaily = adjustedEnd / remainingDays;
      const dailyDelta = adjustedDaily - baseDaily;

      // Savings headroom: frees up / costs from non-savings buckets
      const nonSavingsDelta = buckets
        .filter(function(b) { return b.bucketType !== 'savings'; })
        .reduce(function(s, b) {
          const baseline = b.currentDisplay != null ? b.currentDisplay : b.current;
          const diff = b.value - baseline;
          return s + (b.bucketType === 'income' ? diff : -diff);
        }, 0);

      // Income coverage shift
      const expenseBucketsCurrent = buckets
        .filter(function(b) { return b.bucketType === 'expense'; })
        .reduce(function(s, b) { return s + (b.currentDisplay != null ? b.currentDisplay : b.current); }, 0);
      const expenseBucketsAdj = buckets
        .filter(function(b) { return b.bucketType === 'expense'; })
        .reduce(function(s, b) { return s + b.value; }, 0);

      const incomeCurrent = buckets.find(function(b) { return b.bucketType === 'income'; });
      const incomeAdj = incomeCurrent
        ? totalIncome - incomeCurrent.current + incomeCurrent.value
        : totalIncome;

      const expCoverageCurrent = incomeAdj > 0 ? (expenseBucketsCurrent / totalIncome) * 100 : null;
      const expCoverageAdj = incomeAdj > 0 ? (expenseBucketsAdj / incomeAdj) * 100 : null;

      return {
        baseEnd, adjustedEnd, totalDelta,
        baseDaily, adjustedDaily, dailyDelta,
        remainingDays,
        nonSavingsDelta,
        expCoverageCurrent, expCoverageAdj,
        incomeAdj, totalIncome
      };
    }

    // Allocation helpers — module-level so both dsGenerateQuestions and renderDecisionSimulator can use them
    function dsAllocationForGroup(month, groupKey) {
      if (!groupKey || typeof groupKey !== 'string') return null;
      const groupName = groupKey.replace('expense-group|', '');
      try {
        const rows = allocationRows(month);
        const row = rows.rows.find(function(r) {
          return (r.label || '').trim().toLowerCase() === groupName.trim().toLowerCase();
        });
        return row ? Math.round(Number(row.allocation || 0)) : null;
      } catch(e) { return null; }
    }

    function dsSavingsAllocation(month) {
      try {
        const rows = allocationRows(month);
        const savRow = rows.rows.find(function(r) { return r.key === 'savings'; });
        return savRow ? Math.round(Number(savRow.allocation || 0)) : null;
      } catch(e) { return null; }
    }

    function dsExpenseLabel(opt, fallbackKey) {
      let raw = '';
      if (opt && typeof opt.label === 'string' && opt.label.trim()) {
        raw = opt.label;
      } else if (typeof fallbackKey === 'string' && fallbackKey) {
        raw = fallbackKey;
      }
      return String(raw || '')
        .replace('Expenses / ', '')
        .replace('Expenses/', '')
        .trim();
    }

    function dsGenerateQuestions(month, historyMonths) {
      const options = planningBucketOptions(month);
      const forecast = monthForecast(month);
      const base = monthBudgetBase(month);
      const totalIncome = (month.income || []).reduce(function(s, r) { return s + rowActual(r); }, 0);

      // Pull signals from insight models — wrapped in try/catch so a partial
      // data month doesn't break the simulator
      let fwm, decision, advisor, burden, mix;
      try { fwm = forecastWidgetModel(month); } catch(e) { fwm = null; }
      try { decision = insightDecisionEngine(month); } catch(e) { decision = null; }
      try { advisor = budgetAdjustmentAdvisor(month); } catch(e) { advisor = null; }
      try { burden = subscriptionBurdenModel(month, base, forecast); } catch(e) { burden = null; }
      try { mix = budgetMixTrackerModel(month); } catch(e) { mix = null; }

      const questions = [];

      // Helper: find bucket option by type / key
      function optByKey(key) { return options.find(function(o) { return o.key === key; }) || null; }

      // All expense groups — includes fixed-only groups (for display)
      function expenseGroups() {
        return options
          .filter(function(o) { return o.bucketType === 'expense' && o.key.indexOf('expense-group|') === 0; })
          .sort(function(a, b) { return (b.current || 0) - (a.current || 0); });
      }

      // Only groups that have at least one variable row — eligible for simulation adjustment
      function simulationVariableExpenseGroups() {
        return expenseGroups().filter(function(g) {
          const groupName = g.key.replace('expense-group|', '');
          const groupExpRows = (month.expenses || []).filter(function(r) {
            return (r.group || '').trim() === groupName;
          });
          // Exclude if ALL rows are fixed (or no rows exist — derived fixed-only via subscriptions)
          if (groupExpRows.length === 0) return false;
          return groupExpRows.some(function(r) { return !r.fixed; });
        });
      }

      function primaryIncomeOpt() {
        return options.find(function(o) { return o.bucketType === 'income'; }) || null;
      }
      function primarySavingsOpt() {
        return options.find(function(o) { return o.bucketType === 'savings'; }) || null;
      }

      // ── Smart offset basket: top-3 ranked variable expense categories ──────
      // Returns array of up to 3 { opt, reason, label, score, allocTarget, allocDelta } sorted best-first
      // allocDelta = this candidate's proportional share of neededGap (weighted by score)
      function dsOffsetBasket(excludeKey, neededGap) {
        const groups = simulationVariableExpenseGroups();
        const decisionRows = decision ? decision.rows : [];
        let candidates = [];
        groups.forEach(function(g) {
          if (excludeKey && g.key === excludeKey) return;
          const allocTarget = dsAllocationForGroup(month, g.key);
          const base = (allocTarget != null && allocTarget > 0) ? allocTarget : g.current;
          // Include if has allocation OR meaningful actual spend
          if (base < 10) return;
          const histAvg = dsHistAvgForKey(g.key, historyMonths);
          const aboveAvg = histAvg && histAvg > 0 ? Math.max(0, g.current - histAvg) : 0;
          const decRow = decisionRows.find(function(r) { return 'expense-group|' + r.key === g.key; });
          const lev = decRow ? Number(decRow.leverScore || 0) : 0;
          // Score on base (allocation or actual), not just actual spend
          const score = aboveAvg * 2.5 + lev * 1.2 + base * 0.4;
          const label = dsExpenseLabel(g, g && g.key);
          let reason = '';
          if (aboveAvg > 5 && histAvg) {
            reason = currency(Math.round(aboveAvg)) + ' above your 3-month average';
          } else if (decRow && decRow.profile && decRow.profile.type === 'repeatable') {
            reason = 'most controllable recurring category';
          } else if (decRow && decRow.capacity > 10) {
            reason = currency(Math.round(decRow.capacity)) + ' of identified capacity';
          } else {
            reason = 'largest flexible category';
          }
          candidates.push({ opt: g, reason: reason, label: label, score: score, allocTarget: allocTarget, base: base, allocDelta: null });
        });
        candidates.sort(function(a, b) { return b.score - a.score; });
        const top3 = candidates.slice(0, 3);

        // Distribute neededGap across top-3 proportionally by score
        if (neededGap && neededGap > 0 && top3.length > 0) {
          const totalScore = top3.reduce(function(s, c) { return s + c.score; }, 0) || 1;
          let remaining = neededGap;
          top3.forEach(function(c, i) {
            if (i === top3.length - 1) {
              // Last candidate gets the remainder to avoid rounding drift
              c.allocDelta = Math.min(remaining, c.base);
            } else {
              const share = Math.round(neededGap * c.score / totalScore);
              c.allocDelta = Math.min(share, c.base);
              remaining -= c.allocDelta;
            }
            c.allocDelta = Math.max(0, c.allocDelta);
          });
        }
        return top3;
      }

      // Q1 — Overspend recovery
      if (decision && decision.liveIssue) {
        const issue = decision.liveIssue;
        const over = Math.max(Number(issue.actualOver || 0), 0);
        const futureRisk = Math.max(Number(issue.futureRisk || 0), 0);
        const groupKey = 'expense-group|' + issue.key;
        const opt = optByKey(groupKey);
        if (opt) {
          const histAvg = dsHistAvgForKey(groupKey, historyMonths);
          const allocAmt = dsAllocationForGroup(month, groupKey);
          // Reference: allocation target (what was budgeted), then histAvg, then current
          const refAmt = (allocAmt != null && allocAmt > 0) ? allocAmt : (histAvg || opt.current);
          const overAmt = refAmt > 0 ? Math.max(0, opt.current - refAmt) : over;
          const recoverAmt = overAmt > 0 ? overAmt : Math.round(futureRisk * 0.7);
          // Use confirmed quick-input if present, else seed at reference (allocation or histAvg)
          const savedQVal = month.scenario && month.scenario.questionKey === 'q-overspend' && month.scenario.quickInputVal != null
            ? month.scenario.quickInputVal : null;
          const targetAmt = savedQVal != null ? savedQVal : Math.round(refAmt);
          const bucket = dsBucketFromOption(opt, 'b-overspend-main', month, historyMonths);
          bucket.currentDisplay = refAmt > 0 ? refAmt : undefined;
          bucket.value = targetAmt;
          bucket.snapValue = Math.round(refAmt);
          bucket.snapLabel = allocAmt != null ? '→ allocation' : '→ avg';
          const overPct = refAmt > 0 ? Math.round((opt.current / refAmt - 1) * 100) : 0;
          questions.push({
            id: 'q-overspend',
            tier: 1,
            badge: { label: 'Urgent', tone: 'urgent' },
            label: issue.key + ' is running over — how much can you recover by cutting it?',
            currentNote: overPct > 0 ? overPct + '% above ' + (allocAmt != null ? 'allocation' : 'average') : (recoverAmt > 0 ? 'Recovery potential: ' + currency(recoverAmt) : ''),
            framing: 'Target mode — set the amount you want to reach. ' + (recoverAmt > 0 ? 'Bringing it back recovers ' + currency(recoverAmt) + ' by month-end.' : 'Slide to see the recovery.'),
            quickInput: {
              type: 'eur',
              seed: Math.round(refAmt),
              primaryBucket: 'b-overspend-main',
              placeholder: 'target €'
            },
            buckets: [bucket]
          });
        }
      }

      // Q2 — Pace-to-plan alignment
      if (fwm) {
        const planGap = Number(fwm.planGap || 0);
        const paceGapPct = Number(fwm.paceGapPct || 0);
        if (planGap < -20 || paceGapPct > 12) {
          const lever = decision && decision.adjustmentLever;
          const leverKey = lever ? 'expense-group|' + lever.key : null;
          const groups = expenseGroups();
          const primaryOpt = (leverKey ? optByKey(leverKey) : null) || groups[0] || null;
          if (primaryOpt) {
            const shortage = Math.abs(Math.min(planGap, 0));
            const primaryAllocAmt = dsAllocationForGroup(month, primaryOpt.key);
            const primaryBase = (primaryAllocAmt != null && primaryAllocAmt > 0) ? primaryAllocAmt : primaryOpt.current;
            // Use confirmed quick-input if present
            const savedQVal = month.scenario && month.scenario.questionKey === 'q-pace' && month.scenario.quickInputVal != null
              ? month.scenario.quickInputVal : null;
            const primaryTargetAmt = savedQVal != null ? savedQVal : Math.max(0, primaryBase - (shortage > 0 ? shortage : Math.round(primaryBase * 0.15)));
            const primaryBucket = dsBucketFromOption(primaryOpt, 'b-pace-main', month, historyMonths);
            primaryBucket.currentDisplay = primaryBase > 0 ? primaryBase : undefined;
            primaryBucket.value = primaryTargetAmt;
            primaryBucket.snapValue = primaryTargetAmt;
            primaryBucket.snapLabel = shortage > 0 ? '−' + currency(shortage) : '−15%';
            const buckets = [primaryBucket];

            // Secondary: basket of top-3 excluding primary, gap distributed proportionally
            const basket = dsOffsetBasket(primaryOpt.key, shortage);
            const savedOffsetKey = month.scenario && month.scenario.bucketOverrides && month.scenario.bucketOverrides['b-pace-sec'];
            const activeBasketKey = savedOffsetKey || (basket[0] && basket[0].opt.key);
            const activeBasketOpt = activeBasketKey ? optByKey(activeBasketKey) : null;
            if (activeBasketOpt) {
              const secAllocTarget = dsAllocationForGroup(month, activeBasketOpt.key);
              const secBase = (secAllocTarget != null && secAllocTarget > 0) ? secAllocTarget : activeBasketOpt.current;
              if (secBase >= 10) {
                const secBucket = dsBucketFromOption(activeBasketOpt, 'b-pace-sec', month, historyMonths);
                const activeItem = basket.find(function(c) { return c.opt.key === activeBasketOpt.key; });
                const secCut = (activeItem && activeItem.allocDelta > 0) ? activeItem.allocDelta : 0;
                const secTarget = Math.max(0, secBase - secCut);
                secBucket.value = secTarget;
                secBucket.currentDisplay = secBase;
                secBucket.snapValue = secTarget;
                secBucket.snapLabel = secCut > 0 ? '−' + currency(secCut) : '→ target';
                if (activeItem) {
                  if (!activeItem.allocTarget) activeItem.allocTarget = secBase;
                }
                secBucket.reasonNote = activeItem ? (activeItem.label + ' — ' + activeItem.reason) : '';
                secBucket.basket = basket;
                secBucket.basketBucketId = 'b-pace-sec';
                buckets.push(secBucket);
              }
            }

            questions.push({
              id: 'q-pace',
              tier: 1,
              badge: { label: planGap < 0 ? 'Urgent' : 'Warning', tone: planGap < 0 ? 'urgent' : 'warn' },
              label: planGap < 0
                ? 'Month-end is projected short — which cuts close the gap?'
                : 'Spending is above target pace — what brings it back in line?',
              currentNote: planGap < 0
                ? 'Shortfall: ' + currency(Math.abs(planGap))
                : 'Pace ' + Math.round(paceGapPct) + '% above target',
              framing: 'Target mode — set the amount you want to reach for the lever below. ' +
                (planGap < 0 ? 'Gap to close: ' + currency(Math.abs(planGap)) + '.' : 'Basket shows further cuts to reinforce.'),
              quickInput: {
                type: 'eur',
                seed: primaryTargetAmt,
                primaryBucket: 'b-pace-main',
                placeholder: 'target €'
              },
              buckets: buckets
            });
          }
        }
      }

      // Q3 — Subscription affordability simulator
      // Always fires when subscriptions exist (this is a planning question, not a reactive alert).
      // The user wants to know: "Can I add a new subscription?" or "What happens if my recurring
      // burden grows?" Cadences: monthly / quarterly / yearly — all normalised to a monthly cost.
      // Analysis: variable expense headroom, savings impact, past-months averages.
      {
        const allSubs = ensureSubscriptionsState(state).filter(function(s) { return s.active !== false; });
        if (allSubs.length > 0 || (burden && burden.activeCount > 0)) {

          // ── Cadence and amount from saved scenario state ─────────────────
          const savedSubsCadence = month.scenario && month.scenario.subsSimCadence;
          const cadence = (savedSubsCadence === 'quarterly' || savedSubsCadence === 'yearly')
            ? savedSubsCadence : 'monthly';
          const cadenceMultiplier = cadence === 'yearly' ? 1/12 : cadence === 'quarterly' ? 1/3 : 1;
          const cadenceLabel = cadence === 'yearly' ? '/yr' : cadence === 'quarterly' ? '/qtr' : '/mo';

          // Saved EUR amount (the per-cycle cost the user entered)
          const savedSubsAmt = month.scenario && month.scenario.questionKey === 'q-subs' && month.scenario.quickInputVal != null
            ? Number(month.scenario.quickInputVal) : null;
          const defaultSubsAmt = cadence === 'yearly' ? 100 : cadence === 'quarterly' ? 30 : 10;
          const inputAmt = savedSubsAmt != null ? savedSubsAmt : defaultSubsAmt;
          const monthlyNewCost = Math.max(0, inputAmt * cadenceMultiplier);

          // ── Current subscription baseline ────────────────────────────────
          const existingMonthly = allSubs.reduce(function(sum, s) {
            const c = String(s.cadence || '').toLowerCase();
            const amt = Number(s.amount || s.defaultAmount || 0);
            if (c === 'yearly') return sum + amt / 12;
            if (c === 'quarterly') return sum + amt / 3;
            return sum + amt; // monthly default
          }, 0);

          // ── Variable expense headroom ────────────────────────────────────
          // Sum of (allocation − actual) across variable expense groups where we have room
          const varGroups = simulationVariableExpenseGroups();
          let totalVarAlloc = 0, totalVarActual = 0;
          varGroups.forEach(function(g) {
            const alloc = dsAllocationForGroup(month, g.key);
            const base = (alloc != null && alloc > 0) ? alloc : g.current;
            totalVarAlloc += base;
            totalVarActual += g.current;
          });
          const varHeadroom = Math.max(0, totalVarAlloc - totalVarActual);

          // ── Savings headroom ─────────────────────────────────────────────
          const savingsAlloc = dsSavingsAllocation(month) || 0;
          const savOpt3 = primarySavingsOpt();
          const savingsActual = savOpt3 ? (savOpt3.current || 0) : 0;
          const savingsHeadroom = Math.max(0, savingsActual - 0); // savings we could dip into
          const savingsDipNeeded = monthlyNewCost > varHeadroom
            ? Math.max(0, monthlyNewCost - varHeadroom)
            : 0;

          // ── Historical average check ─────────────────────────────────────
          // Do past months show consistent variable budget surplus?
          let histVarSurplusAvg = null;
          if (historyMonths.length > 0) {
            const surpluses = historyMonths.map(function(hm) {
              const hmVarGroups = planningBucketOptions(hm).filter(function(o) {
                return o.bucketType === 'expense' && o.key.indexOf('expense-group|') === 0;
              });
              let hmAlloc = 0, hmActual = 0;
              hmVarGroups.forEach(function(g) {
                const alloc = dsAllocationForGroup(hm, g.key);
                hmAlloc += (alloc != null && alloc > 0) ? alloc : g.current;
                hmActual += g.current;
              });
              return hmAlloc - hmActual;
            }).filter(function(v) { return Number.isFinite(v); });
            if (surpluses.length) {
              histVarSurplusAvg = surpluses.reduce(function(a, b) { return a + b; }, 0) / surpluses.length;
            }
          }

          // ── Badge tone: good if affordable, warn if tight, urgent if dipping savings ──
          const subsAffordable = monthlyNewCost <= varHeadroom;
          const subsTight = !subsAffordable && savingsDipNeeded > 0 && savingsDipNeeded <= savingsAlloc * 0.15;
          const subsBadTone = !subsAffordable && !subsTight;
          const tone = subsAffordable ? 'opportunity' : subsTight ? 'warn' : 'warn';
          const badgeLabel = subsAffordable ? 'Planning' : 'Warning';

          // ── Verdict note shown in the picker ─────────────────────────────
          const annualCost = Math.round(monthlyNewCost * 12);
          const currentNote = currency(Math.round(monthlyNewCost)) + '/mo · ' + currency(annualCost) + '/yr run rate';

          questions.push({
            id: 'q-subs',
            tier: 2,
            badge: { label: badgeLabel, tone: tone },
            label: 'Can I take on a new subscription — or what if my recurring burden grows?',
            currentNote: currentNote,
            framing: 'Enter the cost per billing cycle and pick its cadence. The simulator checks whether your variable budget has room, or whether savings would need to absorb it.',
            // Quick-input = the per-cycle amount (EUR only)
            quickInput: {
              type: 'eur',
              seed: inputAmt,
              primaryBucket: 'b-subs-qi',
              placeholder: 'cost' + cadenceLabel,
              disabled: false
            },
            // No sliders — output is purely analytical (adding a fixed cost is not about cutting something)
            buckets: [],
            // Carry computed values for outcome/narration rendering
            subsData: {
              cadence: cadence,
              cadenceLabel: cadenceLabel,
              inputAmt: inputAmt,
              monthlyNewCost: monthlyNewCost,
              annualCost: annualCost,
              existingMonthly: existingMonthly,
              varHeadroom: varHeadroom,
              totalVarAlloc: totalVarAlloc,
              totalVarActual: totalVarActual,
              savingsAlloc: savingsAlloc,
              savingsDipNeeded: savingsDipNeeded,
              histVarSurplusAvg: histVarSurplusAvg,
              histMonthCount: historyMonths.length,
              affordable: subsAffordable,
              tight: subsTight
            }
          });
        }
      }

      // Q4 — Savings stretch
      const savOpt = primarySavingsOpt();
      if (savOpt) {
        const savingsRow = mix && mix.rows.find(function(r) { return r.label === 'Savings'; });
        const savPct = savingsRow ? Math.round(savingsRow.percentOfAvailable) : 0;
        const incOpt2 = primaryIncomeOpt();
        const incomeBase = incOpt2 ? totalIncome : 1;

        // Current savings allocation = the baseline
        const currentSavAlloc = dsSavingsAllocation(month) || 0;

        // Quick-input = the INCREASE amount (EUR or %). Default seed = +5% of income.
        const defaultIncreasePct = 5;
        const defaultIncreaseEur = Math.round(incomeBase * defaultIncreasePct / 100);

        const savedQMode = month.scenario && month.scenario.quickInputMode;
        const qiMode = (savedQMode === 'eur' || savedQMode === 'pct') ? savedQMode : 'pct';

        const savedQVal = month.scenario && month.scenario.questionKey === 'q-savings' && month.scenario.quickInputVal != null
          ? month.scenario.quickInputVal : null;

        // Convert input to EUR increase
        let increaseEur;
        if (savedQVal != null) {
          increaseEur = qiMode === 'pct'
            ? Math.round(savedQVal / 100 * incomeBase)
            : Math.round(savedQVal);
        } else {
          increaseEur = defaultIncreaseEur;
        }
        // Negative increase = reducing savings; positive = adding
        const targetSavAmt = currentSavAlloc + increaseEur;
        const targetSavPct = Math.round(targetSavAmt / (incomeBase || 1) * 100);

        const savBucket = dsBucketFromOption(savOpt, 'b-sav-main', month, historyMonths);
        savBucket.value = Math.max(0, targetSavAmt);
        savBucket.snapValue = currentSavAlloc + defaultIncreaseEur;
        savBucket.snapLabel = '+' + defaultIncreasePct + '%';
        savBucket.currentDisplay = currentSavAlloc > 0 ? currentSavAlloc : undefined;

        const buckets = [savBucket];

        // Gap = the increase itself (positive = need to fund this extra saving)
        const savGap = Math.max(0, increaseEur);
        const savedOverrideKey = month.scenario && month.scenario.bucketOverrides && month.scenario.bucketOverrides['b-sav-offset'];
        const basket = dsOffsetBasket(null, savGap);
        const activeOffsetKey = savedOverrideKey || (basket[0] && basket[0].opt.key);
        const activeOffsetOpt = activeOffsetKey ? optByKey(activeOffsetKey) : null;

        if (activeOffsetOpt) {
          const offsetAllocTarget = dsAllocationForGroup(month, activeOffsetOpt.key);
          const offsetBase = (offsetAllocTarget != null && offsetAllocTarget > 0) ? offsetAllocTarget : activeOffsetOpt.current;
          if (offsetBase >= 10) {
            const offsetBucket = dsBucketFromOption(activeOffsetOpt, 'b-sav-offset', month, historyMonths);
            const activeItem = basket.find(function(c) { return c.opt.key === activeOffsetOpt.key; });
            const suggestedCut = (activeItem && activeItem.allocDelta > 0) ? activeItem.allocDelta : 0;
            const suggestedTarget = Math.max(0, offsetBase - suggestedCut);
            offsetBucket.value = suggestedTarget;
            offsetBucket.currentDisplay = offsetBase;
            offsetBucket.snapValue = suggestedTarget;
            offsetBucket.snapLabel = suggestedCut > 0 ? '−' + currency(suggestedCut) : '→ target';
            if (activeItem && !activeItem.allocTarget) activeItem.allocTarget = offsetBase;
            offsetBucket.reasonNote = activeItem ? (activeItem.label + ' — ' + activeItem.reason) : '';
            offsetBucket.basket = basket;
            offsetBucket.basketBucketId = 'b-sav-offset';
            buckets.push(offsetBucket);
          }
        }

        questions.push({
          id: 'q-savings',
          tier: 2,
          badge: { label: 'Opportunity', tone: 'opportunity' },
          label: 'What would pushing your savings rate higher require in cuts?',
          currentNote: 'Currently ' + currency(currentSavAlloc) + ' (' + savPct + '% of funds)',
          framing: 'Enter the increase (EUR or %). The basket shows best categories to absorb the cut.',
          increaseEur: increaseEur,
          quickInput: {
            type: qiMode,
            toggleable: true,
            seed: qiMode === 'eur' ? defaultIncreaseEur : defaultIncreasePct,
            seedEur: defaultIncreaseEur,
            seedPct: defaultIncreasePct,
            savingsBase: currentSavAlloc,
            incomeBase: incomeBase,
            primaryBucket: 'b-sav-main',
            placeholder: qiMode === 'eur' ? '€ increase' : '% of income'
          },
          buckets: buckets
        });
      }

      // Q5 — Income scenario
      const incOpt = primaryIncomeOpt();
      if (incOpt) {
        const incHistAvg = dsHistAvgForKey(incOpt.key, historyMonths);
        const incVariance = incHistAvg && incHistAvg > 0
          ? Math.abs((incOpt.current / incHistAvg - 1) * 100)
          : 0;

        // Quick-input = the INCREASE amount (not the total). Default seed = +10%.
        const defaultIncreaseEur = Math.round(incOpt.current * 0.10 / 50) * 50 || 100;
        const defaultIncreasePct = 10;

        // Read saved mode + value (increase, not total)
        const savedQModeInc = month.scenario && month.scenario.quickInputMode;
        const qiModeInc = (savedQModeInc === 'eur' || savedQModeInc === 'pct') ? savedQModeInc : 'eur';
        const savedQValInc = month.scenario && month.scenario.questionKey === 'q-income' && month.scenario.quickInputVal != null
          ? month.scenario.quickInputVal : null;

        // Convert saved value to absolute income target
        let increaseEur;
        if (savedQValInc != null) {
          increaseEur = qiModeInc === 'pct'
            ? Math.round(incOpt.current * savedQValInc / 100)
            : savedQValInc;
        } else {
          increaseEur = defaultIncreaseEur;
        }
        const targetInc = incOpt.current + increaseEur;

        const incBucket = dsBucketFromOption(incOpt, 'b-inc-main', month, historyMonths);
        incBucket.value = targetInc;
        incBucket.snapValue = incOpt.current + defaultIncreaseEur;
        incBucket.snapLabel = '+' + currency(defaultIncreaseEur);

        const incLabel = incVariance > 8
          ? 'Income has been variable — what does a stronger month look like for your budget?'
          : 'What would a salary increase or bonus mean for your daily room?';

        // ── Gain allocation basket: 3 buttons (like Q4's offset basket) ──
        // Savings ~27%, then top-2 underfunded expense categories split the rest
        const savOptInc = primarySavingsOpt();
        const savAllocInc = dsSavingsAllocation(month) || 0;
        const gainBasket = [];

        if (savOptInc) {
          const savShare = Math.round(increaseEur * 0.60);
          gainBasket.push({
            opt: { key: 'savings', label: 'Savings' },
            label: 'Savings',
            reason: '~60% of gain to savings (recommended)',
            allocTarget: savAllocInc,
            allocDelta: savShare,
            score: 300,
            base: savAllocInc,
            isGain: true
          });
        }

        const underfunded = variableExpenseGroups(month)
          .map(function(g) {
            const alloc = dsAllocationForGroup(month, g.key);
            const room = (alloc != null && alloc > 0) ? Math.max(0, alloc - g.current) : 0;
            return { g: g, alloc: alloc || g.current, room: room };
          })
          .filter(function(x) { return x.room > 10; })
          .sort(function(a, b) { return b.room - a.room; })
          .slice(0, 2);

        const expPool = Math.round(increaseEur * 0.40);
        const expShare = underfunded.length > 0 ? Math.round(expPool / underfunded.length) : 0;
        underfunded.forEach(function(x) {
          const share = Math.min(expShare, x.room);
          gainBasket.push({
            opt: x.g,
            label: dsExpenseLabel(x.g, x.g && x.g.key),
            reason: currency(x.room) + ' below your allocation target',
            allocTarget: x.alloc,
            allocDelta: share,
            score: x.room,
            base: x.alloc,
            isGain: true
          });
        });

        // Pad to 3 if fewer underfunded categories exist
        while (gainBasket.length < 3) {
          gainBasket.push({ opt: { key: '_empty_' + gainBasket.length, label: '—' }, label: '—', reason: '', allocTarget: 0, allocDelta: 0, score: 0, base: 0, isGain: true });
        }

        // Single allocation basket bucket (renders as 3-button grid + delta line, no slider)
        const savedGainKey = month.scenario && month.scenario.bucketOverrides && month.scenario.bucketOverrides['b-inc-alloc'];
        const allocBucket = {
          id: 'b-inc-alloc',
          key: 'b-inc-alloc',
          bucketType: 'income',
          label: 'Where the gain goes',
          current: 0,
          currentDisplay: undefined,
          histAvg: null,
          min: 0, max: 0, step: 1,
          value: 0,
          basket: gainBasket,
          basketBucketId: 'b-inc-alloc',
          isGainAllocationBucket: true,
          noSlider: true  // flag to suppress slider rendering
        };

        const gainAllocationBasket = gainBasket;
        const incBuckets = [incBucket, allocBucket];

        questions.push({
          id: 'q-income',
          tier: 2,
          badge: { label: 'Planning', tone: 'planning' },
          label: incLabel,
          currentNote: 'Current income: ' + currency(incOpt.current) + (incHistAvg ? ', avg ' + currency(incHistAvg) : ''),
          framing: 'Enter the increase (EUR or %). The basket shows where this extra income could go — click to switch allocation target.',
          quickInput: {
            type: qiModeInc,
            toggleable: true,
            seed: qiModeInc === 'pct' ? defaultIncreasePct : defaultIncreaseEur,
            seedEur: defaultIncreaseEur,
            seedPct: defaultIncreasePct,
            incomeBase: incOpt.current,
            primaryBucket: 'b-inc-main',
            placeholder: qiModeInc === 'pct' ? '% increase' : '€ increase'
          },
          gainAllocationBasket: gainAllocationBasket,
          increaseEur: increaseEur,
          buckets: incBuckets
        });
      }

      // Q6 — Trajectory: is this drift structural or temporary?
      // Triggered: backgroundAnomaly exists, OR a category has risen 2+ months in a row.
      // Always fires if any expense groups exist — user can switch to any category via selector.
      // No sliders — purely diagnostic. Shows a mini-timeline, drift cost, and a verdict.
      {
        // ── Helper: compute trajData for any group key ─────────────────────
        function buildTrajDataForGroup(grpKey) {
          const grpOpt = optByKey(grpKey);
          if (!grpOpt || grpOpt.current < 0) return null;
          const timelineVals = historyMonths.map(function(hm) {
            return planningBucketOptions(hm).reduce(function(s, o) {
              return o.key === grpKey ? s + (o.current || 0) : s;
            }, 0);
          });
          const histAvg = timelineVals.length
            ? averageValue(timelineVals) : grpOpt.current;
          const recent3 = timelineVals.slice(-3);
          const baseline = recent3.length >= 2 ? averageValue(recent3) : (timelineVals.length ? timelineVals[timelineVals.length - 1] : grpOpt.current);
          const baselineLabel = recent3.length >= 2 ? 'recent average' : (timelineVals.length ? 'prior month' : 'no history');
          const driftAmt = grpOpt.current - baseline;
          const pct = baseline > 0 ? (driftAmt / baseline) * 100 : 0;
          const isDownshift = pct < -15;
          const isUptrend = timelineVals.length >= 2 &&
            timelineVals[timelineVals.length - 1] > timelineVals[timelineVals.length - 2] &&
            grpOpt.current > timelineVals[timelineVals.length - 1];
          // Try to get recurrence profile from decision engine rows
          const decRow = decision && decision.rows
            ? decision.rows.find(function(r) { return 'expense-group|' + r.key === grpKey; })
            : null;
          const profile = decRow && decRow.profile ? decRow.profile : {};
          const grpName = dsExpenseLabel(grpOpt, grpOpt && grpOpt.key);
          return {
            categoryName: grpName,
            categoryKey: grpKey,
            current: grpOpt.current,
            baseline: Math.round(baseline),
            baselineLabel: baselineLabel,
            pct: pct,
            driftAmt: driftAmt,
            annualDriftCost: Math.round(Math.abs(driftAmt) * 12),
            recoveryVal: Math.abs(driftAmt),
            driftDirection: isDownshift ? 'down' : (isUptrend ? 'up-trend' : 'up-spike'),
            isUptrend: isUptrend,
            isDownshift: isDownshift,
            timeline: timelineVals.concat([grpOpt.current]),
            timelineMonths: historyMonths.map(function(hm) { return hm.name; }).concat(['now']),
            recurrenceClass: profile.recurrenceClass || 'unknown',
            monthsObserved: Number(profile.monthsObserved || historyMonths.length),
            spikeMonths: Number(profile.spikeMonths || 0),
            histCount: historyMonths.length
          };
        }

        const allTrajGroups = expenseGroups();
        if (allTrajGroups.length > 0) {
          // ── Determine default category (signal-driven) ───────────────────
          let defaultTrajKey = null;

          // Path A: anomaly engine
          if (decision && decision.backgroundAnomaly) {
            const anom = decision.backgroundAnomaly;
            const anomKey = 'expense-group|' + anom.key;
            const anomOpt = optByKey(anomKey);
            if (anomOpt && anomOpt.current > 20) defaultTrajKey = anomKey;
          }

          // Path B: multi-month series
          if (!defaultTrajKey && historyMonths.length >= 2) {
            for (let gi = 0; gi < Math.min(allTrajGroups.length, 5); gi++) {
              const grp = allTrajGroups[gi];
              if (!grp || grp.current < 20) continue;
              const hv = historyMonths.map(function(hm) {
                return planningBucketOptions(hm).reduce(function(s, o) {
                  return o.key === grp.key ? s + (o.current || 0) : s;
                }, 0);
              });
              if (hv.length >= 2 &&
                  hv[hv.length - 1] > hv[hv.length - 2] &&
                  grp.current > hv[hv.length - 1]) {
                defaultTrajKey = grp.key;
                break;
              }
            }
          }

          // Fallback: highest-spend group
          if (!defaultTrajKey) defaultTrajKey = allTrajGroups[0].key;

          // ── User override via saved selection ────────────────────────────
          const savedTrajCat = month.scenario && month.scenario.trajCategory;
          const activeKey = savedTrajCat && allTrajGroups.find(function(g) { return g.key === savedTrajCat; })
            ? savedTrajCat : defaultTrajKey;

          const trajData = buildTrajDataForGroup(activeKey);
          if (trajData) {
            const pctAbs = Math.abs(Math.round(trajData.pct));
            const isUp = !trajData.isDownshift;
            // Badge: Warning for upward drift, Opportunity for downshift, Planning for flat/unknown
            const tone = Math.abs(trajData.pct) < 10 ? 'planning'
              : isUp ? 'warn' : 'opportunity';
            const badgeLabel = Math.abs(trajData.pct) < 10 ? 'Planning'
              : isUp ? 'Warning' : 'Opportunity';
            const dirLabel = trajData.isUptrend
              ? pctAbs + '% uptrend vs ' + trajData.baselineLabel
              : trajData.isDownshift
                ? pctAbs + '% below ' + trajData.baselineLabel
                : pctAbs > 5
                  ? pctAbs + '% above ' + trajData.baselineLabel
                  : 'near ' + trajData.baselineLabel;
            const currentNote = 'Now: ' + currency(Math.round(trajData.current)) +
              ' · avg: ' + currency(Math.round(trajData.baseline));

            questions.push({
              id: 'q-trajectory',
              tier: 2,
              badge: { label: badgeLabel, tone: tone },
              label: trajData.categoryName + ' is ' + dirLabel + ' — new normal or recoverable?',
              currentNote: currentNote,
              framing: 'Switch category below to analyse any group. This is a diagnostic read — see whether drift is structural or temporary, and what it costs annually if it holds.',
              quickInput: { disabled: true },
              buckets: [],
              trajData: trajData,
              trajAllGroups: allTrajGroups,
              trajDefaultKey: defaultTrajKey,
              trajActiveKey: activeKey
            });
          }
        }
      }

      // Q7 — Category pace drill-down
      // Always fires. User picks any expense group via the category selector.
      // Projects month-end spend for that group using computeCategoryPaceData.
      {
        const allGroups = expenseGroups();
        if (allGroups.length > 0) {
          const savedPaceCat = month.scenario && month.scenario.paceDrillCategory;
          const defaultGroup = variableExpenseGroups(month)[0] || allGroups[0];
          const activeGroupKey = savedPaceCat && allGroups.find(function(g) { return g.key === savedPaceCat; })
            ? savedPaceCat : defaultGroup.key;
          const activeGroup = allGroups.find(function(g) { return g.key === activeGroupKey; }) || defaultGroup;
          const groupName = dsExpenseLabel(activeGroup, activeGroup && activeGroup.key);

          const pd = computeCategoryPaceData(month, activeGroupKey);
          const groupHistAvg = dsHistAvgForKey(activeGroupKey, historyMonths);
          const bufferBasket = pd.isOver
            ? dsOffsetBasket(activeGroupKey, pd.projectedVsAllocation).slice(0, 2)
            : [];

          questions.push({
            id: 'q-pace-drill',
            tier: 2,
            badge: { label: pd.isOver ? 'Warning' : 'Planning', tone: pd.isOver ? 'warn' : 'opportunity' },
            label: 'Where is ' + groupName + ' heading by month-end at current pace?',
            currentNote: currency(Math.round(pd.spentSoFar)) + ' spent · ' + currency(Math.round(pd.projectedTotal)) + ' projected',
            framing: 'Category-level projection using the same forecast model as your spending pace card — recurring, open, and one-off rows handled separately.',
            quickInput: { disabled: true },
            buckets: [],
            paceDrillData: Object.assign({}, pd, {
              allGroups: allGroups,
              groupName: groupName,
              groupHistAvg: groupHistAvg,
              bufferBasket: bufferBasket
            })
          });
        }
      }

      // ── Sort and cap at 6 ───────────────────────────────────────────────
      questions.sort(function(a, b) {
        if (a.tier !== b.tier) return a.tier - b.tier;
        return 0;
      });

      return questions.slice(0, 6);
    }

    function renderDecisionSimulator(month, wrap) {
      const currentIdx = state.months.findIndex(function(m) { return m.name === month.name; });
      const historyMonths = currentIdx > 0
        ? state.months.slice(Math.max(0, currentIdx - 3), currentIdx)
        : [];
      const forecast = monthForecast(month);
      const totalIncome = (month.income || []).reduce(function(s, r) { return s + rowActual(r); }, 0);

      const questions = dsGenerateQuestions(month, historyMonths);

      // Determine active question — null = not chosen yet (blank state)
      const savedQKey = month.scenario && month.scenario.questionKey;
      const activeQ = savedQKey
        ? (questions.find(function(q) { return q.id === savedQKey; }) || null)
        : null;

      // Reset button in card header — visibility depends on activeQ (must be after activeQ)
      const resetBtnHtml = '<button type="button" class="ds-clear-btn" id="dsClearBtn"' +
        (!activeQ ? ' style="visibility:hidden"' : '') + '>Reset</button>';

      const headerHtml = renderUnifiedCardHeader({
        title: 'Decision Simulator',
        tooltipId: 'scenarioSimulatorTooltip',
        tooltipHtml: '<ul class="info-tooltip-list"><li><strong>Target mode:</strong> all inputs set the absolute target value you want to reach — not a change from current. Enter the value you want, confirm with Enter or ✓.</li><li>Choose a question — it reads signals from your budget and pre-configures the relevant levers.</li><li>The basket below each offset lever shows the top 3 smart candidates. Click to switch.</li><li>Outcomes update after each confirmation.</li></ul>',
        rightHtml: resetBtnHtml
      });

      if (!questions.length) {
        const sec = document.createElement('section');
        sec.className = 'planner-card planner-card-scenario ui-3d-decision';
        sec.setAttribute('data-card-key', 'plan_scenario');
        sec.setAttribute('data-planner-card', 'plan_scenario');
        sec.innerHTML = headerHtml + '<div class="ds-empty">Add income, savings, and expenses to generate smart scenarios.</div>';
        return sec;
      }

      // Build quick-input field for the question row
      function buildQuickInputHtml(q) {
        if (!q || !q.quickInput) {
          return '<div class="ds-quick-input-wrap is-disabled" aria-hidden="true">' +
            '<span class="ds-quick-unit" data-toggleable="false">€</span>' +
            '<input type="number" class="ds-quick-field" disabled placeholder="—">' +
            '<button type="button" class="ds-quick-confirm" disabled>✓</button>' +
          '</div>';
        }
        const qi = q.quickInput;
        if (qi.disabled) {
          return '<div class="ds-quick-input-wrap is-disabled" aria-label="Not applicable for this question" title="Not applicable for this question">' +
            '<span class="ds-quick-unit" data-toggleable="false">—</span>' +
            '<input type="number" class="ds-quick-field" disabled placeholder="n/a">' +
            '<button type="button" class="ds-quick-confirm" disabled>✓</button>' +
          '</div>';
        }
        // Resolve current mode: saved > question default
        const savedMode = month.scenario && month.scenario.quickInputMode;
        const mode = qi.toggleable && (savedMode === 'eur' || savedMode === 'pct')
          ? savedMode : qi.type;
        // Resolve display value: saved raw val > seed for current mode
        const savedVal = month.scenario && month.scenario.quickInputVal != null
          ? month.scenario.quickInputVal : null;
        const displayVal = savedVal != null ? savedVal
          : (mode === 'pct' ? qi.seedPct : (qi.seedEur != null ? qi.seedEur : qi.seed));
        const unit = mode === 'pct' ? '%' : '€';
        const toggleTitle = qi.toggleable
          ? (mode === 'pct' ? 'Switch to EUR input' : 'Switch to % input')
          : '';
        return '<div class="ds-quick-input-wrap" id="dsQuickWrap">' +
          '<span class="ds-quick-unit" id="dsQuickUnit"' +
            ' data-toggleable="' + (qi.toggleable ? 'true' : 'false') + '"' +
            (toggleTitle ? ' title="' + toggleTitle + '"' : '') + '>' +
            unit +
          '</span>' +
          '<input type="number" class="ds-quick-field" id="dsQuickField"' +
            ' step="' + (mode === 'pct' ? '0.5' : '1') + '"' +
            ' value="' + (displayVal != null ? displayVal : '') + '"' +
            ' placeholder="' + escapeHtml(qi.placeholder || '') + '">' +
          '<button type="button" class="ds-quick-confirm" id="dsQuickConfirm" title="Confirm (Enter)">✓</button>' +
        '</div>';
      }

      // Context strip: Currently (allocation) → Target (input) + delta
      function buildQuickContextHtml(q) {
        if (!q || !q.quickInput || q.quickInput.disabled) return '';
        const qi = q.quickInput;
        // Only show after the user has confirmed a value for THIS question
        const savedVal = month.scenario && month.scenario.questionKey === q.id && month.scenario.quickInputVal != null
          ? month.scenario.quickInputVal : null;
        if (savedVal == null) return '';

        // Q3 subscription: bypass standard currentBase logic — no primary expense bucket
        if (q.id === 'q-subs') {
          const sd = q.subsData || {};
          const cadenceLabel = sd.cadenceLabel || '/mo';
          const monthlyCost = Math.max(0, savedVal * (sd.cadence === 'yearly' ? 1/12 : sd.cadence === 'quarterly' ? 1/3 : 1));
          const annualCost = Math.round(monthlyCost * 12);
          const affordable = monthlyCost <= (sd.varHeadroom || 0);
          const cls = affordable ? 'ds-positive' : 'ds-negative';
          return '<div class="ds-quick-context">' +
            '<span>' + currency(Math.round(savedVal)) + cadenceLabel + '</span>' +
            '<span class="ds-quick-context-arrow">→</span>' +
            '<span class="ds-quick-context-delta ' + cls + '">' + currency(Math.round(monthlyCost)) + '/mo</span>' +
            '<span class="ds-quick-context-arrow">·</span>' +
            '<span class="ds-quick-context-delta ' + cls + '">' + currency(annualCost) + '/yr</span>' +
          '</div>';
        }

        const primary = q.buckets.find(function(b) { return b.id === qi.primaryBucket; });

        // "Currently" = the allocation baseline for this question
        let currentBase;
        if (q.id === 'q-savings') {
          currentBase = dsSavingsAllocation(month) || 0;
        } else if (primary && primary.currentDisplay != null) {
          // currentDisplay was set at build time to the allocation amount
          currentBase = primary.currentDisplay;
        } else if (primary) {
          currentBase = primary.current;
        } else {
          return '';
        }

        // "Target" = confirmed input in EUR
        const savedMode = month.scenario && month.scenario.quickInputMode;
        const mode = qi.toggleable && (savedMode === 'eur' || savedMode === 'pct') ? savedMode : (qi.type || 'eur');
        let targetEur, increaseEur;
        if (q.id === 'q-savings') {
          // savedVal = increase amount (EUR or % of income)
          const incBase = qi.incomeBase || 1;
          increaseEur = mode === 'pct' ? Math.round(savedVal / 100 * incBase) : savedVal;
          targetEur = currentBase + increaseEur;
        } else if (q.id === 'q-income') {
          const incBase = qi.incomeBase || 0;
          increaseEur = mode === 'pct' ? Math.round(incBase * savedVal / 100) : savedVal;
          targetEur = currentBase + increaseEur;
        } else {
          targetEur = savedVal;
          increaseEur = null;
        }

        const delta = targetEur - currentBase;
        if (Math.abs(delta) < 0.5) return '';
        const sign = delta >= 0 ? '+' : '';
        const isGood = (q.id === 'q-savings' || q.id === 'q-income') ? delta > 0 : delta < 0;
        const deltaCls = isGood ? 'ds-positive' : 'ds-negative';

        // Q4 and Q5: show "Currently: X → +Y → Total: Z" increase framing
        if ((q.id === 'q-income' || q.id === 'q-savings') && increaseEur != null) {
          const incSign = increaseEur >= 0 ? '+' : '';
          return '<div class="ds-quick-context">' +
            '<span>Currently: <strong>' + currency(currentBase) + '</strong></span>' +
            '<span class="ds-quick-context-arrow">→</span>' +
            '<span class="ds-quick-context-delta ' + deltaCls + '">' + incSign + currency(increaseEur) + '</span>' +
            '<span class="ds-quick-context-arrow">→</span>' +
            '<span>Total: <strong>' + currency(targetEur) + '</strong></span>' +
          '</div>';
        }

        return '<div class="ds-quick-context">' +
          '<span>Currently: <strong>' + currency(currentBase) + '</strong></span>' +
          '<span class="ds-quick-context-arrow">→</span>' +
          '<span>Target: <strong>' + currency(targetEur) + '</strong></span>' +
          '<span class="ds-quick-context-delta ' + deltaCls + '">' + sign + currency(delta) + '</span>' +
        '</div>';
      }

      // ── Outcome narration ──────────────────────────────────────────────
      function buildNarration(out, q) {
        if (!q) return '';

        // Per-question specific summary sentence using real bucket values
        const primaryB = q.buckets[0];
        const offsetB = q.buckets.length > 1 ? q.buckets[1] : null;

        function bucketDelta(b) {
          if (!b) return null;
          const d = b.value - b.current;
          return Math.abs(d) < 0.5 ? null : d;
        }

        function sign(n) { return n >= 0 ? '+' : ''; }
        function scenarioSignedCurrency(n) { return sign(n) + currency(n); }

        if (q.id === 'q-savings') {
          const savAllocNow = dsSavingsAllocation(month);
          const savBase = (savAllocNow != null && savAllocNow > 0) ? savAllocNow : primaryB.current;
          const confirmedVal = month.scenario && month.scenario.quickInputVal != null ? month.scenario.quickInputVal : null;
          if (confirmedVal == null) return '';
          const qi = q.quickInput || {};
          const incBase = qi.incomeBase || 1;
          const savedMode = month.scenario && month.scenario.quickInputMode;
          const mode = qi.toggleable && (savedMode === 'eur' || savedMode === 'pct') ? savedMode : (qi.type || 'pct');
          // confirmedVal = increase, not absolute
          const increaseEurN = mode === 'pct' ? Math.round(confirmedVal / 100 * incBase) : confirmedVal;
          const targetEur = savBase + increaseEurN;
          if (Math.abs(increaseEurN) < 0.5) return '';
          const offsetDelta = offsetB ? (offsetB.value - (offsetB.currentDisplay != null ? offsetB.currentDisplay : offsetB.current)) : null;
          const incSign = increaseEurN >= 0 ? '+' : '';
          let s = 'Savings ' + incSign + currency(increaseEurN) + ' → ' + currency(targetEur) + ' total';
          if (offsetB && offsetDelta != null && Math.abs(offsetDelta) > 0.5) {
            s += ', funded by cutting ' + offsetB.label + ' to ' + currency(offsetB.value) +
              ' (' + scenarioSignedCurrency(offsetDelta) + ' from allocation).';
          } else {
            s += '.';
          }
          return s;
        }

        if (q.id === 'q-overspend' || q.id === 'q-pace') {
          const allocBase = primaryB.currentDisplay != null ? primaryB.currentDisplay : primaryB.current;
          const confirmedTarget = month.scenario && month.scenario.quickInputVal != null ? month.scenario.quickInputVal : primaryB.value;
          const delta = confirmedTarget - allocBase;
          if (Math.abs(delta) < 0.5) return '';
          let s = primaryB.label + ' from ' + currency(allocBase) + ' → ' + currency(confirmedTarget) + ' (' + scenarioSignedCurrency(delta) + ' from allocation)';
          if (offsetB) {
            const secBase = offsetB.currentDisplay != null ? offsetB.currentDisplay : offsetB.current;
            const secDelta = offsetB.value - secBase;
            if (Math.abs(secDelta) > 0.5) {
              s += ', ' + offsetB.label + ' from ' + currency(secBase) + ' → ' + currency(offsetB.value) + ' (' + scenarioSignedCurrency(secDelta) + ')';
            }
          }
          const recovered = Math.abs(out.totalDelta);
          if (recovered > 1) s += '. Frees ' + currency(recovered) + ' by month-end.';
          if (out.adjustedEnd >= 0 && out.baseEnd < 0) s += ' Month-end moves positive.';
          else if (out.adjustedEnd < 0) s += ' Month-end still negative.';
          return s;
        }

        if (q.id === 'q-income') {
          const qiInc = q.quickInput || {};
          const savedModeInc = month.scenario && month.scenario.quickInputMode;
          const incModeN = qiInc.toggleable && (savedModeInc === 'eur' || savedModeInc === 'pct') ? savedModeInc : (qiInc.type || 'eur');
          const incBaseN = qiInc.incomeBase || primaryB.current;
          const confirmedInc = month.scenario && month.scenario.quickInputVal != null ? month.scenario.quickInputVal : null;
          if (confirmedInc == null) return '';
          const increaseEurN = incModeN === 'pct' ? Math.round(incBaseN * confirmedInc / 100) : confirmedInc;
          const totalIncN = incBaseN + increaseEurN;
          let s = 'Income +' + currency(increaseEurN) + ' → ' + currency(totalIncN) + ' total.';
          // List how the gain is allocated across candidates
          const basket = q.gainAllocationBasket || [];
          if (basket.length > 0) {
            const parts = basket.map(function(c) {
              const newShare = Math.round((c.share || 0) * (increaseEurN / (qiInc.seedEur || increaseEurN || 1)));
              return currency(newShare) + ' → ' + c.label;
            });
            s += ' Allocated: ' + parts.join(', ') + '.';
          }
          return s;
        }

        if (q.id === 'q-trajectory') {
          const td = q.trajData;
          if (!td) return '';
          const pctAbs = Math.abs(Math.round(td.pct));
          const driftStr = currency(Math.abs(Math.round(td.driftAmt)));

          // Build timeline string  e.g.  €180 → €195 → €203 → €241 (now)
          const timelineStr = td.timeline.map(function(v, i) {
            const label = i === td.timeline.length - 1 ? currency(Math.round(v)) + ' (now)' : currency(Math.round(v));
            return label;
          }).join(' → ');

          if (td.isDownshift) {
            return '<strong>' + td.categoryName + '</strong> is running <strong>' + pctAbs + '% below its ' +
              td.baselineLabel + '</strong> (' + timelineStr + '). ' +
              '<strong>' + driftStr + '/mo</strong> may be available to redirect — consider savings as the first destination. ' +
              'Confirm this is not a timing gap before acting on it.';
          }
          if (td.isUptrend) {
            let s = '<strong>' + td.categoryName + '</strong> shows a <strong>' + td.histCount + '-month uptrend</strong> (' + timelineStr + '). ';
            s += 'If this holds, you are committing <strong>' + currency(td.annualDriftCost) + '/yr more</strong> than your ' + td.baselineLabel + '. ';
            if (td.recurrenceClass === 'recurring') {
              s += 'History suggests this is a <strong>recurring pattern</strong> — consider raising the allocation for ' + td.categoryName + '.';
            } else if (td.recurrenceClass === 'occasional') {
              s += 'This type of spike is <strong>occasional</strong> in your history — worth watching but not necessarily permanent.';
            } else {
              s += 'Review whether this reflects a <strong>permanent cost increase</strong> or a recoverable spike.';
            }
            return s;
          }
          // Spike (up but not a trend)
          return '<strong>' + td.categoryName + '</strong> is <strong>' + pctAbs + '% above its ' + td.baselineLabel + '</strong> (' + timelineStr + '). ' +
            'This looks like an <strong>outlier month</strong> rather than a trend — the prior months were more stable. ' +
            (td.annualDriftCost > 0 ? 'If it recurs, the annual cost would be <strong>' + currency(td.annualDriftCost) + '</strong> above average. ' : '') +
            'No allocation change needed unless the pattern repeats.';
        }

        if (q.id === 'q-subs') {
          const sd = q.subsData;
          if (!sd) return '';
          const monthlyCost = sd.monthlyNewCost;
          if (monthlyCost < 0.5) return '';
          const existingTotal = Math.round(sd.existingMonthly);
          const newTotal = Math.round(existingTotal + monthlyCost);
          const annualNew = sd.annualCost;
          const varRoom = Math.round(sd.varHeadroom);
          const savDip = Math.round(sd.savingsDipNeeded);
          const histAvg = sd.histVarSurplusAvg;

          if (sd.affordable) {
            let s = currency(Math.round(monthlyCost)) + '/mo fits within your variable budget — ' +
              currency(varRoom) + ' of headroom available.';
            s += ' Total recurring load would be ' + currency(newTotal) + '/mo (' + currency(annualNew) + '/yr).';
            if (histAvg != null && histAvg > monthlyCost) {
              s += ' Past ' + sd.histMonthCount + '-month average shows ' + currency(Math.round(histAvg)) + ' surplus, supporting this.';
            } else if (histAvg != null && histAvg < monthlyCost) {
              s += ' However, your ' + sd.histMonthCount + '-month average surplus was only ' + currency(Math.round(histAvg)) + ' — watch the trend.';
            }
            return s;
          } else if (savDip > 0) {
            let s = currency(Math.round(monthlyCost)) + '/mo exceeds available variable headroom (' + currency(varRoom) + ').';
            s += ' Absorbing it would require ' + currency(savDip) + '/mo from planned savings.';
            if (histAvg != null) {
              s += ' Past ' + sd.histMonthCount + '-month average surplus: ' + currency(Math.round(histAvg)) +
                (histAvg >= monthlyCost ? ' — history suggests it may be feasible with discipline.' : ' — history does not support this addition.');
            }
            return s;
          } else {
            return currency(Math.round(monthlyCost)) + '/mo exceeds available variable headroom (' + currency(varRoom) + '). ' +
              'This would require cutting variable categories or dipping into savings.';
          }
        }

        // Fallback for unknown question IDs
        const daily = out.dailyDelta;
        const freed = out.nonSavingsDelta;
        const hasDaily = Math.abs(daily) > 0.5;
        const hasFreed = Math.abs(freed) > 5 && q.buckets.some(function(b) { return b.bucketType !== 'savings'; });
        if (hasDaily && hasFreed) {
          return freed > 0
            ? 'At this level, you free up ' + currency(freed) + ' — enough to add ' + currency(Math.abs(daily)) + '/day, or redirect to savings.'
            : 'At this level, you commit ' + currency(Math.abs(freed)) + ' more, reducing room by ' + currency(Math.abs(daily)) + '/day.';
        }
        if (hasDaily) return daily > 0 ? 'You gain ' + currency(daily) + '/day in spending room.' : 'You lose ' + currency(Math.abs(daily)) + '/day in spending room.';
        if (hasFreed) return freed > 0 ? currency(freed) + ' freed for savings.' : currency(Math.abs(freed)) + ' more committed away from savings.';
        return '';
      }

      // ── Outcome block HTML ─────────────────────────────────────────────
      function buildOutcomeHtml(buckets, q, pending) {
        const out = pending ? null : dsComputeOutcomes(buckets, forecast, totalIncome, historyMonths);
        const rows = [];

        function placeholder() {
          return '<div class="ds-outcome-val"><strong>—</strong></div>';
        }

        function valWithDelta(absVal, delta, absClass) {
          const dCls = delta > 0.5 ? 'ds-positive' : delta < -0.5 ? 'ds-negative' : '';
          const dSign = delta >= 0 ? '+' : '';
          const deltaHtml = Math.abs(delta) > 0.5
            ? '<span class="ds-outcome-delta ' + dCls + '">' + dSign + currency(delta) + ' vs now</span>'
            : '';
          return '<div class="ds-outcome-val">' +
            '<strong class="' + absClass + '">' + absVal + '</strong>' +
            deltaHtml +
          '</div>';
        }

        // Q5 income: custom outcome block (standard metrics don't apply)
        if (q && q.id === 'q-income') {
          const confirmedVal = month.scenario && month.scenario.questionKey === 'q-income' && month.scenario.quickInputVal != null
            ? month.scenario.quickInputVal : null;
          const qi = q.quickInput || {};
          const savedMode = month.scenario && month.scenario.quickInputMode;
          const incMode = qi.toggleable && (savedMode === 'eur' || savedMode === 'pct') ? savedMode : (qi.type || 'eur');
          const incBase = qi.incomeBase || 0;

          // Use confirmed value if present; fall back to the value computed at build time (q.increaseEur)
          // so tiles are never blank when the question is active
          const effectiveIncrease = confirmedVal != null
            ? (incMode === 'pct' ? Math.round(incBase * confirmedVal / 100) : confirmedVal)
            : (q.increaseEur || 0);

          if (!effectiveIncrease || !out) {
            rows.push('<div class="ds-outcome-row"><span>Monthly income gain</span>' + placeholder() + '</div>');
            rows.push('<div class="ds-outcome-row"><span>To savings</span>' + placeholder() + '</div>');
            rows.push('<div class="ds-outcome-row"><span>To spending</span>' + placeholder() + '</div>');
          } else {
            const increaseEurOut = effectiveIncrease;
            const basket = q.gainAllocationBasket || [];

            // Row 1: Income gain
            rows.push('<div class="ds-outcome-row"><span>Monthly income gain</span>' +
              '<div class="ds-outcome-val"><strong class="ds-positive">+' + currency(increaseEurOut) + '</strong></div>' +
            '</div>');

            // Row 2: To savings — always 60% of the effective increase
            const savShare = Math.round(increaseEurOut * 0.60);
            const savAllocNow = dsSavingsAllocation(month) || 0;
            rows.push('<div class="ds-outcome-row"><span>To savings</span>' +
              '<div class="ds-outcome-val">' +
                '<strong class="ds-positive">+' + currency(savShare) + '</strong>' +
                '<span class="ds-outcome-delta ds-positive">' + currency(savAllocNow + savShare) + ' total</span>' +
              '</div>' +
            '</div>');

            // Row 3: To spending (remainder after savings share)
            const toSpending = increaseEurOut - savShare;
            const dailyExtra = (toSpending / 30).toFixed(2);
            rows.push('<div class="ds-outcome-row"><span>To spending</span>' +
              '<div class="ds-outcome-val">' +
                '<strong class="ds-positive">+' + currency(toSpending) + '</strong>' +
                '<span class="ds-outcome-delta ds-positive">+€' + dailyExtra + '/day</span>' +
              '</div>' +
            '</div>');
          }

          const narration = out ? buildNarration(out, q) : '';
          const narrationHtml = narration ? '<div class="ds-narration" data-ds-out="narration">' + narration + '</div>' : '';
          return '<div class="ds-outcomes" data-ds-outcomes>' + rows.join('') + '</div>' + narrationHtml;
        }

        // Q4 savings: custom outcome block showing savings increase, expense cut, net
        if (q && q.id === 'q-savings') {
          const confirmedVal = month.scenario && month.scenario.questionKey === 'q-savings' && month.scenario.quickInputVal != null
            ? month.scenario.quickInputVal : null;
          const qi = q.quickInput || {};
          const incBase = qi.incomeBase || 1;
          const savedMode = month.scenario && month.scenario.quickInputMode;
          const incMode = qi.toggleable && (savedMode === 'eur' || savedMode === 'pct') ? savedMode : (qi.type || 'pct');
          const effectiveIncrease = confirmedVal != null
            ? (incMode === 'pct' ? Math.round(incBase * confirmedVal / 100) : confirmedVal)
            : (q.increaseEur || 0);
          const savBase = dsSavingsAllocation(month) || 0;
          const savTarget = savBase + effectiveIncrease;
          const offsetB = q.buckets.find(function(b) { return b.id === 'b-sav-offset'; });
          const offsetBase = offsetB ? (offsetB.currentDisplay != null ? offsetB.currentDisplay : offsetB.current) : 0;
          const offsetTarget = offsetB ? offsetB.value : offsetBase;
          const offsetCut = offsetBase - offsetTarget;

          // Row 1: Savings increase
          const incSign = effectiveIncrease >= 0 ? '+' : '';
          rows.push('<div class="ds-outcome-row"><span>Savings target</span>' +
            '<div class="ds-outcome-val">' +
              '<strong class="' + (effectiveIncrease >= 0 ? 'ds-positive' : 'ds-negative') + '">' + incSign + currency(effectiveIncrease) + '</strong>' +
              '<span class="ds-outcome-delta">' + currency(savTarget) + ' total</span>' +
            '</div></div>');

          // Row 2: Expense cut required
          if (offsetB) {
            rows.push('<div class="ds-outcome-row"><span>Cut in ' + escapeHtml(offsetB.label) + '</span>' +
              '<div class="ds-outcome-val">' +
                '<strong class="' + (offsetCut > 0 ? 'ds-positive' : 'ds-negative') + '">' + (offsetCut > 0 ? '−' : '+') + currency(Math.abs(offsetCut)) + '</strong>' +
                '<span class="ds-outcome-delta">' + currency(offsetTarget) + ' target</span>' +
              '</div></div>');
          }

          // Row 3: Net monthly impact (savings increase minus expense freed)
          const net = effectiveIncrease - offsetCut;
          const netCls = net <= 0 ? 'ds-positive' : 'ds-negative';
          rows.push('<div class="ds-outcome-row"><span>Net monthly impact</span>' +
            '<div class="ds-outcome-val">' +
              '<strong class="' + netCls + '">' + (net > 0 ? '−' : '+') + currency(Math.abs(net)) + '</strong>' +
              '<span class="ds-outcome-delta">' + (net > 0 ? 'still needed from other cuts' : 'fully covered') + '</span>' +
            '</div></div>');

          const narration = out ? buildNarration(out, q) : '';
          const narrationHtml = narration ? '<div class="ds-narration" data-ds-out="narration">' + narration + '</div>' : '';
          return '<div class="ds-outcomes" data-ds-outcomes>' + rows.join('') + '</div>' + narrationHtml;
        }

        // Q3 subscription affordability: custom analytical outcome — no sliders, pure cost analysis
        if (q && q.id === 'q-subs') {
          const sd = q.subsData || {};
          const confirmedAmt = month.scenario && month.scenario.questionKey === 'q-subs' && month.scenario.quickInputVal != null
            ? Number(month.scenario.quickInputVal) : null;
          const effectiveInput = confirmedAmt != null ? confirmedAmt : (sd.inputAmt || 0);
          const effectiveMonthly = effectiveInput * (sd.cadence === 'yearly' ? 1/12 : sd.cadence === 'quarterly' ? 1/3 : 1);
          const annualCost = Math.round(effectiveMonthly * 12);
          const existingMonthly = sd.existingMonthly || 0;
          const varHeadroom = sd.varHeadroom || 0;
          const savDip = Math.max(0, effectiveMonthly - varHeadroom);
          const histAvg = sd.histVarSurplusAvg;

          // Row 1: Monthly cost
          const monthlyCls = effectiveMonthly <= varHeadroom ? 'ds-positive' : 'ds-negative';
          rows.push('<div class="ds-outcome-row"><span>Monthly cost (normalised)</span>' +
            '<div class="ds-outcome-val">' +
              '<strong class="' + monthlyCls + '">' + currency(Math.round(effectiveMonthly)) + '/mo</strong>' +
              '<span class="ds-outcome-delta">' + currency(annualCost) + '/yr</span>' +
            '</div></div>');

          // Row 2: Variable budget headroom vs cost
          const headroomCls = varHeadroom >= effectiveMonthly ? 'ds-positive' : 'ds-negative';
          const headroomNote = varHeadroom >= effectiveMonthly
            ? currency(Math.round(varHeadroom - effectiveMonthly)) + ' still free'
            : currency(Math.round(effectiveMonthly - varHeadroom)) + ' over budget';
          rows.push('<div class="ds-outcome-row"><span>Variable budget headroom</span>' +
            '<div class="ds-outcome-val">' +
              '<strong class="' + headroomCls + '">' + currency(Math.round(varHeadroom)) + '</strong>' +
              '<span class="ds-outcome-delta ' + headroomCls + '">' + headroomNote + '</span>' +
            '</div></div>');

          // Row 3: Savings impact (only show when dip needed)
          if (savDip > 0.5) {
            const savingsAlloc = sd.savingsAlloc || 0;
            const savPct = savingsAlloc > 0 ? ((savDip / savingsAlloc) * 100).toFixed(1) : null;
            const savNote = savPct ? savPct + '% of planned savings' : 'from planned savings';
            rows.push('<div class="ds-outcome-row"><span>Savings dip required</span>' +
              '<div class="ds-outcome-val">' +
                '<strong class="ds-negative">−' + currency(Math.round(savDip)) + '/mo</strong>' +
                '<span class="ds-outcome-delta ds-negative">' + savNote + '</span>' +
              '</div></div>');
          } else {
            rows.push('<div class="ds-outcome-row"><span>Savings impact</span>' +
              '<div class="ds-outcome-val"><strong class="ds-positive">None</strong>' +
              '<span class="ds-outcome-delta">covered by variable budget</span></div></div>');
          }

          // Row 4: Historical average check
          if (histAvg != null && sd.histMonthCount > 0) {
            const histCls = histAvg >= effectiveMonthly ? 'ds-positive' : 'ds-negative';
            const histVerdict = histAvg >= effectiveMonthly ? 'avg surplus supports this' : 'avg surplus too low';
            rows.push('<div class="ds-outcome-row"><span>Avg variable surplus (' + sd.histMonthCount + ' mo)</span>' +
              '<div class="ds-outcome-val">' +
                '<strong class="' + histCls + '">' + currency(Math.round(histAvg)) + '/mo</strong>' +
                '<span class="ds-outcome-delta ' + histCls + '">' + histVerdict + '</span>' +
              '</div></div>');
          }

          const narration = buildNarration(null, q);
          const narrationHtml = narration ? '<div class="ds-narration" data-ds-out="narration">' + narration + '</div>' : '';
          return '<div class="ds-outcomes" data-ds-outcomes>' + rows.join('') + '</div>' + narrationHtml;
        }

        // Q6 trajectory: diagnostic outcome — drift cost, recovery value, recurrence class
        if (q && q.id === 'q-trajectory') {
          const td = q.trajData;
          if (!td) {
            rows.push('<div class="ds-outcome-row"><span>Drift vs average</span>' + placeholder() + '</div>');
            rows.push('<div class="ds-outcome-row"><span>Annual cost of drift</span>' + placeholder() + '</div>');
            rows.push('<div class="ds-outcome-row"><span>Recovery value</span>' + placeholder() + '</div>');
          } else {
            const isUp = !td.isDownshift;
            // Row 1: Drift vs average
            const driftCls = isUp ? 'ds-negative' : 'ds-positive';
            const driftSign = isUp ? '+' : '−';
            const driftPct = Math.abs(Math.round(td.pct));
            rows.push('<div class="ds-outcome-row"><span>Drift vs ' + td.baselineLabel + '</span>' +
              '<div class="ds-outcome-val">' +
                '<strong class="' + driftCls + '">' + driftSign + currency(Math.abs(Math.round(td.driftAmt))) + '/mo</strong>' +
                '<span class="ds-outcome-delta ' + driftCls + '">' + driftSign + driftPct + '%</span>' +
              '</div></div>');

            // Row 2: Annual cost of drift (upward only)
            if (isUp) {
              rows.push('<div class="ds-outcome-row"><span>Annual cost if this holds</span>' +
                '<div class="ds-outcome-val">' +
                  '<strong class="ds-negative">+' + currency(td.annualDriftCost) + '/yr</strong>' +
                  '<span class="ds-outcome-delta">above avg run rate</span>' +
                '</div></div>');
            } else {
              rows.push('<div class="ds-outcome-row"><span>Annual saving vs average</span>' +
                '<div class="ds-outcome-val">' +
                  '<strong class="ds-positive">−' + currency(td.annualDriftCost) + '/yr</strong>' +
                  '<span class="ds-outcome-delta">below avg run rate</span>' +
                '</div></div>');
            }

            // Row 3: Recurrence class verdict
            const rcLabel = td.recurrenceClass === 'recurring' ? 'Recurring pattern'
              : td.recurrenceClass === 'occasional' ? 'Occasional spike'
              : td.recurrenceClass === 'one-off' ? 'One-off event'
              : td.histCount >= 2 ? 'Pattern unclear'
              : 'First data point';
            const rcCls = td.recurrenceClass === 'recurring' ? 'ds-negative'
              : td.recurrenceClass === 'one-off' ? 'ds-positive'
              : '';
            const rcNote = td.monthsObserved > 0
              ? td.spikeMonths + ' of ' + td.monthsObserved + ' prior months'
              : td.histCount + ' months of history';
            rows.push('<div class="ds-outcome-row"><span>Pattern classification</span>' +
              '<div class="ds-outcome-val">' +
                '<strong class="' + rcCls + '">' + rcLabel + '</strong>' +
                '<span class="ds-outcome-delta">' + rcNote + '</span>' +
              '</div></div>');
          }
          const narration = buildNarration(null, q);
          const narrationHtml = narration ? '<div class="ds-narration" data-ds-out="narration">' + narration + '</div>' : '';
          return '<div class="ds-outcomes" data-ds-outcomes>' + rows.join('') + '</div>' + narrationHtml;
        }

        // Q7 pace drill: delegate entirely to shared renderCategoryPaceTile
        if (q && q.id === 'q-pace-drill') {
          return renderCategoryPaceTile(q.paceDrillData || null, 'simulator');
        }

        // Standard outcome block for all other questions
        if (out) {
          const dailyCls = out.dailyDelta > 0.5 ? 'ds-positive' : out.dailyDelta < -0.5 ? 'ds-negative' : '';
          rows.push('<div class="ds-outcome-row"><span>Spending room per day</span>' +
            valWithDelta(currency(out.adjustedDaily) + '/day', out.dailyDelta, dailyCls) + '</div>');
        } else {
          rows.push('<div class="ds-outcome-row"><span>Spending room per day</span>' + placeholder() + '</div>');
        }

        const showFreed = out && Math.abs(out.nonSavingsDelta) > 1;
        if (showFreed) {
          const freed = out.nonSavingsDelta;
          const label = freed > 0 ? 'Budget freed for savings' : 'Extra savings commitment';
          const freeCls = freed > 0 ? 'ds-positive' : 'ds-negative';
          rows.push('<hr class="ds-outcome-divider"/>' +
            '<div class="ds-outcome-row"><span>' + label + '</span>' +
            '<div class="ds-outcome-val"><strong class="' + freeCls + '">' + (freed > 0 ? '+' : '') + currency(freed) + '</strong></div>' +
            '</div>');
        }

        if (out && out.expCoverageCurrent !== null && out.expCoverageAdj !== null &&
            Math.abs(out.expCoverageAdj - out.expCoverageCurrent) > 0.2) {
          const covDelta = out.expCoverageAdj - out.expCoverageCurrent;
          const covCls = covDelta < 0 ? 'ds-positive' : covDelta > 0 ? 'ds-negative' : '';
          rows.push('<div class="ds-outcome-row"><span>Expense share of income</span>' +
            '<div class="ds-outcome-val">' +
              '<strong class="' + covCls + '">' + out.expCoverageAdj.toFixed(1) + '%</strong>' +
              '<span class="ds-outcome-delta ' + covCls + '">' + (covDelta >= 0 ? '+' : '') + covDelta.toFixed(1) + 'pp vs now</span>' +
            '</div></div>');
        }

        const narration = out ? buildNarration(out, q) : '';
        const narrationHtml = narration
          ? '<div class="ds-narration" data-ds-out="narration">' + narration + '</div>'
          : '';

        return '<div class="ds-outcomes" data-ds-outcomes>' + rows.join('') + '</div>' + narrationHtml;
      }

      // ── Bucket / slider HTML ───────────────────────────────────────────
      function buildBucketHtml(buckets) {
        // Q3 subscription: no sliders — render cadence toggle only
        if (activeQ && activeQ.id === 'q-subs') {
          const sd = activeQ.subsData || {};
          const currentCadence = sd.cadence || 'monthly';
          const cadences = [
            { key: 'monthly',   label: 'Monthly' },
            { key: 'quarterly', label: 'Quarterly' },
            { key: 'yearly',    label: 'Yearly' }
          ];
          const btns = cadences.map(function(c) {
            const isActive = c.key === currentCadence;
            return '<button type="button" class="ds-cadence-btn' + (isActive ? ' is-active' : '') + '"' +
              ' data-ds-cadence="' + c.key + '">' + c.label + '</button>';
          }).join('');
          const existingMonthly = sd.existingMonthly || 0;
          const existingNote = existingMonthly > 0.5
            ? 'Current recurring baseline: ' + currency(Math.round(existingMonthly)) + '/mo (' + currency(Math.round(existingMonthly * 12)) + '/yr)'
            : 'No existing subscriptions yet.';
          return '<div class="ds-subs-ui">' +
            '<div class="ds-subs-cadence-row">' +
              '<span class="ds-subs-cadence-label">Billing cadence</span>' +
              '<div class="ds-cadence-btns" id="dsCadenceBtns">' + btns + '</div>' +
            '</div>' +
            '<div class="ds-subs-existing-note">' + existingNote + '</div>' +
          '</div>';
        }

        // Q6 trajectory: category selector + mini timeline display — no sliders
        if (activeQ && activeQ.id === 'q-trajectory') {
          const td = activeQ.trajData;
          const allTrajGroups = activeQ.trajAllGroups || [];
          const activeKey = activeQ.trajActiveKey || (td && td.categoryKey);
          const defaultKey = activeQ.trajDefaultKey;

          // Category selector pills
          const catBtns = allTrajGroups.slice(0, 8).map(function(g) {
            const isActive = g.key === activeKey;
            const isSignal = g.key === defaultKey && g.key !== activeKey;
            const label = dsExpenseLabel(g, g && g.key);
            return '<button type="button" class="ds-traj-cat-btn' +
              (isActive ? ' is-active' : '') +
              (isSignal ? ' is-signal' : '') + '"' +
              ' data-ds-traj-cat="' + escapeHtml(g.key) + '"' +
              ' title="' + escapeHtml(label) + (isSignal ? ' (signal-triggered)' : '') + '">' +
              escapeHtml(label) +
            '</button>';
          }).join('');

          // Timeline dots
          if (!td || !td.timeline.length) {
            return '<div class="ds-traj-ui">' +
              '<div class="ds-traj-cat-row"><span class="ds-traj-cat-label">Category</span>' +
              '<div class="ds-traj-cat-btns">' + catBtns + '</div></div>' +
            '</div>';
          }
          const isUp = !td.isDownshift;
          const dotHtml = td.timeline.map(function(v, i) {
            const isNow = i === td.timeline.length - 1;
            const dotCls = isNow ? (isUp ? 'ds-traj-dot now-up' : 'ds-traj-dot now-down') : 'ds-traj-dot past';
            const monthLabel = td.timelineMonths && td.timelineMonths[i]
              ? (isNow ? 'now' : String(td.timelineMonths[i]).slice(0, 3))
              : (isNow ? 'now' : '');
            return '<div class="ds-traj-step">' +
              '<div class="' + dotCls + '"></div>' +
              '<div class="ds-traj-val">' + currency(Math.round(v)) + '</div>' +
              '<div class="ds-traj-month">' + escapeHtml(monthLabel) + '</div>' +
            '</div>';
          }).join('<div class="ds-traj-arrow">→</div>');

          return '<div class="ds-traj-ui">' +
            '<div class="ds-traj-cat-row">' +
              '<span class="ds-traj-cat-label">Category</span>' +
              '<div class="ds-traj-cat-btns">' + catBtns + '</div>' +
            '</div>' +
            '<div class="ds-traj-label">Spending timeline</div>' +
            '<div class="ds-traj-track">' + dotHtml + '</div>' +
          '</div>';
        }

        // Q7 pace drill: category selector
        if (activeQ && activeQ.id === 'q-pace-drill') {
          const pd = activeQ.paceDrillData;
          if (!pd) return '<div class="ds-pace-drill-ui"></div>';
          const groups = pd.allGroups || [];
          const btns = groups.slice(0, 8).map(function(g) {
            const isActive = g.key === pd.activeGroupKey;
            const label = dsExpenseLabel(g, g && g.key);
            return '<button type="button" class="ds-drill-cat-btn' + (isActive ? ' is-active' : '') + '"' +
              ' data-ds-drill-cat="' + escapeHtml(g.key) + '">' +
              escapeHtml(label) +
            '</button>';
          }).join('');
          return '<div class="ds-pace-drill-ui">' +
            '<div class="ds-pace-drill-row">' +
              '<span class="ds-pace-drill-label">Category</span>' +
              '<div class="ds-drill-cat-btns" id="dsDrillCatBtns">' + btns + '</div>' +
            '</div>' +
          '</div>';
        }

        return buckets.map(function(b) {
          const clampedVal = Math.min(Math.max(b.value, b.min), b.max);
          const displayCurrent = b.currentDisplay != null ? b.currentDisplay : b.current;
          const histNote = b.histAvg !== null ? ' · avg ' + currency(b.histAvg) : '';
          // Use displayCurrent for % calculation — ensures % is relative to allocation target, not mid-month actual spend
          const pctBase = displayCurrent > 0 ? displayCurrent : b.current;
          const pctDisabled = pctBase <= 0;
          const pctVal = !pctDisabled
            ? ((clampedVal / pctBase - 1) * 100).toFixed(1)
            : '';

          // Basket: fixed 3-cell grid — labels only in buttons, delta shown separately below
          const savedBasketKey = month.scenario && month.scenario.bucketOverrides && month.scenario.bucketOverrides[b.basketBucketId];
          let basketHtml = '';
          let basketDeltaHtml = '';
          if (b.basket && b.basket.length >= 1) {
            // Build button grid
            basketHtml = '<div class="ds-basket" data-ds-basket="' + b.basketBucketId + '">' +
              b.basket.map(function(c) {
                const isActive = savedBasketKey ? c.opt.key === savedBasketKey : c === b.basket[0];
                const tooltipText = c.label + ' — ' + c.reason +
                  (c.allocTarget != null ? ' (allocation: ' + currency(c.allocTarget) + ')' : '');
                return '<button type="button" class="ds-basket-btn' + (isActive ? ' is-active' : '') + '"' +
                  ' data-ds-basket-key="' + escapeHtml(c.opt.key) + '"' +
                  ' data-ds-basket-id="' + escapeHtml(b.basketBucketId) + '"' +
                  ' title="' + escapeHtml(tooltipText) + '">' +
                  escapeHtml(c.label) +
                '</button>';
              }).join('') +
            '</div>';

            // Separate anchored delta line — always present, updates on selection
            const activeCandidate = savedBasketKey
              ? b.basket.find(function(c) { return c.opt.key === savedBasketKey; }) || b.basket[0]
              : b.basket[0];
            if (activeCandidate && activeCandidate.allocDelta != null && activeCandidate.allocDelta > 0) {
              const isGain = activeCandidate.isGain;
              const allocBase = activeCandidate.allocTarget != null ? activeCandidate.allocTarget : activeCandidate.base || 0;
              if (isGain) {
                // Gain allocation basket: show + framing (where money goes TO)
                const gainTarget = allocBase + activeCandidate.allocDelta;
                const totalGain = b.basket.reduce(function(s, c) { return s + (c.allocDelta || 0); }, 0);
                const gainContext = totalGain > activeCandidate.allocDelta
                  ? ' — ' + currency(activeCandidate.allocDelta) + ' of ' + currency(totalGain) + ' gain'
                  : '';
                basketDeltaHtml = '<div class="ds-basket-delta-line">' +
                  'Suggested: ' + escapeHtml(activeCandidate.label) +
                  ' from <strong>' + currency(allocBase) + '</strong>' +
                  ' → <strong class="ds-positive">' + currency(gainTarget) + '</strong>' +
                  ' <span class="ds-positive">(+' + currency(Math.round(activeCandidate.allocDelta)) + gainContext + ')</span>' +
                '</div>';
              } else {
                // Cut basket: show − framing (Q4 style)
                const suggestedTarget = Math.max(0, allocBase - activeCandidate.allocDelta);
                const totalGap = b.basket.reduce(function(s, c) { return s + (c.allocDelta || 0); }, 0);
                const gapContext = totalGap > activeCandidate.allocDelta
                  ? ' — your share of ' + currency(totalGap) + ' total gap'
                  : '';
                basketDeltaHtml = '<div class="ds-basket-delta-line">' +
                  'Suggested: ' + escapeHtml(activeCandidate.label) +
                  ' from <strong>' + currency(allocBase) + '</strong>' +
                  ' → <strong class="ds-negative">' + currency(suggestedTarget) + '</strong>' +
                  ' <span class="ds-negative">(−' + currency(Math.round(activeCandidate.allocDelta)) + gapContext + ')</span>' +
                '</div>';
              }
            } else {
              basketDeltaHtml = '<div class="ds-basket-delta-line" aria-hidden="true">&nbsp;</div>';
            }
          }

          // noSlider buckets (gain allocation display bucket) — render basket + delta only, no slider
          if (b.noSlider) {
            const gainTotal = b.basket ? b.basket.reduce(function(s, c) { return s + (c.allocDelta || 0); }, 0) : 0;
            return '<div class="ds-bucket">' +
              '<div class="ds-bucket-label">' +
                escapeHtml(b.label) +
                (gainTotal > 0 ? '<span class="ds-positive">+' + currency(gainTotal) + ' to allocate</span>' : '<span></span>') +
              '</div>' +
              basketHtml +
              basketDeltaHtml +
            '</div>';
          }

          return '<div class="ds-bucket">' +
            '<div class="ds-bucket-label">' +
              escapeHtml(b.label) +
              '<span>' + (b.currentDisplay != null ? 'allocation ' : 'now ') + currency(displayCurrent) + histNote + '</span>' +
            '</div>' +
            (b.reasonNote ? '<div class="ds-bucket-reason">↳ ' + escapeHtml(b.reasonNote) + '</div>' : '') +
            basketHtml +
            basketDeltaHtml +
            '<div class="ds-slider-wrap">' +
              '<input type="range" class="ds-slider" data-ds-id="' + b.id + '"' +
                ' min="' + b.min + '" max="' + b.max + '" step="' + b.step + '"' +
                ' value="' + clampedVal + '">' +
              '<div class="ds-input-wrap">' +
                '<input type="number" class="ds-amount-input" data-ds-input="' + b.id + '"' +
                  ' min="' + b.min + '" max="' + b.max + '" step="' + b.step + '"' +
                  ' value="' + clampedVal.toFixed(0) + '" placeholder="EUR">' +
                '<button type="button" class="ds-apply-btn" data-ds-apply="' + b.id + '" title="Confirm (Enter)">✓</button>' +
              '</div>' +
              '<div class="ds-input-wrap">' +
                '<input type="number" class="ds-pct-input" data-ds-pct="' + b.id + '"' +
                  ' step="0.5"' +
                  (pctDisabled ? ' disabled' : '') +
                  ' value="' + (pctDisabled ? '' : pctVal) + '" placeholder="%">' +
                '<span class="ds-pct-suffix">%</span>' +
                '<button type="button" class="ds-apply-btn" data-ds-apply-pct="' + b.id + '"' +
                  (pctDisabled ? ' disabled title="% not applicable here"' : ' title="Confirm % (Enter)"') + '>✓</button>' +
              '</div>' +
            '</div>' +
          '</div>';
        }).join('');
      }

      // ── Standard question dropdown HTML ────────────────────────────────
      function buildPickerHtml(questions, activeQ) {
        const optionRows = questions.map(function(q) {
          const isActive = activeQ && q.id === activeQ.id;
          const label = q.badge && q.badge.label
            ? q.badge.label + ' — ' + q.label
            : q.label;
          return '<option value="' + q.id + '"' + (isActive ? ' selected' : '') + '>' +
            escapeHtml(label) +
            '</option>';
        }).join('');

        return '<div class="ds-standard-picker">' +
          '<select class="ds-question-select" id="dsQuestionSelect" aria-label="Decision Simulator question">' +
            optionRows +
          '</select>' +
        '</div>';
      }

      const pickerHtml = buildPickerHtml(questions, activeQ);
      const quickInputHtml = buildQuickInputHtml(activeQ);
      const quickContextHtml = buildQuickContextHtml(activeQ);
      const framingHtml = activeQ
        ? '<div class="ds-question-framing" id="dsFraming">' + escapeHtml(activeQ.framing) + '</div>'
        : '';
      const bucketHtml = activeQ ? buildBucketHtml(activeQ.buckets) : '';
      const outcomeHtml = activeQ
        ? buildOutcomeHtml(activeQ.buckets, activeQ, false)
        : '<div class="ds-outcomes" data-ds-outcomes>' +
            '<div class="ds-outcome-row"><span>Spending room per day</span>' +
              '<div class="ds-outcome-val"><strong>—</strong></div></div>' +
            '<div class="ds-outcome-row"><span>Budget freed for savings</span>' +
              '<div class="ds-outcome-val"><strong>—</strong></div></div>' +
            '<div class="ds-outcome-row"><span>Expense share of income</span>' +
              '<div class="ds-outcome-val"><strong>—</strong></div></div>' +
          '</div>';

      const sec = document.createElement('section');
      sec.className = 'planner-card planner-card-scenario ui-3d-decision';
      sec.setAttribute('data-card-key', 'plan_scenario');
      sec.setAttribute('data-planner-card', 'plan_scenario');
      sec.innerHTML = headerHtml +
        '<div class="ds-question-row">' +
          pickerHtml +
          quickInputHtml +
        '</div>' +
        quickContextHtml +
        framingHtml +
        '<div class="ds-body">' +
          '<div class="ds-buckets-wrap" id="dsBuckets">' + bucketHtml + '</div>' +
          '<div class="ds-outcome-wrap" id="dsOutcomeWrap">' + outcomeHtml + '</div>' +
        '</div>';

      // ── Event wiring ────────────────────────────────────────────────────

      // Persist a committed value: snaps slider, refreshes outcomes
      function persistBucketValue(bucketId, rawVal) {
        if (!activeQ) return;
        const val = Math.max(0, Number.isFinite(Number(rawVal)) ? Number(rawVal) : 0);
        month.scenario = month.scenario || { questionKey: activeQ.id, adjustments: [] };
        month.scenario.adjustments = month.scenario.adjustments || [];
        const existing = month.scenario.adjustments.find(function(a) { return a.id === bucketId; });
        if (existing) { existing.amount = val; } else { month.scenario.adjustments.push({ id: bucketId, amount: val }); }
        markDirty();

        const sliderEl = sec.querySelector('.ds-slider[data-ds-id="' + bucketId + '"]');
        if (sliderEl) sliderEl.value = Math.min(Math.max(val, Number(sliderEl.min)), Number(sliderEl.max));

        const eurEl = sec.querySelector('[data-ds-input="' + bucketId + '"]');
        if (eurEl) eurEl.value = Math.round(val);
        const bucket = activeQ.buckets.find(function(b) { return b.id === bucketId; });
        const pctEl = sec.querySelector('[data-ds-pct="' + bucketId + '"]');
        if (pctEl && !pctEl.disabled && bucket && bucket.current > 0) {
          pctEl.value = eurToPct(val, bucket.current).toFixed(1);
        }

        const liveQ = dsGenerateQuestions(month, historyMonths).find(function(q) { return q.id === activeQ.id; }) || activeQ;
        const outWrap = sec.querySelector('#dsOutcomeWrap');
        if (outWrap) outWrap.innerHTML = buildOutcomeHtml(liveQ.buckets, liveQ, false);
      }

      // Helper: EUR ↔ % conversion
      function pctToEur(pct, current) { return Math.max(0, current * (1 + pct / 100)); }
      function eurToPct(eur, current) { return current > 0 ? ((eur / current) - 1) * 100 : 0; }

      // ── Quick-input wiring ─────────────────────────────────────────────
      function getActiveQiMode() {
        if (!activeQ || !activeQ.quickInput) return 'eur';
        const qi = activeQ.quickInput;
        if (!qi.toggleable) return qi.type;
        const saved = month.scenario && month.scenario.quickInputMode;
        return (saved === 'eur' || saved === 'pct') ? saved : qi.type;
      }

      function commitQuickInput(rawVal) {
        if (!activeQ || !activeQ.quickInput || activeQ.quickInput.disabled) return;
        const qi = activeQ.quickInput;
        const mode = getActiveQiMode();
        const numVal = Number(rawVal) || 0;

        if (activeQ.id === 'q-savings') {
          const incBase = qi.incomeBase || 1;
          const savBase = qi.savingsBase || dsSavingsAllocation(month) || 0;
          // numVal = the INCREASE (EUR or % of income)
          const increaseEur = mode === 'pct' ? Math.round(numVal / 100 * incBase) : numVal;
          const eurVal = Math.max(0, savBase + increaseEur);
          const newGap = Math.max(0, increaseEur);
          // Auto-set offset bucket proportional share of the increase
          const offsetB = activeQ.buckets.find(function(b) { return b.id === 'b-sav-offset'; });
          if (offsetB && newGap > 0) {
            const offsetAllocBase = offsetB.currentDisplay != null ? offsetB.currentDisplay : offsetB.current;
            const basket = offsetB.basket || [];
            const activeC = basket.find(function(c) { return c.opt && c.opt.key === offsetB.key; }) || basket[0];
            const totalBasketScore = basket.reduce(function(s, c) { return s + (c.score || 0); }, 0) || 1;
            const candidateScore = activeC ? (activeC.score || 0) : totalBasketScore / 3;
            const share = Math.min(Math.round(newGap * candidateScore / totalBasketScore), offsetAllocBase);
            const offsetTarget = Math.max(0, offsetAllocBase - share);
            month.scenario = month.scenario || { questionKey: activeQ.id, adjustments: [] };
            month.scenario.adjustments = month.scenario.adjustments || [];
            const existing = month.scenario.adjustments.find(function(a) { return a.id === 'b-sav-offset'; });
            if (existing) { existing.amount = offsetTarget; } else { month.scenario.adjustments.push({ id: 'b-sav-offset', amount: offsetTarget }); }
          }
          month.scenario = month.scenario || { questionKey: activeQ.id, adjustments: [] };
          month.scenario.quickInputVal = numVal;
          const savAdj = month.scenario.adjustments ? month.scenario.adjustments.find(function(a) { return a.id === 'b-sav-main'; }) : null;
          if (savAdj) { savAdj.amount = eurVal; } else { (month.scenario.adjustments = month.scenario.adjustments || []).push({ id: 'b-sav-main', amount: eurVal }); }
          pushHistory(); markDirty(); render('planning'); return;
        }

        if (activeQ.id === 'q-income') {
          const incBase = qi.incomeBase || 0;
          const savedMode = month.scenario && month.scenario.quickInputMode;
          const incMode = qi.toggleable && (savedMode === 'eur' || savedMode === 'pct') ? savedMode : (qi.type || 'eur');
          // numVal = the INCREASE (EUR or %)
          const increaseEur = incMode === 'pct' ? Math.round(incBase * numVal / 100) : numVal;
          const totalIncomeTgt = incBase + increaseEur;

          month.scenario = month.scenario || { questionKey: activeQ.id, adjustments: [] };
          month.scenario.adjustments = month.scenario.adjustments || [];
          month.scenario.quickInputVal = numVal;

          // Set income bucket to absolute total
          const incAdj = month.scenario.adjustments.find(function(a) { return a.id === 'b-inc-main'; });
          if (incAdj) { incAdj.amount = totalIncomeTgt; } else { month.scenario.adjustments.push({ id: 'b-inc-main', amount: totalIncomeTgt }); }

          // Update all gain allocation buckets proportionally
          const basket = activeQ.gainAllocationBasket || [];
          basket.forEach(function(c) {
            // Recalculate each candidate's share proportionally to the new increaseEur
            const originalGain = (qi.seedEur || 0);
            const ratio = originalGain > 0 ? increaseEur / originalGain : 1;
            const newShare = Math.round((c.share || 0) * ratio);
            const newTarget = (c.allocTarget || 0) + newShare;
            const existing = month.scenario.adjustments.find(function(a) { return a.id === c.bucketId; });
            if (existing) { existing.amount = newTarget; } else { month.scenario.adjustments.push({ id: c.bucketId, amount: newTarget }); }
          });

          pushHistory(); markDirty(); render('planning'); return;
        }

        if (activeQ.id === 'q-subs') {
          // numVal = the per-cycle cost the user entered; cadence is stored separately
          month.scenario = month.scenario || { questionKey: activeQ.id, adjustments: [] };
          month.scenario.adjustments = month.scenario.adjustments || [];
          month.scenario.quickInputVal = Math.max(0, numVal);
          pushHistory(); markDirty(); render('planning'); return;
        }

        // Q1 and Q2: input is absolute EUR target for primary bucket → full re-render
        month.scenario = month.scenario || { questionKey: activeQ.id, adjustments: [] };
        month.scenario.adjustments = month.scenario.adjustments || [];
        month.scenario.quickInputVal = numVal;
        const primId = qi.primaryBucket;
        const primAdj = month.scenario.adjustments.find(function(a) { return a.id === primId; });
        if (primAdj) { primAdj.amount = numVal; } else { month.scenario.adjustments.push({ id: primId, amount: numVal }); }
        pushHistory(); markDirty(); render('planning');
      }

      const quickField = sec.querySelector('#dsQuickField');
      const quickConfirm = sec.querySelector('#dsQuickConfirm');
      const quickUnit = sec.querySelector('#dsQuickUnit');

      // Unit toggle click — flips EUR ↔ % for toggleable questions, converts value
      if (quickUnit && activeQ && activeQ.quickInput && activeQ.quickInput.toggleable) {
        quickUnit.addEventListener('click', function() {
          const qi = activeQ.quickInput;
          const currentMode = getActiveQiMode();
          const newMode = currentMode === 'pct' ? 'eur' : 'pct';
          let newVal = '';
          const fieldVal = Number(quickField && quickField.value) || 0;
          if (activeQ.id === 'q-savings') {
            // Increase mode: pct = % of income, eur = EUR increase
            const incBase = qi.incomeBase || 1;
            if (currentMode === 'pct' && newMode === 'eur') {
              newVal = Math.round(incBase * fieldVal / 100);
            } else {
              newVal = incBase > 0 ? (fieldVal / incBase * 100).toFixed(1) : '';
            }
          } else if (activeQ.id === 'q-income') {
            // Increase mode: pct = % increase of current income, eur = EUR increase
            const incBase = qi.incomeBase || 1;
            if (currentMode === 'pct' && newMode === 'eur') {
              newVal = Math.round(incBase * fieldVal / 100);
            } else {
              newVal = incBase > 0 ? (fieldVal / incBase * 100).toFixed(1) : '';
            }
          }
          month.scenario = month.scenario || { questionKey: activeQ.id, adjustments: [] };
          month.scenario.quickInputMode = newMode;
          month.scenario.quickInputVal = Number(newVal) || null;
          markDirty();
          render('planning');
        });
      }

      if (quickField) {
        quickField.addEventListener('input', function() {
          if (!activeQ || !activeQ.quickInput || activeQ.quickInput.disabled) return;
          const qi = activeQ.quickInput;
          const mode = getActiveQiMode();
          let eurVal;
          if (activeQ.id === 'q-savings') {
            // Input = increase; show total (base + increase) on the savings slider
            const incBase = qi.incomeBase || 1;
            const savBase = qi.savingsBase || dsSavingsAllocation(month) || 0;
            const increaseAmt = mode === 'pct'
              ? Math.round(incBase * (Number(quickField.value) || 0) / 100)
              : Number(quickField.value) || 0;
            eurVal = Math.max(0, savBase + increaseAmt);
          } else if (activeQ.id === 'q-income') {
            // Input = increase amount; show total on the salary slider
            const incBase = qi.incomeBase || 0;
            const increaseAmt = mode === 'pct'
              ? Math.round(incBase * (Number(quickField.value) || 0) / 100)
              : Number(quickField.value) || 0;
            eurVal = incBase + increaseAmt;
          } else {
            eurVal = Number(quickField.value) || 0;
          }
          const eurEl = sec.querySelector('[data-ds-input="' + qi.primaryBucket + '"]');
          if (eurEl) eurEl.value = Math.round(eurVal);
        });
        quickField.addEventListener('keydown', function(e) {
          if (e.key === 'Enter') { e.preventDefault(); commitQuickInput(quickField.value); }
        });
      }
      if (quickConfirm) {
        quickConfirm.addEventListener('click', function() {
          if (quickField) commitQuickInput(quickField.value);
        });
      }

      // Slider drag — syncs display fields only; commits on release
      sec.querySelectorAll('.ds-slider').forEach(function(slider) {
        const id = slider.dataset.dsId;
        slider.addEventListener('input', function() {
          const val = Number(slider.value);
          const eurEl = sec.querySelector('[data-ds-input="' + id + '"]');
          if (eurEl) eurEl.value = Math.round(val);
          const bucket = activeQ && activeQ.buckets.find(function(b) { return b.id === id; });
          const pctEl = sec.querySelector('[data-ds-pct="' + id + '"]');
          if (pctEl && !pctEl.disabled && bucket && bucket.current > 0) {
            pctEl.value = eurToPct(val, bucket.current).toFixed(1);
          }
        });
        slider.addEventListener('change', function() {
          pushHistory();
          persistBucketValue(id, Number(slider.value));
        });
      });

      // EUR input — sync % only; no slider, no commit while typing
      sec.querySelectorAll('.ds-amount-input').forEach(function(input) {
        const id = input.dataset.dsInput;
        const bucket = activeQ && activeQ.buckets.find(function(b) { return b.id === id; });
        input.addEventListener('input', function() {
          const pctEl = sec.querySelector('[data-ds-pct="' + id + '"]');
          if (pctEl && !pctEl.disabled && bucket && bucket.current > 0) {
            pctEl.value = eurToPct(Math.max(0, Number(input.value) || 0), bucket.current).toFixed(1);
          }
        });
        input.addEventListener('keydown', function(e) {
          if (e.key === 'Enter') { e.preventDefault(); pushHistory(); persistBucketValue(id, Number(input.value) || 0); }
        });
      });

      // % input — sync EUR only; no slider, no commit while typing
      sec.querySelectorAll('.ds-pct-input').forEach(function(input) {
        const id = input.dataset.dsPct;
        const bucket = activeQ && activeQ.buckets.find(function(b) { return b.id === id; });
        input.addEventListener('input', function() {
          if (input.disabled || !bucket || bucket.current <= 0) return;
          const eurEl = sec.querySelector('[data-ds-input="' + id + '"]');
          if (eurEl) eurEl.value = Math.round(pctToEur(Number(input.value) || 0, bucket.current));
        });
        input.addEventListener('keydown', function(e) {
          if (e.key === 'Enter' && !input.disabled) {
            e.preventDefault();
            if (!bucket || bucket.current <= 0) return;
            pushHistory();
            persistBucketValue(id, pctToEur(Number(input.value) || 0, bucket.current));
          }
        });
      });

      // EUR confirm buttons
      sec.querySelectorAll('.ds-apply-btn[data-ds-apply]').forEach(function(btn) {
        const id = btn.dataset.dsApply;
        btn.addEventListener('click', function() {
          const inputEl = sec.querySelector('[data-ds-input="' + id + '"]');
          if (!inputEl) return;
          pushHistory();
          persistBucketValue(id, Number(inputEl.value) || 0);
        });
      });

      // % confirm buttons
      sec.querySelectorAll('.ds-apply-btn[data-ds-apply-pct]').forEach(function(btn) {
        const id = btn.dataset.dsApplyPct;
        const bucket = activeQ && activeQ.buckets.find(function(b) { return b.id === id; });
        btn.addEventListener('click', function() {
          if (btn.disabled || !bucket || bucket.current <= 0) return;
          const pctEl = sec.querySelector('[data-ds-pct="' + id + '"]');
          if (!pctEl) return;
          pushHistory();
          persistBucketValue(id, pctToEur(Number(pctEl.value) || 0, bucket.current));
        });
      });

      // Basket picker — clicking a candidate switches the active offset category
      sec.querySelectorAll('.ds-basket-btn').forEach(function(btn) {
        btn.addEventListener('click', function() {
          const basketId = btn.dataset.dsBaskId || btn.dataset.dsBasketId;
          const newKey = btn.dataset.dsBasketKey;
          if (!basketId || !newKey) return;
          month.scenario = month.scenario || { questionKey: activeQ && activeQ.id, adjustments: [] };
          month.scenario.bucketOverrides = month.scenario.bucketOverrides || {};
          month.scenario.bucketOverrides[basketId] = newKey;
          // Clear any saved adjustment for this bucket so it reseeds from the new category
          month.scenario.adjustments = (month.scenario.adjustments || []).filter(function(a) {
            return a.id !== basketId;
          });
          markDirty();
          render('planning');
        });
      });

      // Cadence toggle for q-subs
      sec.querySelectorAll('.ds-cadence-btn').forEach(function(btn) {
        btn.addEventListener('click', function() {
          const newCadence = btn.dataset.dsCadence;
          if (!newCadence) return;
          month.scenario = month.scenario || { questionKey: 'q-subs', adjustments: [] };
          month.scenario.subsSimCadence = newCadence;
          // Keep the same input amount but clear quickInputVal so it reseeds to the cadence default
          // only if user hasn't explicitly set a value yet
          markDirty();
          render('planning');
        });
      });

      // Category selector for q-pace-drill
      sec.querySelectorAll('.ds-drill-cat-btn').forEach(function(btn) {
        btn.addEventListener('click', function() {
          const newCat = btn.dataset.dsDrillCat;
          if (!newCat) return;
          month.scenario = month.scenario || { questionKey: 'q-pace-drill', adjustments: [] };
          month.scenario.paceDrillCategory = newCat;
          markDirty();
          render('planning');
        });
      });

      // Category selector for q-trajectory
      sec.querySelectorAll('.ds-traj-cat-btn').forEach(function(btn) {
        btn.addEventListener('click', function() {
          const newCat = btn.dataset.dsTrajCat;
          if (!newCat) return;
          month.scenario = month.scenario || { questionKey: 'q-trajectory', adjustments: [] };
          month.scenario.trajCategory = newCat;
          markDirty();
          render('planning');
        });
      });

      // ── Standard dropdown: select question ─────────────────────────────
      function selectQuestion(qid) {
        const newQ = questions.find(function(q) { return q.id === qid; }) || questions[0];
        qid = newQ.id;
        const preservedIds = newQ ? newQ.buckets.map(function(b) { return b.id; }) : [];
        const existingAdj = month.scenario && Array.isArray(month.scenario.adjustments)
          ? month.scenario.adjustments.filter(function(a) { return preservedIds.includes(a.id); })
          : [];
        const existingOverrides = month.scenario && month.scenario.bucketOverrides
          ? Object.fromEntries(
              Object.entries(month.scenario.bucketOverrides).filter(function(kv) {
                return preservedIds.includes(kv[0]);
              })
            )
          : {};
        month.scenario = { questionKey: qid, adjustments: existingAdj, bucketOverrides: existingOverrides };
        markDirty();
        render('planning');
      }

      const questionSelect = sec.querySelector('#dsQuestionSelect');
      if (questionSelect) {
        questionSelect.addEventListener('change', function() {
          selectQuestion(questionSelect.value);
        });
      }

      // Reset (in card header)
      const clearBtn = sec.querySelector('#dsClearBtn');
      if (clearBtn) {
        clearBtn.addEventListener('click', function() {
          month.scenario = null;
          markDirty();
          render('planning');
        });
      }

      return sec;
    }

    function financialGoalPercent(item) {
      return Number(item && item.resolved && (item.resolved.pct != null ? item.resolved.pct : item.resolved.percent) || 0);
    }

    function financialGoalsStateClass(item) {
      const pct = financialGoalPercent(item);
      if (pct >= 100) return 'state-complete';
      if (pct < 50) return 'state-lagging';
      return 'state-active';
    }

    function financialGoalsProgressFillClass(item) {
      const pct = financialGoalPercent(item);
      if (pct >= 100) return 'complete';
      if (pct < 50) return 'lagging';
      return '';
    }

    function financialGoalDraftState() {
      state.financialGoalDraftByMonth = state.financialGoalDraftByMonth || {};
      return state.financialGoalDraftByMonth;
    }
    function financialGoalDraftFor(month) {
      const monthName = String(month && month.name || '');
      return monthName ? (financialGoalDraftState()[monthName] || null) : null;
    }
    function setFinancialGoalDraft(month, draft) {
      const monthName = String(month && month.name || '');
      if (!monthName) return;
      if (draft) financialGoalDraftState()[monthName] = draft;
      else delete financialGoalDraftState()[monthName];
    }
    function makeFinancialGoalDraft(month) {
      const nextNum = (Array.isArray(month && month.goals) ? month.goals.length : 0) + 1;
      return { id:'goal-draft-' + Date.now() + '-' + Math.floor(Math.random()*1000), name:'Goal ' + nextNum, targetKey:'', goalAmount:0, goalMode:'monthly', baseProgress:0, matchWords:'', keywordDraft:'' };
    }

    function financialGoalHistoryStore() {
      state.financialGoalHistory = Array.isArray(state.financialGoalHistory) ? state.financialGoalHistory : [];
      return state.financialGoalHistory;
    }
    function financialGoalHistoryKey(monthName, goalId) { return String(monthName || '') + '::' + String(goalId || ''); }
    function recordCompletedFinancialGoal(month, goal, item) {
      if (!month || !goal) return;
      const pct = item ? financialGoalPercent(item) : Number(resolveGoalProgressForGoal(month, goal).pct || 0);
      if (pct < 100) return;
      const history = financialGoalHistoryStore();
      const key = financialGoalHistoryKey(month.name, goal.id);
      if (history.some(function(entry) { return entry && entry.key === key; })) return;
      const resolved = item && item.resolved ? item.resolved : resolveGoalProgressForGoal(month, goal);
      history.push({ key:key, goalId:goal.id, name:String(goal.name || 'Goal'), sourceLabel:item && item.sourceLabel ? item.sourceLabel : 'No source selected', monthName:month.name, completedAt:new Date().toISOString(), target:Number(goal.goalAmount || resolved.target || 0), progress:Number(resolved.totalProgress || 0), pct:Number(resolved.pct || pct || 0), goalMode:goal.goalMode === 'rolling' ? 'rolling' : 'monthly' });
    }
    function captureCompletedFinancialGoals(month, goalOptions) {
      if (!month || !Array.isArray(month.goals)) return;
      const options = goalOptions || planningBucketOptions(month);
      month.goals.forEach(function(goal, index) { recordCompletedFinancialGoal(month, goal, goalPresentationModel(month, goal, options, index)); });
    }
    function financialGoalHistoryEntries() {
      state.months.forEach(function(month) { captureCompletedFinancialGoals(month, planningBucketOptions(month)); });
      const seen = new Set();
      return financialGoalHistoryStore().filter(function(entry) { if (!entry || !entry.key || seen.has(entry.key)) return false; seen.add(entry.key); return true; }).sort(function(a,b){ return String(b.completedAt || '').localeCompare(String(a.completedAt || '')); });
    }

    function renderFinancialGoalsSummary(month, goalOptions) {
      const safeHtml = window.escapeHtml || escapeHtml;
      captureCompletedFinancialGoals(month, goalOptions || []);
      const tracker = goalTrackerViewModel(month, goalOptions || []);
      const items = tracker.items || [];
      const totalTarget = items.reduce(function(sum, item) { return sum + Number(item && item.resolved && item.resolved.target || 0); }, 0);
      const totalProgress = items.reduce(function(sum, item) { return sum + Number(item && item.resolved && item.resolved.totalProgress || 0); }, 0);
      const completed = items.filter(function(item) { return financialGoalPercent(item) >= 100; }).length;
      const averageProgress = items.length
        ? items.reduce(function(sum, item) { return sum + Math.max(0, Math.min(100, financialGoalPercent(item))); }, 0) / items.length
        : 0;
      const nearest = items.slice().sort(function(a, b) {
        const ad = new Date((a && a.targetDate) || (a && a.resolved && a.resolved.targetDate) || '2999-12-31').getTime();
        const bd = new Date((b && b.targetDate) || (b && b.resolved && b.resolved.targetDate) || '2999-12-31').getTime();
        return ad - bd;
      })[0];

      const rowsHtml = items.length ? items.map(function(item) {
        const pct = Math.max(0, Math.min(100, financialGoalPercent(item)));
        const target = Number(item && item.resolved && item.resolved.target || 0);
        const progress = Number(item && item.resolved && item.resolved.totalProgress || 0);
        const targetLabel = item.targetLabel || currency(target);
        const stateText = pct >= 100 ? 'Completed' : (item.remainingLabel ? item.remainingLabel + ' left' : item.pctLabel);
        return '' +
          '<article class="phase4-goal-card">' +
            '<div class="phase4-goal-card-head">' +
              '<div class="phase4-goal-copy">' +
                '<div class="phase4-goal-kicker">Financial goal</div>' +
                '<div class="phase4-goal-title">' + safeHtml(item.title || 'Untitled goal') + '</div>' +
                '<div class="phase4-goal-source">' + safeHtml(item.sourceLabel || 'No source selected') + '</div>' +
              '</div>' +
              '<span class="phase4-goal-status ' + financialGoalsStateClass(item) + '">' + safeHtml(stateText) + '</span>' +
            '</div>' +
            '<div class="phase4-goal-main">' + currency(progress) + '</div>' +
            '<div class="phase4-goal-meta">' +
              '<div class="phase4-goal-stat"><span class="phase4-goal-stat-label">Target</span><span class="phase4-goal-stat-value">' + safeHtml(targetLabel) + '</span></div>' +
              '<div class="phase4-goal-stat"><span class="phase4-goal-stat-label">Progress</span><span class="phase4-goal-stat-value">' + pct.toFixed(0) + '%</span></div>' +
              '<div class="phase4-goal-stat"><span class="phase4-goal-stat-label">Remaining</span><span class="phase4-goal-stat-value">' + currency(Math.max(target - progress, 0)) + '</span></div>' +
            '</div>' +
            '<div class="phase4-goal-progress">' +
              '<div class="phase4-goal-progress-row"><span>Completion</span><span>' + pct.toFixed(1) + '%</span></div>' +
              '<div class="phase4-goal-progress-track"><span class="phase4-goal-progress-fill ' + financialGoalsProgressFillClass(item) + '" style="width:' + pct + '%"></span></div>' +
            '</div>' +
          '</article>';
      }).join('') : '<div class="phase4-goals-empty">No goals yet. Open the Goals Manager to create your first financial goal.</div>';

      return '' +
        '<section class="phase4-goals-hero">' +
          '<div class="phase4-goals-kpi primary"><div class="phase4-goals-label">Goal progress</div><div class="phase4-goals-value">' + currency(totalProgress) + '</div><div class="phase4-goals-sub">' + completed + ' of ' + items.length + ' goals completed</div></div>' +
          '<div class="phase4-goals-kpi"><div class="phase4-goals-label">Target total</div><div class="phase4-goals-value">' + currency(totalTarget) + '</div><div class="phase4-goals-sub">Combined target across active goals</div></div>' +
          '<div class="phase4-goals-kpi"><div class="phase4-goals-label">Average completion</div><div class="phase4-goals-value">' + averageProgress.toFixed(0) + '%</div><div class="phase4-goals-sub">Average progress across tracked goals</div></div>' +
          '<div class="phase4-goals-kpi"><div class="phase4-goals-label">Next focus</div><div class="phase4-goals-value text-value">' + (nearest ? safeHtml(nearest.title || 'Goal') : '—') + '</div><div class="phase4-goals-sub">' + (nearest ? safeHtml(nearest.remainingLabel || nearest.pctLabel || 'In progress') : 'No goals configured') + '</div></div>' +
        '</section>' +
        '<section class="phase4-goals-board">' +
          '<div class="phase4-goals-board-head"><div><h3 class="phase4-goals-board-title">Financial Goals</h3><div class="phase4-goals-board-sub">Track progress, linked sources, and remaining effort per goal.</div></div><div class="phase4-goals-board-actions"><button class="financial-goals-history-btn feature-action-btn" id="openFinancialGoalsHistoryBtn" type="button" aria-haspopup="dialog" aria-controls="financialGoalsHistoryOverlay">History</button><button class="feature-action-btn is-primary financial-goals-workspace-primary-btn" id="openFinancialGoalsWorkspaceBtn" type="button" aria-haspopup="dialog" aria-controls="financialGoalsManagerOverlay">Goals Manager</button></div></div>' +
          '<div class="phase4-goals-grid">' + rowsHtml + '</div>' +
        '</section>';
    }

    function ensureFinancialGoalsManagerOverlay() {
      let overlay = document.getElementById('financialGoalsManagerOverlay');
      if (!overlay) { overlay = document.createElement('div'); overlay.id = 'financialGoalsManagerOverlay'; overlay.className = 'cbm-overlay financial-goals-manager-overlay'; overlay.setAttribute('data-modal-kind','financial-goals-manager'); overlay.setAttribute('aria-hidden','true'); document.body.appendChild(overlay); }
      if (!overlay.dataset.bound) { overlay.addEventListener('click', function(event) { if (event.target === overlay) closeFinancialGoalsWorkspace(); }); overlay.dataset.bound = 'true'; }
      return overlay;
    }
    function ensureFinancialGoalsHistoryOverlay() {
      let overlay = document.getElementById('financialGoalsHistoryOverlay');
      if (!overlay) { overlay = document.createElement('div'); overlay.id = 'financialGoalsHistoryOverlay'; overlay.className = 'cbm-overlay financial-goals-history-overlay'; overlay.setAttribute('data-modal-kind','financial-goals-history'); overlay.setAttribute('aria-hidden','true'); document.body.appendChild(overlay); }
      if (!overlay.dataset.bound) { overlay.addEventListener('click', function(event) { if (event.target === overlay) closeFinancialGoalsHistory(); }); overlay.dataset.bound = 'true'; }
      return overlay;
    }
    function closeFinancialGoalsWorkspace() { const overlay = document.getElementById('financialGoalsManagerOverlay'); if (overlay) { overlay.classList.remove('cbm-open'); overlay.setAttribute('aria-hidden','true'); } }
    function closeFinancialGoalsHistory() { const overlay = document.getElementById('financialGoalsHistoryOverlay'); if (overlay) { overlay.classList.remove('cbm-open'); overlay.setAttribute('aria-hidden','true'); } }
    function openFinancialGoalsWorkspace() { const month = getActiveMonth(); if (!month) return; renderFinancialGoalsWorkspace(month); const overlay = ensureFinancialGoalsManagerOverlay(); overlay.classList.add('cbm-open'); overlay.setAttribute('aria-hidden','false'); }
    function openFinancialGoalsHistory() { renderFinancialGoalsHistory(); const overlay = ensureFinancialGoalsHistoryOverlay(); overlay.classList.add('cbm-open'); overlay.setAttribute('aria-hidden','false'); }

    function renderFinancialGoalsWorkspace(month) {
      const overlay = ensureFinancialGoalsManagerOverlay();
      const goalOptions = planningBucketOptions(month || {});
      captureCompletedFinancialGoals(month, goalOptions);
      const tracker = goalTrackerViewModel(month, goalOptions);
      const items = tracker.items || [];
      const totalTarget = items.reduce(function(sum, item) { return sum + Number(item && item.resolved && item.resolved.target || 0); }, 0);
      const totalProgress = items.reduce(function(sum, item) { return sum + Number(item && item.resolved && item.resolved.totalProgress || 0); }, 0);
      const completed = items.filter(function(item) { return financialGoalPercent(item) >= 100; }).length;
      const draft = financialGoalDraftFor(month);
      overlay.innerHTML = '<div class="cbm-modal financial-goals-manager-modal" role="dialog" aria-modal="true" aria-labelledby="financialGoalsManagerTitle"><div class="cbm-header"><div><div class="cbm-title" id="financialGoalsManagerTitle">Financial Goals Workspace</div><div class="cbm-sub">Create, confirm, edit and review all goals in one focused view.</div></div><button class="cbm-close-btn" type="button" data-close-financial-goals aria-label="Close goals workspace">×</button></div><div class="financial-goals-workspace-strip"><div class="financial-goals-workspace-stat"><div class="financial-goals-workspace-stat-label">Goals</div><div class="financial-goals-workspace-stat-value">' + items.length + '</div></div><div class="financial-goals-workspace-stat"><div class="financial-goals-workspace-stat-label">Target</div><div class="financial-goals-workspace-stat-value">' + currency(totalTarget) + '</div></div><div class="financial-goals-workspace-stat"><div class="financial-goals-workspace-stat-label">Progress</div><div class="financial-goals-workspace-stat-value">' + currency(totalProgress) + '</div></div><div class="financial-goals-workspace-stat"><div class="financial-goals-workspace-stat-label">Complete</div><div class="financial-goals-workspace-stat-value">' + completed + '/' + items.length + '</div></div></div><div class="financial-goals-manager-body"><section class="financial-goals-workspace-card">' + (draft ? renderFinancialGoalDraftPanel(draft, goalOptions) : '') + renderGoalTrackerPanel(tracker, goalOptions) + '</section></div><div class="cbm-footer"><button class="cbm-btn-ghost" type="button" data-close-financial-goals>Done</button><button class="cbm-btn-primary" type="button" id="addGoalBtn">Add goal</button></div></div>';
      overlay.querySelectorAll('[data-close-financial-goals]').forEach(function(btn) { btn.onclick = closeFinancialGoalsWorkspace; });
      wireGoalTrackerControls(overlay, month, function() { render('goals'); });
      wireFinancialGoalDraftControls(overlay, month, function() { render('goals'); });
    }

    function renderFinancialGoalDraftPanel(draft, goalOptions) {
      const safeHtml = window.escapeHtml || escapeHtml;
      const optionMarkup = (goalOptions || []).map(function(opt) { return '<option value="' + safeHtml(String(opt.key || '')) + '" ' + (draft.targetKey === opt.key ? 'selected' : '') + '>' + safeHtml(String(opt.label || '')) + '</option>'; }).join('');
      const keywordPhrases = goalKeywordPhrases(draft);
      const keywordChipMarkup = keywordPhrases.length ? keywordPhrases.map(function(phrase, idx) { return '<button type="button" class="goal-keyword-chip" data-remove-draft-goal-keyword="' + idx + '" title="Remove keyword">' + safeHtml(phrase) + '<span>×</span></button>'; }).join('') : '<span class="goal-keyword-empty">No keywords added</span>';
      return '<article class="fg-goal-card is-draft"><div class="fg-goal-card-head"><div class="fg-goal-title-block"><div class="fg-goal-title-row"><div class="fg-goal-title">New goal setup</div><span class="financial-goals-state-pill state-active">Draft</span></div><div class="fg-goal-source">Confirm to activate this goal.</div></div></div><div class="fg-goal-form-grid"><div class="fg-goal-field"><label>Name</label><input type="text" data-draft-goal-field="name" value="' + safeHtml(draft.name || '') + '" /></div><div class="fg-goal-field"><label>Source</label><select data-draft-goal-field="targetKey"><option value="">Select bucket</option>' + optionMarkup + '</select></div><div class="fg-goal-field"><label>Goal type</label><select data-draft-goal-field="goalMode"><option value="monthly" ' + (draft.goalMode === 'monthly' ? 'selected' : '') + '>Monthly</option><option value="rolling" ' + (draft.goalMode === 'rolling' ? 'selected' : '') + '>Rolling</option></select></div><div class="fg-goal-field"><label>Goal €</label><input type="number" step="0.01" min="0" data-draft-goal-field="goalAmount" value="' + Number(draft.goalAmount || 0).toFixed(2) + '" /></div><div class="fg-goal-field fg-goal-keywords"><label>Match words (optional)</label><div class="fg-goal-keyword-box"><div class="fg-goal-keyword-chips">' + keywordChipMarkup + '</div><div class="fg-goal-keyword-entry"><input type="text" data-draft-goal-keyword-input value="' + safeHtml(draft.keywordDraft || '') + '" placeholder="Add keyword or phrase" /><button type="button" class="tiny-btn" data-add-draft-goal-keyword>Add</button></div></div></div></div><div class="fg-goal-confirm-row"><div class="fg-goal-confirm-note">This goal will not become active until you confirm it.</div><button type="button" class="fg-goal-cancel-draft" data-cancel-draft-goal>Cancel</button><button type="button" class="fg-goal-confirm-btn" data-confirm-draft-goal>Confirm goal</button></div></article>';
    }

    function renderFinancialGoalsHistory() {
      const safeHtml = window.escapeHtml || escapeHtml;
      const overlay = ensureFinancialGoalsHistoryOverlay();
      const items = financialGoalHistoryEntries();
      const body = items.length ? '<div class="financial-goals-history-list">' + items.map(function(entry) { return '<article class="financial-goals-history-item"><div class="financial-goals-history-top"><div><div class="financial-goals-history-title">' + safeHtml(entry.name || 'Completed goal') + '</div><div class="financial-goals-history-meta">Completed in ' + safeHtml(entry.monthName || 'Unknown month') + ' · ' + safeHtml(entry.sourceLabel || 'No source selected') + '</div></div><span class="financial-goals-state-pill state-complete">Completed</span></div><div class="financial-goals-history-amounts"><div class="fg-goal-metric"><div class="fg-goal-metric-label">Target</div><div class="fg-goal-metric-value">' + currency(entry.target || 0) + '</div></div><div class="fg-goal-metric"><div class="fg-goal-metric-label">Progress</div><div class="fg-goal-metric-value">' + currency(entry.progress || 0) + '</div></div><div class="fg-goal-metric"><div class="fg-goal-metric-label">Result</div><div class="fg-goal-metric-value">' + Number(entry.pct || 0).toFixed(1) + '%</div></div></div></article>'; }).join('') + '</div>' : '<div class="financial-goals-history-empty">No completed goals have moved into history yet.</div>';
      overlay.innerHTML = '<div class="cbm-modal financial-goals-history-modal" role="dialog" aria-modal="true" aria-labelledby="financialGoalsHistoryTitle"><div class="cbm-header"><div><div class="cbm-title" id="financialGoalsHistoryTitle">Financial Goals History</div><div class="cbm-sub">Completed goals are collected here once they are no longer part of the active goal workspace.</div></div><button class="cbm-close-btn" type="button" data-close-financial-goals-history aria-label="Close goals history">×</button></div><div class="financial-goals-history-body">' + body + '</div><div class="cbm-footer"><button class="cbm-btn-ghost" type="button" data-close-financial-goals-history>Done</button></div></div>';
      overlay.querySelectorAll('[data-close-financial-goals-history]').forEach(function(btn) { btn.onclick = closeFinancialGoalsHistory; });
    }

    function wireGoalTrackerControls(root, month, rerenderFn) {
      if (!root || !month) return;
      const rerender = typeof rerenderFn === 'function' ? rerenderFn : function() { render('goals'); };
      const addGoalBtn = root.querySelector('#addGoalBtn');
      if (addGoalBtn) addGoalBtn.onclick = function() {
        if (!financialGoalDraftFor(month)) setFinancialGoalDraft(month, makeFinancialGoalDraft(month));
        rerender();
      };

      root.querySelectorAll("[data-delete-goal]").forEach(function(btn) {
        btn.onclick = function() {
          pushHistory();
          markDirty();
          const previousIndex = goalTrackerStateFor(month).activeIndex;
          month.goals = (month.goals || []).filter(function(goal) { return goal.id !== btn.dataset.deleteGoal; });
          setGoalTrackerActiveIndex(month, previousIndex);
          rerender();
        };
      });

      root.querySelectorAll("[data-goal-nav]").forEach(function(btn) {
        btn.onclick = function() {
          const trackerState = goalTrackerStateFor(month);
          if (trackerState.goalCount <= 1) return;
          const delta = btn.dataset.goalNav === "prev" ? -1 : 1;
          const nextIndex = (trackerState.activeIndex + delta + trackerState.goalCount) % trackerState.goalCount;
          setGoalTrackerActiveIndex(month, nextIndex);
          rerender();
        };
      });

      root.querySelectorAll("[data-goal-index]").forEach(function(btn) {
        btn.onclick = function() {
          setGoalTrackerActiveIndex(month, Number(btn.dataset.goalIndex || 0));
          rerender();
        };
      });

      root.querySelectorAll("[data-add-goal-keyword]").forEach(function(btn) {
        btn.onclick = function(e) {
          e.preventDefault();
          const localGoal = (month.goals || []).find(function(item) { return item.id === btn.dataset.addGoalKeyword; });
          const input = root.querySelector('[data-goal-keyword-input="' + btn.dataset.addGoalKeyword + '"]');
          if (!localGoal) return;
          const target = resolveGoalEditTarget(month, localGoal);
          const goal = target.goal;
          if (!goal) return;
          const rawValue = input ? input.value : (localGoal.keywordDraft || goal.keywordDraft);
          const value = String(rawValue || '').trim().replace(/^,+|,+$/g, '');
          if (!value) return;
          const phrases = goalKeywordPhrases(goal);
          const exists = phrases.some(function(part) { return part.toLowerCase() === value.toLowerCase(); });
          pushHistory();
          markDirty();
          if (!exists) phrases.push(value);
          syncGoalFieldsAcrossMonths(goal.id, { matchWords: phrases.join(', '), keywordDraft: '' });
          rerender();
        };
      });

      root.querySelectorAll("[data-goal-keyword-input]").forEach(function(input) {
        input.oninput = function() {
          const localGoal = (month.goals || []).find(function(item) { return item.id === input.dataset.goalKeywordInput; });
          if (!localGoal) return;
          syncGoalFieldsAcrossMonths(localGoal.id, { keywordDraft: input.value || '' });
        };
        input.onkeydown = function(e) {
          if (e.key === 'Enter' || e.key === ',') {
            e.preventDefault();
            const btn = root.querySelector('[data-add-goal-keyword="' + input.dataset.goalKeywordInput + '"]');
            if (btn) btn.click();
          }
        };
      });

      root.querySelectorAll("[data-remove-goal-keyword]").forEach(function(btn) {
        btn.onclick = function() {
          const localGoal = (month.goals || []).find(function(item) { return item.id === btn.dataset.removeGoalKeyword; });
          if (!localGoal) return;
          const target = resolveGoalEditTarget(month, localGoal);
          const goal = target.goal;
          if (!goal) return;
          const idx = Number(btn.dataset.goalKeywordIndex || -1);
          const phrases = goalKeywordPhrases(goal);
          if (idx < 0 || idx >= phrases.length) return;
          pushHistory();
          markDirty();
          phrases.splice(idx, 1);
          syncGoalFieldsAcrossMonths(goal.id, { matchWords: phrases.join(', '), keywordDraft: '' });
          rerender();
        };
      });

      root.querySelectorAll("[data-goal-field]").forEach(function(input) {
        const commitGoalField = function() {
          const localGoal = (month.goals || []).find(function(item) { return item.id === input.dataset.goalId; });
          if (!localGoal) return;
          const target = resolveGoalEditTarget(month, localGoal);
          const goal = target.goal || localGoal;
          pushHistory();
          markDirty();
          if (input.dataset.goalField === "goalAmount") {
            const num = parseFloat(input.value);
            syncGoalFieldsAcrossMonths(goal.id, { goalAmount: Number.isFinite(num) ? num : 0 });
          } else {
            syncGoalFieldsAcrossMonths(goal.id, { [input.dataset.goalField]: input.value });
          }
          rerender();
        };
        if (input.tagName === 'INPUT' && input.type === 'text') {
          input.oninput = function() {
            const localGoal = (month.goals || []).find(function(item) { return item.id === input.dataset.goalId; });
            if (!localGoal) return;
            syncGoalFieldsAcrossMonths(localGoal.id, { [input.dataset.goalField]: input.value });
          };
          input.onblur = commitGoalField;
          input.onkeydown = function(e) {
            if (e.key === 'Enter') {
              e.preventDefault();
              commitGoalField();
            }
          };
        } else {
          input.onchange = commitGoalField;
        }
      });
    }


    function wireFinancialGoalDraftControls(root, month, rerenderFn) {
      if (!root || !month) return;
      const rerender = typeof rerenderFn === 'function' ? rerenderFn : function() { render('goals'); };
      root.querySelectorAll('[data-draft-goal-field]').forEach(function(input) {
        const updateDraftField = function() { const draft = financialGoalDraftFor(month); if (!draft) return; if (input.dataset.draftGoalField === 'goalAmount') { const num = parseFloat(String(input.value || '').replace(',', '.')); draft.goalAmount = Number.isFinite(num) ? num : 0; } else { draft[input.dataset.draftGoalField] = input.value; } setFinancialGoalDraft(month, draft); };
        input.oninput = updateDraftField; input.onchange = updateDraftField;
      });
      const keywordInput = root.querySelector('[data-draft-goal-keyword-input]');
      const addKeywordBtn = root.querySelector('[data-add-draft-goal-keyword]');
      function addDraftKeyword() { const draft = financialGoalDraftFor(month); if (!draft || !keywordInput) return; const value = String(keywordInput.value || '').trim().replace(/^,+|,+$/g, ''); if (!value) return; const phrases = goalKeywordPhrases(draft); if (!phrases.some(function(part) { return part.toLowerCase() === value.toLowerCase(); })) phrases.push(value); draft.matchWords = phrases.join(', '); draft.keywordDraft = ''; setFinancialGoalDraft(month, draft); rerender(); }
      if (addKeywordBtn) addKeywordBtn.onclick = addDraftKeyword;
      if (keywordInput) { keywordInput.oninput = function() { const draft = financialGoalDraftFor(month); if (!draft) return; draft.keywordDraft = keywordInput.value || ''; setFinancialGoalDraft(month, draft); }; keywordInput.onkeydown = function(e) { if (e.key === 'Enter' || e.key === ',') { e.preventDefault(); addDraftKeyword(); } }; }
      root.querySelectorAll('[data-remove-draft-goal-keyword]').forEach(function(btn) { btn.onclick = function() { const draft = financialGoalDraftFor(month); if (!draft) return; const idx = Number(btn.dataset.removeDraftGoalKeyword || -1); const phrases = goalKeywordPhrases(draft); if (idx >= 0 && idx < phrases.length) phrases.splice(idx, 1); draft.matchWords = phrases.join(', '); setFinancialGoalDraft(month, draft); rerender(); }; });
      const cancelBtn = root.querySelector('[data-cancel-draft-goal]');
      if (cancelBtn) cancelBtn.onclick = function() { setFinancialGoalDraft(month, null); rerender(); };
      const confirmBtn = root.querySelector('[data-confirm-draft-goal]');
      if (confirmBtn) confirmBtn.onclick = function() { const draft = financialGoalDraftFor(month); if (!draft) return; pushHistory(); markDirty(); month.goals = month.goals || []; const confirmed = Object.assign({}, draft, { id:'goal-' + Date.now() + '-' + Math.floor(Math.random()*1000), goalAmount:Number(draft.goalAmount || 0), baseProgress:Number(draft.baseProgress || 0), keywordDraft:'' }); month.goals.push(confirmed); setFinancialGoalDraft(month, null); setGoalTrackerActiveIndex(month, month.goals.length - 1); rerender(); };
    }

    function renderFinancialGoalsTab(monthArg) {
      const month = monthArg || getActiveMonth();
      const wrap = document.getElementById('financialGoalsLayout');
      if (!wrap || !month) return;
      const goalOptions = planningBucketOptions(month);
      wrap.innerHTML = renderFinancialGoalsSummary(month, goalOptions);
      [document.getElementById('openFinancialGoalsWorkspaceBtn')]
        .filter(Boolean)
        .forEach(function(btn) { btn.onclick = openFinancialGoalsWorkspace; });
      [document.getElementById('openFinancialGoalsHistoryBtn')]
        .filter(Boolean)
        .forEach(function(btn) { btn.onclick = openFinancialGoalsHistory; });
      const overlay = document.getElementById('financialGoalsManagerOverlay');
      if (overlay && overlay.classList.contains('cbm-open')) renderFinancialGoalsWorkspace(month);
      const historyOverlay = document.getElementById('financialGoalsHistoryOverlay');
      if (historyOverlay && historyOverlay.classList.contains('cbm-open')) renderFinancialGoalsHistory();
    };

    function renderPlanningTools(month) {
      // Decision Simulator has moved to its own modal — planningGrid is no longer used.
      // If the DS modal is currently open, re-render its content to reflect state changes.
      const dsOverlay = document.getElementById('dsSimulatorOverlay');
      if (dsOverlay && dsOverlay.classList.contains('cbm-open') && typeof openDecisionSimulatorModal === 'function') {
        openDecisionSimulatorModal();
      }
    }

    function rowPoolForKind(month, kind) {
      return kind === "income" ? month.income : kind === "savings" ? month.savings : month.expenses;
    }

    function categoryOrderKeyForKind(kind) {
      return kind === "income" ? "incomeCategoryOrder" : kind === "savings" ? "savingsCategoryOrder" : "expenseCategoryOrder";
    }

    function normalizeStructureRowPool(month, kind) {
      const source = rowPoolForKind(month, kind);
      const pool = Array.isArray(source) ? source.filter(function(row) {
        return row && typeof row === 'object';
      }) : [];
      if (kind === 'income') month.income = pool;
      else if (kind === 'savings') month.savings = pool;
      return pool;
    }

    function monthGroupsByKind(month, kind) {
      const seen = new Set();
      const groups = [];
      const pool = normalizeStructureRowPool(month, kind);
      const activeGroups = new Set();
      pool.forEach(function(row) {
        const clean = cleanGroupName(row && row.group);
        if (row) row.group = clean;
        if (clean) activeGroups.add(clean);
      });
      const order = month[categoryOrderKeyForKind(kind)] || [];
      order.forEach(function(group) {
        const clean = cleanGroupName(group);
        // Never render or preserve orphan simple cashflow groups from legacy/default templates.
        // This prevents empty groups like "Side Projects" from reappearing after importing old caches.
        if ((kind === 'income' || kind === 'savings') && !activeGroups.has(clean)) return;
        if (!clean || seen.has(clean)) return;
        seen.add(clean);
        groups.push(clean);
      });
      pool.forEach(function(row) {
        const clean = cleanGroupName(row && row.group);
        if (!clean || seen.has(clean)) return;
        seen.add(clean);
        groups.push(clean);
      });
      return groups;
    }

    function defaultSavingsClassification(row) {
      const name = String(row && row.name || '').toLowerCase();
      const group = cleanGroupName(row && row.group || '').toLowerCase();
      if (group.includes('investment')) return 'investment';
      if (name.includes('crypto') || name.includes('etf') || name.includes('stock') || name.includes('broker') || name.includes('portfolio')) return 'investment';
      return 'savings';
    }

    function ensureRowStructure(month, kind) {
      if (kind === 'income') ensureSharedExpensesIncomePreset(month);
      const pool = normalizeStructureRowPool(month, kind);
      month[categoryOrderKeyForKind(kind)] = monthGroupsByKind(month, kind);
      pool.forEach(function(row) {
        row.group = cleanGroupName(row && row.group) || 'New Category';
        row.name = String(row && row.name || '').trim() || 'New sub-category';
        row.type = String(row && row.type || 'VARIABLE').toUpperCase();
        row.planned = Number(row && row.planned || 0);
        row.transactions = Array.isArray(row && row.transactions) ? row.transactions : [];
        if (kind === 'savings') {
          const rawClassification = String(row && row.classification || '').toLowerCase();
          row.classification = rawClassification === 'investment' ? 'investment' : rawClassification === 'savings' ? 'savings' : defaultSavingsClassification(row);
        }
      });
    }

    function ensureSavingsCategoryAllocationState(month) {
      if (!month || typeof month !== 'object') return;
      month.savingsCategoryAllocations = month.savingsCategoryAllocations && typeof month.savingsCategoryAllocations === 'object'
        ? Object.assign({}, month.savingsCategoryAllocations)
        : {};
      const validGroups = new Set(monthGroupsByKind(month, 'savings'));
      Object.keys(month.savingsCategoryAllocations).forEach(function(group) {
        const clean = cleanGroupName(group);
        const raw = Number(month.savingsCategoryAllocations[group] || 0);
        if (!clean || !validGroups.has(clean)) {
          delete month.savingsCategoryAllocations[group];
          return;
        }
        if (group !== clean) {
          delete month.savingsCategoryAllocations[group];
        }
        month.savingsCategoryAllocations[clean] = Math.max(0, raw);
      });
      validGroups.forEach(function(group) {
        if (month.savingsCategoryAllocations[group] == null) month.savingsCategoryAllocations[group] = 0;
      });
    }

    function savingsAllocationBudgetTotal(month) {
      if (!month) return 0;
      const allocation = allocationRows(month);
      const row = (allocation.rows || []).find(function(item) { return isSavingsAllocationRow(item); });
      return row ? Number(row.allocation || 0) : 0;
    }

    function savingsAssignedAmountForGroup(month, group, useDraft) {
      if (!month || !group) return 0;
      ensureSavingsCategoryAllocationState(month);
      const source = useDraft && draftSavingsCategoryAllocations ? draftSavingsCategoryAllocations : month.savingsCategoryAllocations;
      return Math.max(0, Number(source && source[cleanGroupName(group)] || 0));
    }

    function savingsDistributionSummary(month, useDraft) {
      ensureRowStructure(month, 'savings');
      ensureSavingsCategoryAllocationState(month);
      const groups = monthGroupsByKind(month, 'savings');
      const totalBudget = savingsAllocationBudgetTotal(month);
      const assignedByGroup = {};
      let assignedTotal = 0;
      groups.forEach(function(group) {
        const amount = savingsAssignedAmountForGroup(month, group, useDraft);
        assignedByGroup[group] = amount;
        assignedTotal += amount;
      });
      return {
        totalBudget: totalBudget,
        assignedTotal: assignedTotal,
        remaining: totalBudget - assignedTotal,
        groups: groups,
        assignedByGroup: assignedByGroup
      };
    }

    function openSavingsBudgetModal() {
      const month = getActiveMonth();
      if (!month) return;
      ensureRowStructure(month, 'savings');
      ensureSavingsCategoryAllocationState(month);
      draftSavingsCategoryAllocations = Object.assign({}, month.savingsCategoryAllocations || {});
      isSavingsBudgetModalOpen = true;
      render('rows');
      syncSavingsBudgetModal();
    }

    function closeSavingsBudgetModal(shouldSave) {
      const month = getActiveMonth();
      if (shouldSave && month) {
        ensureSavingsCategoryAllocationState(month);
        const nextMap = {};
        monthGroupsByKind(month, 'savings').forEach(function(group) {
          nextMap[group] = Math.max(0, Number(draftSavingsCategoryAllocations && draftSavingsCategoryAllocations[group] || 0));
        });
        pushHistory();
        markDirty();
        month.savingsCategoryAllocations = nextMap;
      }
      draftSavingsCategoryAllocations = null;
      isSavingsBudgetModalOpen = false;
      syncSavingsBudgetModal();
      render('rows');
    }

    function updateDraftSavingsBudgetAllocation(group, value) {
      if (!draftSavingsCategoryAllocations) draftSavingsCategoryAllocations = {};
      draftSavingsCategoryAllocations[cleanGroupName(group)] = Math.max(0, Number(value || 0));
    }

    function renderSavingsBudgetModalContent(month) {
      if (!isSavingsBudgetModalOpen || !month) return '';
      const summary = savingsDistributionSummary(month, true);
      const remainingTone = summary.remaining < -0.009 ? 'bad' : summary.remaining > 0.009 ? 'warn' : 'good';
      const remainingLabel = summary.remaining < -0.009
        ? currency(Math.abs(summary.remaining)) + ' over-assigned'
        : summary.remaining > 0.009
          ? currency(summary.remaining) + ' left to assign'
          : 'Fully assigned';
      return `
<div class="planner-grid" style="grid-template-columns:repeat(3,minmax(0,1fr)); gap:8px; margin-top:8px;">
          <div class="planner-card ui-3d-panel ui-3d-planning savings-budget-summary-card savings-budget-available"><div class="muted savings-budget-summary-label">Available</div><div id="sbd-available" class="savings-budget-summary-value" style="font-weight:800; margin-top:4px;">${currency(summary.totalBudget)}</div></div>
          <div class="planner-card ui-3d-panel ui-3d-planning savings-budget-summary-card savings-budget-assigned"><div class="muted savings-budget-summary-label">Assigned</div><div id="sbd-assigned" class="savings-budget-summary-value" style="font-weight:800; margin-top:4px;">${currency(summary.assignedTotal)}</div></div>
          <div class="planner-card ui-3d-panel ui-3d-planning savings-budget-summary-card savings-budget-remaining"><div class="muted savings-budget-summary-label">Remaining</div><div id="sbd-remaining" class="savings-budget-summary-value" style="font-weight:800; margin-top:4px; color:${remainingTone === 'bad' ? '#fca5a5' : (remainingTone === 'warn' ? '#fcd34d' : '#86efac')};">${remainingLabel}</div></div>
        </div>
        <div class="manage-list" style="margin-top:12px;">
          ${summary.groups.map(function(group) {
            const safeGroup = escapeHtml(group);
            const amount = Number(summary.assignedByGroup[group] || 0);
            const pct = summary.totalBudget > 0 ? Math.max(0, Math.min((amount / Math.max(summary.totalBudget, 1)) * 100, 100)) : 0;
            return `
              <div class="manage-item" style="display:grid; gap:8px;">
                <div style="display:flex; align-items:flex-start; justify-content:space-between; gap:12px;">
                  <div>
                    <div class="manage-item-name">${safeGroup}</div>
                    <div class="manage-item-meta" data-savings-budget-meta="${safeGroup}">${currency(amount)} assigned · ${summary.totalBudget > 0 ? pct.toFixed(0) + '% of total' : 'No budget yet'}</div>
                  </div>
                  <div style="display:flex; align-items:center; gap:6px;">
                    <button type="button" class="ghost-btn" style="white-space:nowrap; font-size:0.7rem; padding:3px 7px;" data-savings-budget-add-remaining="${safeGroup}">+ Add remaining</button>
                    <div style="width:120px;">
                      <input type="number" min="0" step="0.01" class="target-input" style="width:100%;" data-savings-budget-input="${safeGroup}" value="${Number(amount || 0).toFixed(2)}">
                    </div>
                  </div>
                </div>
              </div>`;
          }).join('')}
        </div>
        <div style="display:flex; justify-content:flex-end; gap:8px; margin-top:12px;">
          <button class="ghost-btn" type="button" data-close-savings-budget-modal>Cancel</button>
          <button class="tiny-btn" type="button" data-save-savings-budget-modal>Save &amp; Close</button>
        </div>`;
    }

    function savingsBudgetSelectorValue(value) {
      return String(value || '').replace(/\\/g, '\\\\').replace(/"/g, '\\"');
    }

    function refreshSavingsBudgetSummaryTiles(root) {
      const month = getActiveMonth();
      if (!month || !root) return;
      const summary = savingsDistributionSummary(month, true);
      const remainingTone = summary.remaining < -0.009 ? 'bad' : summary.remaining > 0.009 ? 'warn' : 'good';
      const remainingLabel = summary.remaining < -0.009
        ? currency(Math.abs(summary.remaining)) + ' over-assigned'
        : summary.remaining > 0.009
          ? currency(summary.remaining) + ' left to assign'
          : 'Fully assigned';
      const availEl = root.querySelector('#sbd-available');
      const assignEl = root.querySelector('#sbd-assigned');
      const remEl = root.querySelector('#sbd-remaining');
      if (availEl) availEl.textContent = currency(summary.totalBudget);
      if (assignEl) assignEl.textContent = currency(summary.assignedTotal);
      if (remEl) {
        remEl.textContent = remainingLabel;
        remEl.style.color = remainingTone === 'bad' ? '#fca5a5' : (remainingTone === 'warn' ? '#fcd34d' : '#86efac');
      }
      summary.groups.forEach(function(group) {
        const metaEl = root.querySelector('[data-savings-budget-meta="' + savingsBudgetSelectorValue(group) + '"]');
        if (!metaEl) return;
        const amount = Number(summary.assignedByGroup[group] || 0);
        const pct = summary.totalBudget > 0 ? Math.max(0, Math.min((amount / Math.max(summary.totalBudget, 1)) * 100, 100)) : 0;
        metaEl.textContent = currency(amount) + ' assigned · ' + (summary.totalBudget > 0 ? pct.toFixed(0) + '% of total' : 'No budget yet');
      });
    }

    function bindSavingsBudgetModalControls(root) {
      if (!root) return;
      root.querySelectorAll('[data-close-savings-budget-modal]').forEach(function(btn) {
        btn.onclick = function() { closeSavingsBudgetModal(false); };
      });
      root.querySelectorAll('[data-save-savings-budget-modal]').forEach(function(btn) {
        btn.onclick = function() { closeSavingsBudgetModal(true); };
      });
      root.querySelectorAll('[data-savings-budget-input]').forEach(function(input) {
        input.oninput = function() {
          updateDraftSavingsBudgetAllocation(input.dataset.savingsBudgetInput, input.value);
          refreshSavingsBudgetSummaryTiles(root);
        };
        input.onkeydown = function(event) {
          if (event.key === 'Enter') {
            event.preventDefault();
            updateDraftSavingsBudgetAllocation(input.dataset.savingsBudgetInput, input.value);
            refreshSavingsBudgetSummaryTiles(root);
            input.blur();
          }
        };
      });
      root.querySelectorAll('[data-savings-budget-add-remaining]').forEach(function(btn) {
        btn.onclick = function() {
          const group = btn.dataset.savingsBudgetAddRemaining;
          const month = getActiveMonth();
          if (!month) return;
          const summary = savingsDistributionSummary(month, true);
          const remaining = summary.remaining;
          if (remaining <= 0.009) return;
          const currentAmount = Number(draftSavingsCategoryAllocations && draftSavingsCategoryAllocations[cleanGroupName(group)] || 0);
          const newAmount = Math.max(0, currentAmount + remaining);
          updateDraftSavingsBudgetAllocation(group, newAmount);
          const input = root.querySelector('[data-savings-budget-input="' + savingsBudgetSelectorValue(group) + '"]');
          if (input) input.value = newAmount.toFixed(2);
          refreshSavingsBudgetSummaryTiles(root);
        };
      });
    }

    function syncSavingsBudgetModal() {
      const modal = document.getElementById('savingsBudgetModal');
      const content = document.getElementById('savingsBudgetModalContent');
      if (!modal || !content) return;
      if (!isSavingsBudgetModalOpen) {
        modal.hidden = true;
        content.innerHTML = '';
        return;
      }
      const month = getActiveMonth();
      modal.hidden = false;
      content.innerHTML = renderSavingsBudgetModalContent(month);
      bindSavingsBudgetModalControls(modal);
    }

    const activeStructureGroupByKind = {
      income: null,
      savings: null,
      expense: null
    };

    const pendingStructureOrderByKind = {
      income: null,
      savings: null,
      expense: null
    };


    const structureDraftByKind = {
      income: null,
      savings: null,
      expense: null
    };


    const structureCategoryIconDraftByKind = {
      income: null,
      savings: null,
      expense: null
    };

    function cloneStructureMonth(month) {
      return JSON.parse(JSON.stringify(month || {}));
    }

    function getStructureEditingMonth(kind) {
      const config = structureKindConfig(kind);
      return structureDraftByKind[config.kind] || getActiveMonth();
    }

    function commitStructureDraft(kind) {
      const config = structureKindConfig(kind);
      const draft = structureDraftByKind[config.kind];
      if (!draft) return false;
      const month = getActiveMonth();
      const before = JSON.stringify({
        rows: config.rows(month) || [],
        order: config.kind === 'expense' ? (month.expenseCategoryOrder || []) : (month[categoryOrderKeyForKind(config.kind)] || []),
        splitwiseCategories: config.kind === 'expense' ? Object.assign({}, ensureSplitwiseCategorySettings(month)) : {},
        icons: Object.keys(categoryIconMapForState(state)).filter(function(key) {
          return key.indexOf(config.kind + '|') === 0;
        }).sort().reduce(function(map, key) {
          const iconKey = sanitizeCategoryIconKey(state.categoryIcons[key]);
          if (iconKey) map[key] = iconKey;
          return map;
        }, {})
      });
      const after = JSON.stringify({
        rows: config.rows(draft) || [],
        order: config.kind === 'expense' ? (draft.expenseCategoryOrder || []) : (draft[categoryOrderKeyForKind(config.kind)] || []),
        splitwiseCategories: config.kind === 'expense' ? Object.assign({}, ensureSplitwiseCategorySettings(draft)) : {},
        icons: Object.assign({}, categoryIconDraftMap(config.kind))
      });
      if (before === after) {
        structureDraftByKind[config.kind] = null;
        structureCategoryIconDraftByKind[config.kind] = null;
        clearPendingStructureOrder(config.kind);
        return false;
      }
      pushHistory();
      markDirty();
      if (config.kind === 'expense') {
        month.expenses = JSON.parse(JSON.stringify(draft.expenses || []));
        month.expenseCategoryOrder = JSON.parse(JSON.stringify(draft.expenseCategoryOrder || []));
        month.allocationTargets = JSON.parse(JSON.stringify(draft.allocationTargets || month.allocationTargets || {}));
        month.splitwise = JSON.parse(JSON.stringify(draft.splitwise || month.splitwise || {}));
        month.splitwiseCategories = JSON.parse(JSON.stringify(draft.splitwiseCategories || {}));
        ensureSplitwiseCategorySettings(month);
        ensureCategoryMeta(state);
        Object.keys(state.categoryIcons || {}).forEach(function(key) {
          if (key.indexOf('expense|') === 0) delete state.categoryIcons[key];
        });
        Object.assign(state.categoryIcons, categoryIconDraftMap('expense'));
      } else if (config.kind === 'income') {
        month.income = JSON.parse(JSON.stringify(draft.income || []));
        month.incomeCategoryOrder = JSON.parse(JSON.stringify(draft.incomeCategoryOrder || []));
        ensureCategoryMeta(state);
        Object.keys(state.categoryIcons || {}).forEach(function(key) {
          if (key.indexOf('income|') === 0) delete state.categoryIcons[key];
        });
        Object.assign(state.categoryIcons, categoryIconDraftMap('income'));
      } else {
        month.savings = JSON.parse(JSON.stringify(draft.savings || []));
        month.savingsCategoryOrder = JSON.parse(JSON.stringify(draft.savingsCategoryOrder || []));
        ensureCategoryMeta(state);
        Object.keys(state.categoryIcons || {}).forEach(function(key) {
          if (key.indexOf('savings|') === 0) delete state.categoryIcons[key];
        });
        Object.assign(state.categoryIcons, categoryIconDraftMap('savings'));
      }
      structureDraftByKind[config.kind] = null;
      structureCategoryIconDraftByKind[config.kind] = null;
      clearPendingStructureOrder(config.kind);
      return true;
    }

    function structureKindConfig(kind) {
      const canonicalKind = kind === 'expense' ? 'expense' : kind;
      const prefix = canonicalKind === 'expense' ? 'expense' : canonicalKind;
      return {
        kind: canonicalKind,
        prefix: prefix,
        modalId: prefix + 'StructureModal',
        categoryListId: prefix + 'CategoryList',
        subcategoryListId: prefix + 'SubcategoryList',
        subcategoryTitleId: prefix + 'SubcategoryTitle',
        ensureMonthStructure: function(month) {
          if (canonicalKind === 'expense') ensureExpenseStructure(month);
          else ensureRowStructure(month, canonicalKind);
        },
        groups: function(month) {
          return canonicalKind === 'expense' ? monthExpenseGroups(month) : monthGroupsByKind(month, canonicalKind);
        },
        rows: function(month) {
          return canonicalKind === 'expense' ? (month.expenses || []) : rowPoolForKind(month, canonicalKind);
        },
        setRows: function(month, rows) {
          if (canonicalKind === 'expense') month.expenses = rows;
          else if (canonicalKind === 'income') month.income = rows;
          else month.savings = rows;
        },
        isKnownGroup: function(groupName) {
          return canonicalKind === 'expense' ? isKnownExpenseCategory(groupName) : simpleStructureHasKnownGroup(canonicalKind, groupName);
        }
      };
    }

    function setActiveStructureGroup(kind, groupName) {
      const config = structureKindConfig(kind);
      activeStructureGroupByKind[config.kind] = cleanGroupName(groupName) || null;
    }

    function selectedStructureGroup(month, kind) {
      const config = structureKindConfig(kind);
      config.ensureMonthStructure(month);
      const groups = structureGroupsForModal(month, config.kind);
      if (!groups.length) return null;
      const activeGroup = activeStructureGroupByKind[config.kind];
      if (!activeGroup || groups.indexOf(activeGroup) === -1) {
        activeStructureGroupByKind[config.kind] = groups[0];
      }
      return activeStructureGroupByKind[config.kind];
    }

    function selectedSimpleStructureGroup(month, kind) {
      return selectedStructureGroup(month, kind);
    }

    function selectedExpenseStructureGroup(month) {
      return selectedStructureGroup(month, 'expense');
    }

    function knownExpenseStructureGroups() {
      const starter = buildNeutralStarterMonth();
      const groups = starter && Array.isArray(starter.expenseCategoryOrder) ? starter.expenseCategoryOrder : [];
      return groups.map(cleanGroupName).filter(Boolean);
    }

    function isKnownExpenseCategory(groupName) {
      const target = cleanGroupName(groupName);
      if (!target) return false;
      return knownExpenseStructureGroups().indexOf(target) !== -1;
    }

    function knownSimpleStructureGroups(kind) {
      const starter = buildNeutralStarterMonth();
      const groups = kind === 'income'
        ? (starter.incomeCategoryOrder || [])
        : (starter.savingsCategoryOrder || []);
      return groups.map(cleanGroupName).filter(Boolean);
    }

    function simpleStructureHasKnownGroup(kind, groupName) {
      const target = cleanGroupName(groupName);
      if (!target) return false;
      return knownSimpleStructureGroups(kind).indexOf(target) !== -1;
    }

    function reorderStructureGroups(groupList, groupName, direction) {
      const groups = Array.isArray(groupList) ? groupList.slice() : [];
      const cleanName = cleanGroupName(groupName);
      const currentIndex = groups.findIndex(function(group) { return cleanGroupName(group) === cleanName; });
      if (currentIndex === -1) return groups;
      const nextIndex = direction === 'up' ? currentIndex - 1 : currentIndex + 1;
      if (nextIndex < 0 || nextIndex >= groups.length) return groups;
      const temp = groups[currentIndex];
      groups[currentIndex] = groups[nextIndex];
      groups[nextIndex] = temp;
      return groups;
    }

    function moveSimpleGroupInMonth(month, kind, groupName, direction) {
      ensureRowStructure(month, kind);
      const reordered = reorderStructureGroups(monthGroupsByKind(month, kind), groupName, direction);
      month[categoryOrderKeyForKind(kind)] = reordered;
      setActiveStructureGroup(kind, cleanGroupName(groupName));
      ensureRowStructure(month, kind);
    }


    function getPendingStructureOrder(kind) {
      const config = structureKindConfig(kind);
      const pending = pendingStructureOrderByKind[config.kind];
      return Array.isArray(pending) ? pending.slice() : null;
    }

    function setPendingStructureOrder(kind, order) {
      const config = structureKindConfig(kind);
      pendingStructureOrderByKind[config.kind] = Array.isArray(order) ? order.slice() : null;
    }

    function clearPendingStructureOrder(kind) {
      const config = structureKindConfig(kind);
      pendingStructureOrderByKind[config.kind] = null;
    }

    function structureGroupsForModal(month, kind) {
      const config = structureKindConfig(kind);
      const liveGroups = config.groups(month).map(cleanGroupName).filter(Boolean);
      const pending = getPendingStructureOrder(config.kind);
      if (!pending || !pending.length) return liveGroups;
      const liveSet = new Set(liveGroups);
      const seen = new Set();
      const merged = [];
      pending.forEach(function(group) {
        const clean = cleanGroupName(group);
        if (!clean || !liveSet.has(clean) || seen.has(clean)) return;
        seen.add(clean);
        merged.push(clean);
      });
      liveGroups.forEach(function(group) {
        const clean = cleanGroupName(group);
        if (!clean || seen.has(clean)) return;
        seen.add(clean);
        merged.push(clean);
      });
      return merged;
    }

    function applyPendingStructureOrder(month, kind) {
      const config = structureKindConfig(kind);
      const pending = getPendingStructureOrder(config.kind);
      if (!pending || !pending.length) {
        clearPendingStructureOrder(config.kind);
        return false;
      }
      const liveGroups = config.groups(month);
      const liveSet = new Set(liveGroups.map(function(group) { return cleanGroupName(group); }).filter(Boolean));
      const ordered = [];
      pending.forEach(function(group) {
        const clean = cleanGroupName(group);
        if (!clean || !liveSet.has(clean) || ordered.indexOf(clean) !== -1) return;
        ordered.push(clean);
      });
      liveGroups.forEach(function(group) {
        const clean = cleanGroupName(group);
        if (!clean || ordered.indexOf(clean) !== -1) return;
        ordered.push(clean);
      });
      if (config.kind === 'expense') month.expenseCategoryOrder = ordered;
      else month[categoryOrderKeyForKind(config.kind)] = ordered;
      clearPendingStructureOrder(config.kind);
      return true;
    }

    function nextRowId(prefix) {
      return prefix + '-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7);
    }

    function expenseStructureHasGroup(month, groupName, excludeName) {
      const target = cleanGroupName(groupName);
      const exclude = cleanGroupName(excludeName);
      return monthExpenseGroups(month).some(function(group) {
        const clean = cleanGroupName(group);
        return clean && clean !== exclude && clean.toLowerCase() === target.toLowerCase();
      });
    }

    function migrateExpenseAllocationTarget(month, oldName, nextName) {
      const oldKey = allocationKeyForGroup(oldName);
      const nextKey = allocationKeyForGroup(nextName);
      if (month.allocationTargets && month.allocationTargets[oldKey] != null && month.allocationTargets[nextKey] == null) {
        month.allocationTargets[nextKey] = month.allocationTargets[oldKey];
      }
      if (month.allocationTargets) delete month.allocationTargets[oldKey];
      if (month.splitwise && month.splitwise[oldKey] != null && month.splitwise[nextKey] == null) {
        month.splitwise[nextKey] = month.splitwise[oldKey];
      }
      if (month.splitwise) delete month.splitwise[oldKey];
      if (month.splitwiseCategories && month.splitwiseCategories[oldKey] != null && month.splitwiseCategories[nextKey] == null) {
        month.splitwiseCategories[nextKey] = !!month.splitwiseCategories[oldKey];
      }
      if (month.splitwiseCategories) delete month.splitwiseCategories[oldKey];
    }

    function updateSubscriptionsForExpenseCategoryRename(oldName, nextName) {
    }

    function clearSubscriptionsForExpenseCategory(categoryName) {
    }

    function renameExpenseGroupInMonth(month, oldName, nextName) {
      month.expenses.forEach(function(row) {
        if (cleanGroupName(row.group) === cleanGroupName(oldName)) row.group = cleanGroupName(nextName);
      });
      month.expenseCategoryOrder = monthExpenseGroups(month).map(function(group) {
        return cleanGroupName(group) === cleanGroupName(oldName) ? cleanGroupName(nextName) : cleanGroupName(group);
      });
      migrateExpenseAllocationTarget(month, oldName, nextName);
      updateSubscriptionsForExpenseCategoryRename(oldName, nextName);
      renameCategoryIcon('expense', oldName, nextName, structureCategoryIconDraftByKind.expense);
      setActiveStructureGroup('expense', nextName);
      ensureExpenseStructure(month);
    }

    function removeExpenseGroupInMonth(month, groupName) {
      month.expenses = (month.expenses || []).filter(function(row) {
        return cleanGroupName(row.group) !== cleanGroupName(groupName);
      });
      month.expenseCategoryOrder = monthExpenseGroups(month).filter(function(name) {
        return cleanGroupName(name) !== cleanGroupName(groupName);
      });
      const groupKey = allocationKeyForGroup(groupName);
      delete month.allocationTargets[groupKey];
      delete month.splitwise[groupKey];
      if (month.splitwiseCategories) delete month.splitwiseCategories[groupKey];
      clearSubscriptionsForExpenseCategory(groupName);
      removeCategoryIcon('expense', groupName, structureCategoryIconDraftByKind.expense);
      setActiveStructureGroup('expense', monthExpenseGroups(month)[0] || null);
      ensureExpenseStructure(month);
    }

    function moveExpenseGroupInMonth(month, groupName, direction) {
      const groups = monthExpenseGroups(month);
      const cleanName = cleanGroupName(groupName);
      const currentIndex = groups.findIndex(function(group) { return cleanGroupName(group) === cleanName; });
      if (currentIndex === -1) return;
      const nextIndex = direction === 'up' ? currentIndex - 1 : currentIndex + 1;
      if (nextIndex < 0 || nextIndex >= groups.length) return;
      const reordered = groups.slice();
      const temp = reordered[currentIndex];
      reordered[currentIndex] = reordered[nextIndex];
      reordered[nextIndex] = temp;
      month.expenseCategoryOrder = reordered;
      setActiveStructureGroup('expense', cleanName);
      ensureExpenseStructure(month);
    }

    function renameSimpleGroupInMonth(month, kind, oldName, nextName) {
      rowPoolForKind(month, kind).forEach(function(row) {
        if (cleanGroupName(row.group) === cleanGroupName(oldName)) row.group = cleanGroupName(nextName);
      });
      month[categoryOrderKeyForKind(kind)] = monthGroupsByKind(month, kind).map(function(group) {
        return cleanGroupName(group) === cleanGroupName(oldName) ? cleanGroupName(nextName) : cleanGroupName(group);
      });
      renameCategoryIcon(kind, oldName, nextName, structureCategoryIconDraftByKind[kind]);
      setActiveStructureGroup(kind, nextName);
      ensureRowStructure(month, kind);
    }

    function removeSimpleGroupInMonth(month, kind, groupName) {
      month[categoryOrderKeyForKind(kind)] = monthGroupsByKind(month, kind).filter(function(name) {
        return cleanGroupName(name) !== cleanGroupName(groupName);
      });
      const filtered = rowPoolForKind(month, kind).filter(function(row) {
        return cleanGroupName(row.group) !== cleanGroupName(groupName);
      });
      if (kind === 'income') month.income = filtered;
      else month.savings = filtered;
      removeCategoryIcon(kind, groupName, structureCategoryIconDraftByKind[kind]);
      setActiveStructureGroup(kind, monthGroupsByKind(month, kind)[0] || null);
      ensureRowStructure(month, kind);
    }

    function moveStructureGroupInMonth(month, kind, groupName, direction) {
      if (kind === 'expense') moveExpenseGroupInMonth(month, groupName, direction);
      else moveSimpleGroupInMonth(month, kind, groupName, direction);
    }

    function renameStructureGroupInMonth(month, kind, oldName, nextName) {
      if (kind === 'expense') renameExpenseGroupInMonth(month, oldName, nextName);
      else renameSimpleGroupInMonth(month, kind, oldName, nextName);
    }

    function removeStructureGroupInMonth(month, kind, groupName) {
      if (kind === 'expense') removeExpenseGroupInMonth(month, groupName);
      else removeSimpleGroupInMonth(month, kind, groupName);
    }

    function structureHasGroup(month, kind, groupName, excludeName) {
      if (kind === 'expense') return expenseStructureHasGroup(month, groupName, excludeName);
      const target = cleanGroupName(groupName);
      const exclude = cleanGroupName(excludeName);
      return monthGroupsByKind(month, kind).some(function(group) {
        const clean = cleanGroupName(group);
        return clean && clean !== exclude && clean.toLowerCase() === target.toLowerCase();
      });
    }

    function structureRemoveGroupConfirmMessage(kind, groupName) {
      if (kind !== 'expense') return 'Remove "' + groupName + '" and all of its sub-categories from this tracker month?';
      const linkedSubscriptions = ensureSubscriptionsState(state).filter(function(subscription) {
        return cleanGroupName(subscription && subscription.categoryKey) === cleanGroupName(groupName);
      }).length;
      return linkedSubscriptions > 0
        ? 'Remove "' + groupName + '" and all of its sub-categories from this tracker month? Linked subscriptions will be unassigned.'
        : 'Remove "' + groupName + '" and all of its sub-categories from this tracker month?';
    }

    function structureCategoryControlMarkup(kind, group, groupIndex, groups) {
      const prefix = kind === 'expense' ? 'expense' : kind;
      const isProtectedSharedExpensesGroup = isSharedExpensesIncomeGroup(kind, group);
      const canMoveUp = groupIndex > 0;
      const canMoveDown = groupIndex < groups.length - 1;
      const safeGroup = escapeHtml(cleanGroupName(group));
      let markup = '';
      if (kind === 'expense') {
        const pickerColor = getCategoryColor('expense', cleanGroupName(group));
        markup += '<input class="category-color-input" type="color" value="' + pickerColor + '" title="Choose category color" data-category-color-kind="expense" data-category-color-group="' + safeGroup + '" />';
        markup += '<button class="manage-icon-btn category-color-reset" type="button" title="Reset category color" data-clear-category-color-kind="expense" data-clear-category-color-group="' + safeGroup + '">↺</button>';
      }
      markup += '<button class="manage-icon-btn" type="button" title="Move category up" data-move-' + prefix + '-group="' + safeGroup + '" data-move-direction="up" ' + (canMoveUp ? '' : 'disabled') + '>↑</button>';
      markup += '<button class="manage-icon-btn" type="button" title="Move category down" data-move-' + prefix + '-group="' + safeGroup + '" data-move-direction="down" ' + (canMoveDown ? '' : 'disabled') + '>↓</button>';
      markup += isProtectedSharedExpensesGroup
        ? '<button class="manage-icon-btn danger" type="button" title="Shared Expenses is required for settlements" disabled>×</button>'
        : '<button class="manage-icon-btn danger" type="button" title="Remove category" data-remove-' + prefix + '-group="' + safeGroup + '">×</button>';
      return markup;
    }

    function structureSubcategoryRowMarkup(kind, prefix, row) {
      const safeName = escapeHtml(String(row.name || ''));
      if (kind === 'expense') {
        return `
          <div class="manage-item">
            <div class="manage-item-main manage-inline three">
              <input type="text" value="${safeName}" data-expense-row-name="${row.id}" />
              <select data-expense-row-type="${row.id}">
                <option value="VARIABLE" ${row.fixed ? '' : 'selected'}>Variable</option>
                <option value="FIXED" ${row.fixed ? 'selected' : ''}>Fixed</option>
              </select>
              <input type="number" step="0.01" value="${Number(row.planned || 0).toFixed(2)}" data-expense-row-planned="${row.id}" ${row.fixed ? '' : 'disabled'} />
            </div>
            <button class="manage-icon-btn danger" type="button" title="Remove sub-category" data-remove-expense-row="${row.id}">×</button>
          </div>`;
      }
      if (kind === 'savings') {
        const classification = row.classification === 'investment' ? 'investment' : 'savings';
        return `
          <div class="manage-item">
            <div class="manage-item-main manage-inline two">
              <input type="text" value="${safeName}" data-${prefix}-row-name="${row.id}" />
              <select data-${prefix}-row-classification="${row.id}">
                <option value="savings" ${classification === 'savings' ? 'selected' : ''}>Savings</option>
                <option value="investment" ${classification === 'investment' ? 'selected' : ''}>Investment</option>
              </select>
            </div>
            <button class="manage-icon-btn danger" type="button" title="Remove sub-category" data-remove-${prefix}-row="${row.id}">×</button>
          </div>`;
      }
      const isProtectedSharedExpensesRow = kind === 'income' && isSharedExpensesIncomeRow(row);
      return `
        <div class="manage-item ${isProtectedSharedExpensesRow ? 'is-protected-preset' : ''}">
          <div class="manage-item-main">
            <input type="text" value="${safeName}" data-${prefix}-row-name="${row.id}" ${isProtectedSharedExpensesRow ? 'disabled title="Shared Expenses Balance is required for settlements"' : ''} />
          </div>
          ${isProtectedSharedExpensesRow
            ? '<button class="manage-icon-btn danger" type="button" title="Shared Expenses Balance is required for settlements" disabled>×</button>'
            : `<button class="manage-icon-btn danger" type="button" title="Remove sub-category" data-remove-${prefix}-row="${row.id}">×</button>`}
        </div>`;
    }

    function bindStructureCategoryExtras(kind, categoryList) {
      // Color (expense only)
      categoryList.querySelectorAll('[data-category-color-group]').forEach(function(input) {
        input.onchange = function() {
          const group = cleanGroupName(input.dataset.categoryColorGroup);
          const colorKind = input.dataset.categoryColorKind || 'expense';
          setCategoryColor(colorKind, group, input.value);
          renderStructureModal(kind);
        };
      });
      categoryList.querySelectorAll('[data-clear-category-color-group]').forEach(function(btn) {
        btn.onclick = function() {
          const group = cleanGroupName(btn.dataset.clearCategoryColorGroup);
          const colorKind = btn.dataset.clearCategoryColorKind || 'expense';
          clearCategoryColor(colorKind, group);
          renderStructureModal(kind);
        };
      });      categoryList.querySelectorAll('[data-category-icon-select-group]').forEach(function(select) {
        select.onchange = function(event) {
          event.stopPropagation();
          const iconKind = select.dataset.categoryIconSelectKind;
          const group = cleanGroupName(select.dataset.categoryIconSelectGroup);
          if (!iconKind || !group) return;
          const iconKey = sanitizeCategoryIconKey(select.value);
          const draftIcons = categoryIconDraftMap(iconKind);
          if (iconKey) {
            draftIcons[categoryMetaKey(iconKind, group)] = iconKey;
            recordCategoryIconRecent(iconKey);
          } else {
            delete draftIcons[categoryMetaKey(iconKind, group)];
          }
          renderStructureModal(kind);
        };
      });
      if (kind === 'expense') {
        categoryList.querySelectorAll('[data-expense-splitwise-enabled]').forEach(function(input) {
          input.onchange = function(event) {
            event.stopPropagation();
            const month = getStructureEditingMonth('expense');
            const group = cleanGroupName(input.dataset.expenseSplitwiseEnabled);
            if (!month || !group) return;
            setSplitwiseEnabledForGroup(month, group, input.checked);
            renderStructureModal('expense');
          };
        });
      }
    }

    function bindStructureSubcategoryExtras(kind, month, subcategoryList) {
      if (kind === 'expense') {
        subcategoryList.querySelectorAll('[data-expense-row-type]').forEach(function(select) {
          select.onchange = function() {
            const row = (month.expenses || []).find(function(item) { return item.id === select.dataset.expenseRowType; });
            if (!row) return;
            row.fixed = select.value === 'FIXED';
            row.type = row.fixed ? 'FIXED' : 'VARIABLE';
            if (!row.fixed) row.planned = 0;
            ensureExpenseStructure(month);
            renderStructureModal(kind);
          };
        });
        subcategoryList.querySelectorAll('[data-expense-row-planned]').forEach(function(input) {
          input.onchange = function() {
            const row = (month.expenses || []).find(function(item) { return item.id === input.dataset.expenseRowPlanned; });
            if (!row || !row.fixed) return;
            row.planned = Math.max(0, Number(input.value || 0));
            ensureExpenseStructure(month);
            renderStructureModal(kind);
          };
        });
      }
      if (kind === 'savings') {
        subcategoryList.querySelectorAll('[data-savings-row-classification]').forEach(function(select) {
          select.onchange = function() {
            const row = rowPoolForKind(month, 'savings').find(function(item) { return item.id === select.dataset.savingsRowClassification; });
            if (!row) return;
            row.classification = select.value === 'investment' ? 'investment' : 'savings';
            renderStructureModal(kind);
          };
        });
      }
    }

    function toUiTitleCase(value) {
      return String(value || '')
        .trim()
        .replace(/[_-]+/g, ' ')
        .replace(/\s+/g, ' ')
        .split(' ')
        .filter(Boolean)
        .map(function(word) {
          return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();
        })
        .join(' ');
    }

    function standardizeModalUi() {
      document.querySelectorAll('.chart-modal .chart-modal-head h3, .dictionary-modal .dictionary-head h3').forEach(function(title) {
        const nextTitle = toUiTitleCase(title.textContent);
        if (nextTitle) title.textContent = nextTitle;
      });
      document.querySelectorAll('.chart-modal .chart-modal-head .tiny-btn, .dictionary-modal .dictionary-head .ghost-btn').forEach(function(button) {
        const label = String(button.textContent || '').trim().toLowerCase();
        if (label === 'save & close' || label === 'close') button.textContent = toUiTitleCase(label);
      });
    }

    function renderStructureModal(kind) {
      const config = structureKindConfig(kind);
      const modal = document.getElementById(config.modalId);
      if (!modal || modal.hidden) return;
      const month = getStructureEditingMonth(config.kind);
      config.ensureMonthStructure(month);
      const selectedGroup = selectedStructureGroup(month, config.kind);
      const categoryList = document.getElementById(config.categoryListId);
      const subcategoryList = document.getElementById(config.subcategoryListId);
      const subcategoryTitle = document.getElementById(config.subcategoryTitleId);
      const groups = structureGroupsForModal(month, config.kind);
      const prefix = config.prefix;
      const structureRows = (config.rows(month) || []).filter(function(row) {
        return row && typeof row === 'object';
      });

      categoryList.innerHTML = groups.length ? groups.map(function(group, groupIndex) {
        const cleanGroup = cleanGroupName(group);
        const safeGroup = escapeHtml(cleanGroup);
        const rowCount = structureRows.filter(function(row) { return cleanGroupName(row && row.group) === cleanGroup; }).length;
        const isKnown = config.isKnownGroup(cleanGroup);
        const metaLabel = rowCount + ' sub-category' + (rowCount === 1 ? '' : 'ies') + (isKnown ? '' : ' · custom');
        const iconDraft = categoryIconDraftMap(config.kind);
        const splitwiseEnabled = config.kind === 'expense' && splitwiseEnabledForGroup(month, cleanGroup);
        const splitwiseSetting = config.kind === 'expense'
          ? `<div class="manage-splitwise-setting" title="Allow shared expense entries for this category">
              <span class="manage-splitwise-title">Shared Expenses</span>
              <label class="manage-splitwise-toggle">
                <input type="checkbox" data-expense-splitwise-enabled="${safeGroup}" ${splitwiseEnabled ? 'checked' : ''} />
                <span>${splitwiseEnabled ? 'On' : 'Off'}</span>
              </label>
            </div>`
          : '';
        return `
          <div class="manage-item is-selectable manage-structure-category-row ${cleanGroup === selectedGroup ? 'active' : ''} ${isKnown ? '' : 'is-custom-category'}" data-${prefix}-group-item="${safeGroup}">
            <div class="manage-structure-category-main">
              <div class="manage-structure-category-header">
                ${renderManageCategoryIconSelect(config.kind, cleanGroup, iconDraft)}
                <div class="manage-structure-category-copy">
                  <input type="text" value="${safeGroup}" data-${prefix}-group-name="${safeGroup}" ${isSharedExpensesIncomeGroup(config.kind, cleanGroup) ? 'disabled title="Shared Expenses is required for settlements"' : ''} />
                  <div class="manage-item-meta">${isSharedExpensesIncomeGroup(config.kind, cleanGroup) ? 'Preset category · required for settlements' : metaLabel}</div>
                </div>
              </div>
              ${splitwiseSetting}
            </div>
            <div class="manage-item-controls manage-category-action-row">
              ${structureCategoryControlMarkup(config.kind, cleanGroup, groupIndex, groups)}
            </div>
          </div>`;
      }).join('') : '<div class="manage-empty">No categories yet. Add one to start building the structure.</div>';

      subcategoryTitle.textContent = selectedGroup ? ('Sub-categories · ' + selectedGroup) : 'Sub-categories';
      const rows = selectedGroup ? structureRows.filter(function(row) { return cleanGroupName(row && row.group) === selectedGroup; }) : [];
      subcategoryList.innerHTML = rows.length ? rows.map(function(row) {
        return structureSubcategoryRowMarkup(config.kind, prefix, row);
      }).join('') : '<div class="manage-empty">This category has no sub-categories yet.</div>';

      categoryList.querySelectorAll('[data-' + prefix + '-group-item]').forEach(function(card) {
        card.onclick = function(event) {
          if (event.target.closest('input, button, select, textarea, label')) return;
          setActiveStructureGroup(config.kind, card.dataset[prefix + 'GroupItem']);
          renderStructureModal(config.kind);
        };
      });

      bindStructureCategoryExtras(config.kind, categoryList);

      categoryList.querySelectorAll('[data-move-' + prefix + '-group]').forEach(function(btn) {
        btn.onclick = function() {
          const group = cleanGroupName(btn.dataset['move' + prefix.charAt(0).toUpperCase() + prefix.slice(1) + 'Group']);
          const direction = btn.dataset.moveDirection === 'up' ? 'up' : 'down';
          const nextOrder = reorderStructureGroups(structureGroupsForModal(month, config.kind), group, direction);
          setPendingStructureOrder(config.kind, nextOrder);
          setActiveStructureGroup(config.kind, group);
          renderStructureModal(config.kind);
        };
      });

      categoryList.querySelectorAll('[data-' + prefix + '-group-name]').forEach(function(input) {
        input.onchange = function() {
          const oldName = cleanGroupName(input.dataset[prefix + 'GroupName']);
          if (isSharedExpensesIncomeGroup(config.kind, oldName)) { renderStructureModal(config.kind); return; }
          const nextName = cleanGroupName(input.value);
          if (!nextName || nextName === oldName) { renderStructureModal(config.kind); return; }
          if (structureHasGroup(month, config.kind, nextName, oldName)) {
            alert('A category with that name already exists.');
            renderStructureModal(config.kind);
            return;
          }
          renameStructureGroupInMonth(month, config.kind, oldName, nextName);
          renderStructureModal(config.kind);
        };
      });

      categoryList.querySelectorAll('[data-remove-' + prefix + '-group]').forEach(function(btn) {
        btn.onclick = function() {
          const group = cleanGroupName(btn.dataset['remove' + prefix.charAt(0).toUpperCase() + prefix.slice(1) + 'Group']);
          if (isSharedExpensesIncomeGroup(config.kind, group)) { renderStructureModal(config.kind); return; }
          if (!confirm(structureRemoveGroupConfirmMessage(config.kind, group))) return;
          removeStructureGroupInMonth(month, config.kind, group);
          renderStructureModal(config.kind);
        };
      });

      subcategoryList.querySelectorAll('[data-' + prefix + '-row-name]').forEach(function(input) {
        input.onchange = function() {
          const row = config.rows(month).find(function(item) { return item.id === input.dataset[prefix + 'RowName']; });
          if (!row) return;
          if (config.kind === 'income' && isSharedExpensesIncomeRow(row)) { renderStructureModal(config.kind); return; }
          const nextName = String(input.value || '').trim();
          if (!nextName) { renderStructureModal(config.kind); return; }
          row.name = nextName;
          renderStructureModal(config.kind);
        };
      });

      bindStructureSubcategoryExtras(config.kind, month, subcategoryList);

      subcategoryList.querySelectorAll('[data-remove-' + prefix + '-row]').forEach(function(btn) {
        btn.onclick = function() {
          const row = config.rows(month).find(function(item) { return item.id === btn.dataset['remove' + prefix.charAt(0).toUpperCase() + prefix.slice(1) + 'Row']; });
          if (!row) return;
          if (config.kind === 'income' && isSharedExpensesIncomeRow(row)) { renderStructureModal(config.kind); return; }
          if (!confirm('Remove sub-category "' + row.name + '"?')) return;
          config.setRows(month, config.rows(month).filter(function(item) { return item.id !== row.id; }));
          config.ensureMonthStructure(month);
          renderStructureModal(config.kind);
        };
      });
    }

    function wireExpenseTabActionButtons() {
      const manageExpensesBtn = document.getElementById("manageExpensesBtn");
      if (manageExpensesBtn) {
        manageExpensesBtn.onclick = function(event) {
          event.preventDefault();
          openStructureModal("expense");
        };
      }
      const specialFundingConfigBtn = document.getElementById("specialFundingConfigBtn");
      if (specialFundingConfigBtn) {
        specialFundingConfigBtn.onclick = function(event) {
          event.preventDefault();
          openSpecialFundingSourceModal();
        };
      }
      const expenseCsvImportBtn = document.getElementById("expenseCsvImportBtn");
      if (expenseCsvImportBtn) {
        expenseCsvImportBtn.onclick = function(event) {
          event.preventDefault();
          if (typeof window.openCsvImportHistory === "function") {
            window.openCsvImportHistory();
            return;
          }
          const fallback = document.getElementById("csvImportHistoryBtn");
          if (fallback && fallback !== expenseCsvImportBtn) fallback.click();
        };
      }
      const expenseCreditCardsBtn = document.getElementById("expenseCreditCardsBtn");
      if (expenseCreditCardsBtn) {
        expenseCreditCardsBtn.onclick = function(event) {
          event.preventDefault();
          const fallback = document.getElementById("ccManagerBtn");
          if (fallback && fallback !== expenseCreditCardsBtn) fallback.click();
        };
      }
    }

    function openStructureModal(kind) {
      const config = structureKindConfig(kind);
      const modal = document.getElementById(config.modalId);
      if (!modal) return;
      const month = getActiveMonth();
      structureDraftByKind[config.kind] = cloneStructureMonth(month);
      structureCategoryIconDraftByKind[config.kind] = Object.assign({}, categoryIconDraftMap(config.kind));
      setActiveStructureGroup(config.kind, selectedStructureGroup(structureDraftByKind[config.kind], config.kind));
      setPendingStructureOrder(config.kind, config.groups(structureDraftByKind[config.kind]));
      modal.hidden = false;
      renderStructureModal(config.kind);
    }

    function discardStructureDraft(kind) {
      const config = structureKindConfig(kind);
      structureDraftByKind[config.kind] = null;
      structureCategoryIconDraftByKind[config.kind] = null;
      clearPendingStructureOrder(config.kind);
    }

    function flushStructureDraftInputs(kind) {
      const config = structureKindConfig(kind);
      const modal = document.getElementById(config.modalId);
      const month = getStructureEditingMonth(config.kind);
      if (!modal || modal.hidden || !month) return;

      modal.querySelectorAll('[data-' + config.prefix + '-group-name]').forEach(function(input) {
        const oldName = cleanGroupName(input.dataset[config.prefix + 'GroupName']);
        if (isSharedExpensesIncomeGroup(config.kind, oldName)) return;
        const nextName = cleanGroupName(input.value);
        if (!nextName || nextName === oldName) return;
        if (structureHasGroup(month, config.kind, nextName, oldName)) return;
        renameStructureGroupInMonth(month, config.kind, oldName, nextName);
      });

      modal.querySelectorAll('[data-' + config.prefix + '-row-name]').forEach(function(input) {
        const row = config.rows(month).find(function(item) { return item.id === input.dataset[config.prefix + 'RowName']; });
        if (!row) return;
        if (config.kind === 'income' && isSharedExpensesIncomeRow(row)) return;
        const nextName = String(input.value || '').trim();
        if (!nextName) return;
        row.name = nextName;
      });

      if (config.kind === 'expense') {
        modal.querySelectorAll('[data-expense-row-type]').forEach(function(select) {
          const row = (month.expenses || []).find(function(item) { return item.id === select.dataset.expenseRowType; });
          if (!row) return;
          row.fixed = select.value === 'FIXED';
          row.type = row.fixed ? 'FIXED' : 'VARIABLE';
          if (!row.fixed) row.planned = 0;
        });
        modal.querySelectorAll('[data-expense-row-planned]').forEach(function(input) {
          const row = (month.expenses || []).find(function(item) { return item.id === input.dataset.expenseRowPlanned; });
          if (!row || !row.fixed) return;
          row.planned = Math.max(0, Number(input.value || 0));
        });
      }

      if (config.kind === 'savings') {
        modal.querySelectorAll('[data-savings-row-classification]').forEach(function(select) {
          const row = rowPoolForKind(month, 'savings').find(function(item) { return item.id === select.dataset.savingsRowClassification; });
          if (!row) return;
          row.classification = select.value === 'investment' ? 'investment' : 'savings';
        });
      }

      config.ensureMonthStructure(month);
      const selected = selectedStructureGroup(month, config.kind);
      const ordered = structureGroupsForModal(month, config.kind);
      setPendingStructureOrder(config.kind, ordered);
      setActiveStructureGroup(config.kind, selected);
    }

    function saveStructureModal(kind) {
      const config = structureKindConfig(kind);
      const modal = document.getElementById(config.modalId);
      const draftMonth = structureDraftByKind[config.kind];
      if (!draftMonth) {
        if (modal) modal.hidden = true;
        return;
      }
      flushStructureDraftInputs(config.kind);
      if (getPendingStructureOrder(config.kind)) applyPendingStructureOrder(draftMonth, config.kind);
      if (modal) modal.hidden = true;
      const didCommit = commitStructureDraft(config.kind);
      if (didCommit) render('rows');
      else {
        saveState(state);
        updateHistoryButtons();
      }
    }

    function cancelStructureModal(kind) {
      const config = structureKindConfig(kind);
      const modal = document.getElementById(config.modalId);
      if (modal) modal.hidden = true;
      discardStructureDraft(config.kind);
      saveState(state);
      updateHistoryButtons();
    }

function captureExpenseModalSubcatScroll() {
      const list = document.querySelector('.expense-subcat-list');
      return list ? list.scrollTop : 0;
    }

    function restoreExpenseModalSubcatScroll(scrollTop) {
      if (!Number.isFinite(scrollTop)) return;
      requestAnimationFrame(function() {
        const list = document.querySelector('.expense-subcat-list');
        if (list) list.scrollTop = scrollTop;
      });
    }

function render(hint) {
      // ── Selective rendering ─────────────────────────────────────────────
      // hint = undefined  → full render (month switch, undo/redo, import)
      // hint = 'overview' → summary + overview + insights only
      // hint = 'rows'     → active-view rows + summary only
      // hint = 'subs'     → subscriptions + summary only
      // hint = 'planning' → planning tools only
      // hint = 'insights' → insights only
      //
      // All paths still call propagateLinkedRollovers + syncDerivedRows first
      // so derived values are always fresh before any sub-render runs.
      // ────────────────────────────────────────────────────────────────────

      propagateLinkedRollovers();
      const month = getActiveMonth();
      syncDerivedRows(month);
      ensureDebtState(state);

      // ── Shared header (always cheap, always run) ──────────────────────
      document.getElementById("monthTitle").textContent = month.name;

      // ── Selective paths ───────────────────────────────────────────────
      if (hint === 'month-switch') {
        renderActiveMonthView(month);
        return;
      }

      if (hint === 'overview') {
        renderFinStateBanner(month);
        renderSummary(month);
        renderOverview(month);
        renderCategoryTrends(month);
        renderSpendingChart(month);
        try { renderInsights(month); } catch(e) { console.error('Insights render failed', e); }
        requestAnimationFrame(alignSmartInsightCards);
        saveState(state);
        updateHistoryButtons();
        return;
      }

      if (hint === 'rows') {
        const expenseModalSubcatScrollTop = openExpenseModalGroup ? captureExpenseModalSubcatScroll() : 0;
        renderFinStateBanner(month);
        renderSummary(month);
        renderIncomeSavingsHero(month);
        renderRows("incomeList", month.income, "income");
        renderRows("savingsList", month.savings, "savings");
        syncSavingsBudgetModal();
        renderRows("expenseList", month.expenses, "expenses");
        wireExpenseTabActionButtons();
        if (openExpenseModalGroup) restoreExpenseModalSubcatScroll(expenseModalSubcatScrollTop);
        // Also refresh overview so KPIs stay in sync with row changes
        renderOverview(month);
        renderCategoryTrends(month);
        renderSpendingChart(month);
        try { renderInsights(month); } catch(e) { console.error('Insights render failed', e); }
        // Subscription burden depends on ledger matches, so refresh it after CSV/PDF/manual row changes.
        try { renderSubscriptions(month); } catch(e) { console.error('Subscriptions render failed', e); }
        // Refresh goal tracking so progress reflects newly added transactions
        try { renderPlanningTools(month); } catch(e) { console.error('Planner render failed', e); }
        if (typeof renderedMonthByView === 'object' && renderedMonthByView) delete renderedMonthByView.debt;
        if (activeView === 'debt' && typeof renderDebtTab === 'function') renderDebtTab(month);
        requestAnimationFrame(alignSmartInsightCards);
        saveState(state);
        updateHistoryButtons();
        return;
      }

      if (hint === 'subs') {
        renderFinStateBanner(month);
        renderSummary(month);
        renderSubscriptions(month);
        renderRows("expenseList", month.expenses, "expenses");
        wireExpenseTabActionButtons();
        renderOverview(month);
        try { renderInsights(month); } catch(e) { console.error('Insights render failed', e); }
        requestAnimationFrame(alignSmartInsightCards);
        saveState(state);
        updateHistoryButtons();
        return;
      }

      if (hint === 'planning') {
        try { renderPlanningTools(month); } catch(e) { console.error('Planner render failed', e); }
        saveState(state);
        updateHistoryButtons();
        return;
      }

      if (hint === 'goals') {
        try { if (typeof renderFinancialGoalsTab === 'function') renderFinancialGoalsTab(month); } catch(e) { console.error('Financial Goals render failed', e); }
        saveState(state);
        updateHistoryButtons();
        return;
      }

      if (hint === 'insights') {
        try { renderInsights(month); } catch(e) { console.error('Insights render failed', e); }
        requestAnimationFrame(alignSmartInsightCards);
        saveState(state);
        updateHistoryButtons();
        return;
      }

      // ── Full render (no hint, or unrecognised hint) ───────────────────
      renderMonths();
      renderFinStateBanner(month);
      renderSummary(month);
      standardizeModalUi();
      try {
        renderInsights(month);
      } catch (error) {
        console.error("Insights render failed", error);
        const wrap = document.getElementById("insightGrid");
        if (wrap) {
          wrap.innerHTML = `<section class="insight-card">${renderUnifiedCardHeader({ title: 'Insights' })}<div class="empty">Insights are temporarily unavailable. Budget views remain available.</div></section>`;
        }
      }
      requestAnimationFrame(alignSmartInsightCards);
      try {
        renderPlanningTools(month);
      } catch (error) {
        console.error("Planner render failed", error);
      }
      renderCategoryTrends(month);
      renderSpendingChart(month);
      renderIncomeSavingsHero(month);
      renderRows("incomeList", month.income, "income");
      renderRows("savingsList", month.savings, "savings");
      syncSavingsBudgetModal();
      renderRows("expenseList", month.expenses, "expenses");
      wireExpenseTabActionButtons();
      renderOverview(month);
      if (typeof renderFinancialGoalsTab === 'function') renderFinancialGoalsTab(month);
      renderSubscriptions(month);
      updateAllRowSectionCounts(month);
      const manageIncomeBtn = document.getElementById("manageIncomeBtn");
      if (manageIncomeBtn) manageIncomeBtn.onclick = function(event) { event.preventDefault(); openStructureModal("income"); };
      const manageSavingsBtn = document.getElementById("manageSavingsBtn");
      if (manageSavingsBtn) manageSavingsBtn.onclick = function(event) { event.preventDefault(); openStructureModal("savings"); };
      const manageSavingsBudgetBtn = document.getElementById("manageSavingsBudgetBtn");
      if (manageSavingsBudgetBtn) manageSavingsBudgetBtn.onclick = function(event) { event.preventDefault(); openSavingsBudgetModal(); };
      wireExpenseTabActionButtons();
      renderStructureModal("income");
      renderStructureModal("savings");
      renderStructureModal("expense");
      markAllPrimaryViewsRendered(month);
      wireViewNav();
      setActiveView(activeView);
      saveState(state);
      updateHistoryButtons();
    }
    function nextMonthName(currentName) {
      const monthNames = ["January","February","March","April","May","June","July","August","September","October","November","December"];
      const match = currentName.match(/([A-Za-z]+)\s+(\d{4})/);
      if (!match) return currentName + " Copy";
      let idx = monthNames.indexOf(match[1]); let year = Number(match[2]);
      if (idx === -1) return currentName + " Copy";
      idx += 1; if (idx > 11) { idx = 0; year += 1; }
      return `${monthNames[idx]} ${year}`;
    }
